/* ────────────────────────────────────────────────────��────────────────────
   Helpers
   ───���───────────────────────────────��───────────��───────────────────────── */

function detectSessionMode(s: typeof AI_CHECKIN.sessionInfo): SessionMode {
  if (s.isOpen) return "in_session"
  const m = parseInt(s.opensIn) || 999
  if (m <= 120) return "pre_market"
  return "post_session"
}

/** Magnitude / precision split — the signature Vantary numeric trick.
 *  "12,480" -> lead "12," in semibold paper, tail "480" in light ash. */
function splitMagnitude(value: string): { lead: string; tail: string } {
  // strip currency / sign chars off the front
  const m = value.match(/^([^\d-]*)([\d,]+)(.*)$/)
  if (!m) return { lead: value, tail: "" }
  const [, prefix, digits, suffix] = m
  // split digits roughly in half — first half bold, second half light
  const half = Math.ceil(digits.replace(/,/g, "").length / 2)
  let walked = 0
  let cut = 0
  for (let i = 0; i < digits.length; i++) {
    if (digits[i] !== ",") walked += 1
    if (walked >= half) { cut = i + 1; break }
  }
  // ensure cut lands after a digit, not on the comma boundary
  while (cut < digits.length && digits[cut] === ",") cut += 1
  return {
    lead: prefix + digits.slice(0, cut),
    tail: digits.slice(cut) + suffix,
  }
}

/* ────────────���───────────────────────�����───��────────────────────────────────
   <ProtagonistNumber> — the magnitude/precision hero numeral.
   Used on every primary metric ($12,480 / 67.3% / 72/100 / ±2.1R).
   ───────────────────────────────────────────────────────────────────────── */

function ProtagonistNumber({
  value, suffix, size = 64, hover = false,
}: { value: string; suffix?: string; size?: number; hover?: boolean }) {
  const { lead, tail } = useMemo(() => splitMagnitude(value), [value])
  return (
    <div className="inline-flex items-baseline gap-1.5 select-none">
      <span
        className="font-sans transition-[text-shadow] duration-500"
        style={{
          fontSize: size,
          lineHeight: 0.95,
          letterSpacing: "-0.025em",
          fontWeight: 600,
          color: VANTARY.paper,
          textShadow: hover ? CHROMA_SHADOW : CHROMA_SHADOW_LO,
        }}
      >
        {lead}
      </span>
      {tail && (
        <span
          className="font-sans"
          style={{
            fontSize: size,
            lineHeight: 0.95,
            letterSpacing: "-0.025em",
            fontWeight: 200,
            color: VANTARY.ash,
          }}
        >
          {tail}
        </span>
      )}
      {suffix && (
        <span
          className="font-sans"
          style={{
            fontSize: Math.round(size * 0.28),
            color: VANTARY.ash,
            fontWeight: 400,
            marginLeft: 4,
          }}
        >
          {suffix}
        </span>
      )}
    </div>
  )
}

/* ──────────────���──────────────────������───────────────────────────────────────
   <Bloom> ��� atmospheric amber bloom that lives behind active hero cards.
   Reference: image #11 amber capsule, image #14 frosted overlay.
   �����────────────────────��────────����������������───────────────────────────���────────── */

function Bloom({ size = 320, opacity = 0.18, breath = true }: {
  size?: number; opacity?: number; breath?: boolean
}) {
  return (
    <motion.div
      aria-hidden
      className="absolute pointer-events-none"
      style={{
        top: "50%", left: "50%",
        width: size, height: size,
        transform: "translate(-50%,-50%)",
        background: `radial-gradient(circle, rgba(var(--vt-primary-rgb, 45, 212, 191),${opacity}) 0%, rgba(var(--vt-primary-rgb, 45, 212, 191),${opacity * 0.4}) 35%, transparent 70%)`,
        filter: "blur(40px)",
        zIndex: 0,
      }}
      animate={breath ? { opacity: [0.55, 1, 0.55], scale: [0.95, 1.05, 0.95] } : undefined}
      transition={breath ? { duration: 6, repeat: Infinity, ease: "easeInOut" } : undefined}
    />
  )
}

/* ───────────────────────────────────────────────────��─────────────────────
   <CardShell> — the universal Vantary card. Glass, hairline, radius 24,
   atmospheric bloom on hover, hairline corner mark, optional ↗ deep-link.
   ───────────────────────────────────────────────────────────────────────── */

function CardShell({
  children, title, eyebrow, deepLink, onDeepLink, padding = 24, className = "",
  bloomOnHover = true, severity = "neutral",
}: {
  children: React.ReactNode
  title?: string
  eyebrow?: string
  deepLink?: boolean
  onDeepLink?: () => void
  padding?: number
  className?: string
  bloomOnHover?: boolean
  severity?: "neutral" | "warning"
}) {
  const [hover, setHover] = useState(false)
  const isWarn = severity === "warning"

  return (
    <motion.section
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      className={`relative overflow-hidden ${className}`}
      style={{
        background: isWarn ? VANTARY.warnWash : (hover ? VANTARY.glassStrong : VANTARY.glass),
        border:     `1px solid ${isWarn ? VANTARY.warnEdge : (hover ? VANTARY.ruleStrong : VANTARY.rule)}`,
        borderRadius: RADIUS_V.card,
        backdropFilter: "blur(24px) saturate(140%)",
        WebkitBackdropFilter: "blur(24px) saturate(140%)",
        transition: "background 400ms, border-color 400ms",
      }}
      whileHover={{ y: -2 }}
      transition={{ duration: 0.5, ease: EASE_V }}
    >
      {bloomOnHover && (
        <AnimatePresence>
          {hover && (
            <motion.div
              key="bloom"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 pointer-events-none"
            >
              <Bloom size={420} opacity={0.14} breath={false} />
            </motion.div>
          )}
        </AnimatePresence>
      )}

      <div className="relative" style={{ padding, zIndex: 1 }}>
        {(title || eyebrow || deepLink) && (
          <header className="flex items-start justify-between mb-4">
            <div className="flex flex-col gap-1">
              {eyebrow && (
                <span
                  className="font-mono uppercase"
                  style={{
                    fontSize: 10, letterSpacing: "0.18em",
                    color: VANTARY.ashSoft,
                  }}
                >
                  {eyebrow}
                </span>
              )}
              {title && (
                <h3
                  className="font-sans"
                  style={{
                    fontSize: 15, fontWeight: 500,
                    color: VANTARY.paper, letterSpacing: "-0.005em",
                  }}
                >
                  {title}
                </h3>
              )}
            </div>
            {deepLink && (
              <button
                onClick={onDeepLink}
                aria-label="Open deeper view"
                className="opacity-50 hover:opacity-100 transition-opacity"
              >
                <ArrowUpRight size={16} strokeWidth={1.5} color={VANTARY.paper} />
              </button>
            )}
          </header>
        )}
        {children}
      </div>
    </motion.section>
  )
}

/* ═════════════════════════════════════════════════════════════════════════
   FLIGHT-DECK SECTION HEADER
   ────────────────────────����─────────����������──────────────────────────────────────
   Reusable, doctrine-aligned section header used at the top of major
   blocks (Accounts, Watchlist, Macro, Strategies …).

   Layout (left → right, single row):
     · breathing primary pulse + eyebrow code   (e.g. "ACCOUNTS · ASSET REGISTER")
     · big display title                        (the human-friendly heading)
     · dashed connector rule                    (fills available space)
     · status code chip                         (e.g. "5 ACTIVE · LIVE")
     · live UTC tick                            (HH:MM:SS, second-tick)
     · optional `right` slot                    (chips, command-palette hint)

   This is the visual grammar borrowed from the Ron Design "Traffic
   Management" reference: hairline rules, dashed connectors, breathing
   status pip, live UTC tick, and small-caps mono codes pinned to a
   larger sans heading.
   ───────────────────────────────────────────────────────────────────────── */

function FlightDeckSectionLiveTick({
  size = 9.5,
  label = "UTC",
}: { size?: number; label?: string }) {
  const sec = useUTCSecondClock()
  const hh = sec.getUTCHours().toString().padStart(2, "0")
  const mm = sec.getUTCMinutes().toString().padStart(2, "0")
  const ss = sec.getUTCSeconds().toString().padStart(2, "0")
  return (
    <span className="inline-flex items-center gap-1.5 shrink-0">
      <motion.span
        aria-hidden
        className="rounded-full"
        style={{
          width: 5, height: 5,
          background: VANTARY.amber,
          boxShadow: `0 0 6px ${VANTARY.amberHalo}`,
        }}
        animate={{ opacity: [0.45, 1, 0.45], scale: [0.92, 1.08, 0.92] }}
        transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
      />
      <span
        className="font-mono uppercase tabular-nums"
        style={{ fontSize: size, letterSpacing: "0.16em", color: VANTARY.ashSoft, fontWeight: 500 }}
      >
        {label} · {hh}:{mm}:{ss}
      </span>
    </span>
  )
}

function FlightDeckSectionHeader({
  eyebrow,
  title,
  status,
  right,
}: {
  /** Small-caps eyebrow code (e.g. "ACCOUNTS · ASSET REGISTER"). */
  eyebrow: string
  /** Display title — the big sans heading. */
  title: string
  /** Optional status code shown as a tinted chip on the right. */
  status?: string
  /** Optional right-side slot for chips / palette hints. */
  right?: React.ReactNode
}) {
  return (
    <header className="mb-4">
      {/* Top row — eyebrow + dashed connector + status + UTC tick + right slot */}
      <div className="flex items-center gap-3 mb-2">
        <div className="flex items-center gap-2 shrink-0">
          <motion.span
            aria-hidden
            className="rounded-full"
            style={{
              width: 6, height: 6,
              background: VANTARY.amber,
              boxShadow: `0 0 8px ${VANTARY.amberHalo}`,
            }}
            animate={{ opacity: [0.55, 1, 0.55], scale: [0.92, 1.1, 0.92] }}
            transition={{ duration: 1.7, repeat: Infinity, ease: "easeInOut" }}
          />
          <span
            className="font-mono uppercase"
            style={{
              fontSize: 9.5,
              letterSpacing: "0.24em",
              color: VANTARY.amber,
              fontWeight: 600,
            }}
          >
            {eyebrow}
          </span>
        </div>

        <span
          aria-hidden
          className="flex-1 h-px"
          style={{
            background: `repeating-linear-gradient(90deg, ${VANTARY.rule} 0 4px, transparent 4px 8px)`,
          }}
        />

        {status && (
          <span
            className="font-mono uppercase shrink-0"
            style={{
              fontSize: 9,
              letterSpacing: "0.20em",
              color: VANTARY.paperDim,
              padding: "2px 8px",
              border: `1px solid ${VANTARY.ruleSoft}`,
              borderRadius: 999,
              background: "rgba(255,255,255,0.025)",
            }}
          >
            {status}
          </span>
        )}

        <FlightDeckSectionLiveTick size={9} />
        {right}
      </div>

      {/* Big display title — paired with a graduated underline */}
      <h2
        className="font-sans"
        style={{
          fontSize: 22,
          color: VANTARY.paper,
          fontWeight: 500,
          letterSpacing: "-0.018em",
          lineHeight: 1.1,
        }}
      >
        {title}
      </h2>
      <div
        aria-hidden
        className="mt-2"
        style={{
          height: 1,
          background: `linear-gradient(90deg, ${VANTARY.amber} 0%, ${VANTARY.amberHalo} 22%, ${VANTARY.rule} 60%, transparent 100%)`,
          opacity: 0.75,
        }}
      />
    </header>
  )
}

/* ────────────────────────────────────────────────────────────────────����������────
   <Chip> — the universal Vantary pill. Used for Bus 6023 / Map 2 / Online.
   ─────────────────────────────────────────��─���────────────────────���──────── */

function Chip({
  children, active = false, leading, trailing, onClick, size = "md",
}: {
  children: React.ReactNode
  active?: boolean
  leading?: React.ReactNode
  trailing?: React.ReactNode
  onClick?: () => void
  size?: "sm" | "md"
}) {
  const px = size === "sm" ? 10 : 14
  const py = size === "sm" ? 5 : 7
  const fs = size === "sm" ? 11 : 12
  return (
    <button
      type="button"
      onClick={onClick}
      className="inline-flex items-center gap-1.5 transition-all duration-300 hover:bg-white/[0.08]"
      style={{
        ...vantaryChip(active),
        padding: `${py}px ${px}px`,
        fontSize: fs,
        fontFamily: "inherit",
      }}
    >
      {leading}
      <span style={{ color: active ? VANTARY.paper : VANTARY.paperDim }}>{children}</span>
      {trailing}
    </button>
  )
}

/* ═════�����═════════════════════�����════════════════════════��═════════════════��══����������
 * ╔═══════════════════════════════════════�������════════════�������══����═══════════════╗
 * ║                                                                       ║
 * ║         T H E   D U A L - S T A G E   D E C K                         ║
 * ║         ──────��───────��───────��───────────────                        ║
 * ║                                                                       ║
 * ��   "Two halves. Either can swallow the room."                          ║
 * ║                                                                       ║
 * ║   The signature horizontal row that lives directly below the          ║
 * ║   trader's briefing. Composition:                                     ║
 * ║                                                                       ║
 * ���     ���──────���─��──────────��─���──┬────────────────��───────���               ║
 * ║     ����  LIVE EQUITY VOLUME    │   ACTIVE WINDOWS       │               ║
 * ║     │  (left, 50%)           │   (right, 50%)         │               ║
 * ║     └────────────────────────┴────────────────────────┘               ║
 * ║                                                                       ║
 * ║   Click EITHER stage and that stage smoothly expands to fill 100%     ║
 * ║   of the row, while the other collapses to 0%. Clicking the back     ║
 * ║   chip (or pressing Escape) restores the 50/50 deck.                  ║
 * ║                                                                       ║
 * ║   Layout state machine:                                               ║
 * ║                                                                       ║
 * ║       focused = null         →   1fr 1fr        (50 / 50)             ║
 * ║       focused = "equity"     →   1fr 0fr        (100 / 0)             ║
 * ║       focused = "sessions"   →   0fr 1fr        (0 / 100)             ║
 * ║                                                                       ║
 * ║   Animation primitive: CSS Grid `grid-template-columns` transition.   ║
 * ║   Modern browsers animate this natively, giving a buttery-smooth      ║
 * ║   silk-curtain effect that no flexbox hack can match.                 ║
 * ║                                                                       ║
 * ║   PSYCHOLOGY OF EXCITEMENT (the "click me!" choreography):            ║
 * ║                                                                       ║
 * ║   1. IDLE PULSE — every 6 seconds, a soft amber shimmer wipes         ║
 * ║      diagonally across each idle stage, telegraphing interactivity    ║
 * ║      without screaming.                                               ║
 * ║                                                                       ║
 * ║   2. HOVER ENTRANCE — within 180 ms the border tints amber, the       ║
 * ║      background gains an amber wash, a 1 px accent strip races        ║
 * ║      across the top edge from the inside-out, and a small "↗ EXPAND"  ║
 * ║      pill fades in at the top-right corner.                           ║
 * ║                                                                       ║
 * ║   3. PARALLAX TILT — while hovering, the entire stage tracks the      ║
 * ║      cursor's X position with a ±2° rotateY, giving the surface a     ║
 * ║      subtle "leans toward you" gravity. transformPerspective(1200)    ║
 * ║      keeps the effect cinematic without dizzying.                     ║
 * ║                                                                       ║
 * ║   4. MAGNETIC HEADER — the stage title gains a 4 px amber glow on     ║
 * ║      hover; the eyebrow's status pip enlarges from 5 px to 6 px.      ║
 * ║                                                                       ║
 * ║   5. PRESS — onClick the stage briefly scales to 0.985 then snaps     ║
 * ║      back, communicating commit. The grid transition begins on the    ║
 * ║      same frame so the press and the expansion feel single-gestured.  ║
 * ║                                                                       ║
 * ║   6. SWAP — when focused, the compact view dissolves out and the      ║
 * ║      expanded view dissolves in via AnimatePresence. The expanded     ║
 * ║      view pre-mounts during the grid transition so content is         ║
 * ║      already visible by the time the cell finishes opening.           ║
 * ║                                                                       ║
 * ║   7. RETURN — the back chip in the focused header lights amber on     ║
 * ��      hover, with a tiny "PRESS ESC" whisper next to it. Both pull     ║
 * ║      the user back to the deck without breaking flow.                 ║
 * ║                                                                       ║
 * ║   The takeover panel (when a session puck is clicked) ABSORBS the    ║
 * ║   entire deck row — both stages disappear together, replaced by the   ║
 * ║   full-width <SessionTakeoverPanel/>. This preserves the existing    ║
 * ║   takeover behaviour while keeping the deck's visual contract.       ║
 * ║                                                                       ║
 * ╚═══════════════════════════════════════════════════════════════════════╝
 * ═══════════════════════════════════════════════════════════════════════ */

type DeckFocus = "equity" | "sessions" | null

/* ─────────────────────────────────────────────────────────────────────────
 *  ROTATING PHRASE POOLS — the words that "talk to the trader" while
 *  they sit and look at the deck. Each pool has 12 entries; the header
 *  cycles through them every 6.5 s with a soft crossfade. Titles and
 *  taglines are matched by index — pair 0 of titles always pairs with
 *  pair 0 of taglines so the duo always reads as a single thought.
 *
 *  Tone: editorial, second-person, slightly literary. Designed to feel
 *  like a conversation rather than a metric — the dashboard isn't just
 *  reporting numbers, it's narrating the trader's day back to them.
 * ────────────────────────────────────────�������─��───────────────────���───── */

