/** FOCUS popover — focus pairs with WR/pips/spark + reasoning. */
function FocusPopoverContent({ plan }: { plan: typeof DAILY_PLAN }) {
  const reduce = useReducedMotion() ?? false
  // Build mini bars for each focus pair using the shared candle generator pattern.
  // We approximate with a small synthesized walk so the popover always has a spark.
  const focusRows = plan.focusPairs.map((sym, i) => {
    const wr = sym === "EUR/USD" ? PERFORMANCE.bestPair.winRate : sym === "XAU/USD" ? 68 : 60
    const pips = sym === "EUR/USD" ? 18 : sym === "XAU/USD" ? 42 : 0
    // synth bars
    const bars: { o: number; h: number; l: number; c: number }[] = []
    let last = 100
    let s = 11 + i * 7
    const rand = () => {
      s = (s * 9301 + 49297) % 233280
      return s / 233280
    }
    for (let j = 0; j < 14; j++) {
      const o = last
      const dir = rand() > 0.4 ? 1 : -1
      const c = o + dir * (rand() * 0.6)
      const h = Math.max(o, c) + rand() * 0.2
      const l = Math.min(o, c) - rand() * 0.2
      bars.push({ o, h, l, c })
      last = c
    }
    return { sym, wr, pips, bars, positive: pips >= 0 }
  })

  return (
    <>
      <HoverPreviewPopover.Header
        subject="TODAY'S FOCUS"
        value={`${plan.focusPairs.length} pairs in scope`}
        meta="London bias"
      />
      <HoverPreviewPopover.Body>
        <div className="pb-1">
          <InstrumentFrame
            label="FOCUS CONSTELLATION"
            reading={`${plan.focusPairs.length} PAIRS`}
            tint={VANTARY.teal}
            height={84}
          >
            <PairConstellation
              pairs={focusRows.map((r) => ({ sym: r.sym, wr: r.wr, positive: r.positive }))}
              reduce={reduce}
            />
          </InstrumentFrame>
        </div>
        <div className="flex flex-col gap-1.5">
          {focusRows.map((r) => (
            <div
              key={r.sym}
              className="flex items-center gap-2.5 px-1.5 py-1.5 rounded-md"
              style={{ background: "rgba(6,182,212,0.04)" }}
            >
              <div className="flex flex-col gap-0.5 min-w-0 flex-1">
                <span className="font-mono" style={{ fontSize: 11, color: VANTARY.paper, fontWeight: 600, letterSpacing: "0.02em" }}>
                  {r.sym}
                </span>
                <div className="flex items-center gap-2" style={{ fontSize: 9.5, color: VANTARY.ash }}>
                  <span>WR {r.wr}%</span>
                  <span style={{ color: VANTARY.rule }}>·</span>
                  <span style={{ color: r.positive ? VANTARY.chartUp : VANTARY.chartDown, fontWeight: 500 }}>
                    {r.positive ? "+" : ""}
                    {r.pips} pips
                  </span>
                </div>
              </div>
              <MiniSpark bars={r.bars} positive={r.positive} />
            </div>
          ))}
        </div>
        <HoverPreviewPopover.Divider />
        <div className="flex flex-col gap-1 mt-1">
          <span
            className="font-mono uppercase"
            style={{ fontSize: 8.5, letterSpacing: "0.18em", color: VANTARY.ashSoft }}
          >
            Why these pairs
          </span>
          <p style={{ fontSize: 10.5, lineHeight: 1.5, color: VANTARY.paperDim, margin: 0 }}>
            {plan.aiSuggestion}
          </p>
        </div>
      </HoverPreviewPopover.Body>
      <HoverPreviewPopover.Footer>
        <HoverPreviewPopover.ActionButton affordance="navigate">
          Edit focus list
        </HoverPreviewPopover.ActionButton>
      </HoverPreviewPopover.Footer>
    </>
  )
}

/** NEWS popover — next event with countdown + plan rule + queue. */
function NewsPopoverContent({ plan }: { plan: typeof DAILY_PLAN }) {
  const reduce = useReducedMotion() ?? false
  const now = useNowUTC()
  const next = plan.macroEvents[0]
  const ms = msUntilUTC(now, next.time)
  const sec = ms / 1000
  const totalWindow = 60 * 60 // ring fills over the last hour
  const pct = 1 - Math.min(1, sec / totalWindow)
  const impactTint =
    next.impact === "high" ? VANTARY.chartDown : next.impact === "medium" ? VANTARY.amber : VANTARY.ash

  return (
    <>
      <HoverPreviewPopover.Header
        subject="NEXT MACRO"
        value={next.event}
        meta={`${next.currency} · ${next.time} UTC`}
      />
      <HoverPreviewPopover.Body>
        <div className="flex items-center gap-3 py-1">
          <div style={{ width: 84, flexShrink: 0 }}>
            <InstrumentFrame
              label="IMPACT SONAR"
              reading={fmtCountdown(sec)}
              tint={impactTint}
              height={84}
            >
              <ImpactSonar pct={pct} tint={impactTint} reduce={reduce} />
            </InstrumentFrame>
          </div>
          <div className="flex-1 flex flex-col gap-1">
            <HoverPreviewPopover.Row
              label="Impact"
              value={next.impact.toUpperCase()}
              tone={next.impact === "high" ? "negative" : next.impact === "medium" ? "warn" : "muted"}
            />
            <HoverPreviewPopover.Row label="Currency" value={next.currency} />
            <HoverPreviewPopover.Row
              label="Affects"
              value={plan.focusPairs.filter((p) => p.includes(next.currency)).join(" · ") || "—"}
              tone="muted"
            />
          </div>
        </div>
        <HoverPreviewPopover.Divider />
        <div
          className="flex items-start gap-2 p-2.5 rounded-md mt-1"
          style={{
            background: "rgba(239,68,68,0.07)",
            border: `1px solid rgba(239,68,68,0.16)`,
          }}
        >
          <ShieldAlert size={12} strokeWidth={2} style={{ color: VANTARY.chartDown, marginTop: 1, flexShrink: 0 }} />
          <span style={{ fontSize: 10.5, lineHeight: 1.45, color: VANTARY.paperDim }}>
            <strong style={{ color: VANTARY.paper, fontWeight: 600 }}>Plan rule:</strong>{" "}
            {plan.personalRules.find((r) => r.toLowerCase().includes("news")) ?? "No trading 30min before high-impact news"}
          </span>
        </div>
        {plan.macroEvents.length > 1 && (
          <>
            <HoverPreviewPopover.Divider />
            <div className="flex flex-col gap-1.5 mt-1">
              <span
                className="font-mono uppercase"
                style={{ fontSize: 8.5, letterSpacing: "0.18em", color: VANTARY.ashSoft }}
              >
                Today's queue
              </span>
              {plan.macroEvents.slice(1).map((e, i) => (
                <HoverPreviewPopover.Row
                  key={i}
                  label={`${e.time} · ${e.event}`}
                  value={e.impact.toUpperCase()}
                  tone={e.impact === "high" ? "negative" : e.impact === "medium" ? "warn" : "muted"}
                />
              ))}
            </div>
          </>
        )}
      </HoverPreviewPopover.Body>
      <HoverPreviewPopover.Footer>
        <HoverPreviewPopover.ActionButton affordance="navigate">
          Open macro sheet
        </HoverPreviewPopover.ActionButton>
      </HoverPreviewPopover.Footer>
    </>
  )
}

/* ���────���──���─���──������─���─���────────────────�������───────────────────────────────────
   The capsule trigger — a tight inline DrillCard used by all six.
   ───────────────────────────────────────────────────────────────����───��───��─ */

interface CapsuleProps {
  eyebrow: string
  value: React.ReactNode
  category: "session" | "focus" | "alert" | "macro" | "neutral"
  crossKey: string
  /**
   * Secondary cross-keys this capsule lights up on hover. Lets the top-of-page
   * status strip participate richly in the global cross-highlight network:
   *   • SESSION  ⇒ broadcasts `pair:EUR/USD`, … for the active session's pairs
   *   • FOCUS    �� broadcasts `pair:*` for the user's focus list
   *   • NEWS     ⇒ broadcasts `pair:*` for currencies the event will move
   */
  broadcastKeys?: readonly string[]
  preview: React.ReactNode
  signal?: React.ReactNode // optional micro-visual at the right edge
  delay?: number
}

function TickerCapsule({ eyebrow, value, category, crossKey, broadcastKeys, preview, signal, delay = 0 }: CapsuleProps) {
  const accentRgb =
    category === "session"
      ? "34, 197, 94"
      : category === "focus"
        ? "6, 182, 212"
        : category === "alert"
          ? "251, 146, 60"
          : category === "macro"
            ? "239, 68, 68"
            : "255, 255, 255"

  return (
    <motion.div
      initial={{ opacity: 0, y: -4 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.18 + delay, duration: 0.35, ease: EASE_V }}
      className="shrink-0"
    >
      <DrillCard
        as="button"
        interaction="preview"
        category={category}
        crossKey={crossKey}
        broadcastKeys={broadcastKeys}
        density="compact"
        intent="subtle"
        inline
        previewSide="bottom"
        previewWidth={340}
        preview={preview}
        className="group/cap"
        style={{
          // Override DrillCard's base card surface so it reads as an inline chip on the rail.
          background: "transparent",
          border: "1px solid transparent",
          padding: "5px 9px",
          borderRadius: 8,
          // The internal hover state of DrillCard will lift this; we just need the resting
          // state to sit quietly on the rail.
          ["--dc-hover-bg" as string]: `rgba(${accentRgb}, 0.04)`,
          ["--dc-hover-border" as string]: `rgba(${accentRgb}, 0.14)`,
        }}
      >
        <div className="flex items-center gap-2 whitespace-nowrap">
          {/* Left accent dot — hairline visual signature per category */}
          <span
            aria-hidden="true"
            className="inline-block rounded-full"
            style={{
              width: 4,
              height: 4,
              background: `rgba(${accentRgb}, 0.6)`,
              boxShadow: `0 0 6px rgba(${accentRgb}, 0.5)`,
            }}
          />
          <span
            className="font-mono uppercase"
            style={{ fontSize: 9, letterSpacing: "0.20em", color: VANTARY.ashSoft }}
          >
            {eyebrow}
          </span>
          <span
            className="font-sans whitespace-nowrap"
            style={{ fontSize: 11, color: VANTARY.paperDim, fontWeight: 500 }}
          >
            {value}
          </span>
          {signal}
        </div>
      </DrillCard>
    </motion.div>
  )
}

function CapsuleDivider() {
  return (
    <span
      aria-hidden="true"
      className="shrink-0"
      style={{
        width: 1,
        height: 14,
        background: `linear-gradient(180deg, transparent 0%, ${VANTARY.rule} 50%, transparent 100%)`,
        margin: "0 6px",
      }}
    />
  )
}

/* ─────���───────────────────���────────────────��────────────────────���─────��───
   The strip orchestrator
   ────────────────────────────────��──────────────────────────────────────── */

/**
 * Derive likely-affected pairs from an event's issuer currency. Used by the
 * NEWS capsule to broadcast `pair:*` cross-keys without needing a typed
 * `affectedPairs` field on `DAILY_PLAN.macroEvents`. Matches the pair
 * namespace used by WatchlistMatrix, SessionPuck, MacroRow, and Oracle.
 */
const PAIRS_BY_CURRENCY: Record<string, readonly string[]> = {
  EUR: ["EUR/USD", "EUR/GBP", "EUR/JPY"],
  USD: ["EUR/USD", "USD/JPY", "GBP/USD", "XAU/USD"],
  GBP: ["GBP/USD", "GBP/JPY", "EUR/GBP"],
  JPY: ["USD/JPY", "GBP/JPY", "EUR/JPY"],
  AUD: ["AUD/USD", "AUD/JPY"],
  CAD: ["USD/CAD"],
  CHF: ["USD/CHF", "EUR/CHF"],
}

function TickerStrip({ checkin, plan }: { checkin: typeof AI_CHECKIN; plan: typeof DAILY_PLAN }) {
  const now = useNowUTC()
  const utcHour = now.getUTCHours() + now.getUTCMinutes() / 60
  const activeSession = findActiveSession(utcHour)
  const next = findNextSession(now)
  const liveOpensIn = fmtCountdown(next.deltaH * 3600)

  // Risk + plan tone derivation
  const riskPct = plan.dailyLossUsed / plan.maxDailyLoss
  const riskCategory: "session" | "alert" | "macro" =
    riskPct < 0.33 ? "session" : riskPct < 0.66 ? "alert" : "macro"
  const tradesLeft = plan.maxTrades - plan.tradesUsed
  const tradesCategory: "session" | "alert" | "macro" =
    tradesLeft >= plan.maxTrades ? "session" : tradesLeft > 0 ? "alert" : "macro"

  // News next event countdown (for live ms display in chip)
  const nextEvent = plan.macroEvents[0]
  const newsMs = nextEvent ? msUntilUTC(now, nextEvent.time) : 0
  const newsSec = newsMs / 1000

  /* ── Cross-highlight broadcast lists ───────────────────────────────────
     Pre-compute the pair: keys each capsule should broadcast on hover so
     the top-of-page status strip becomes a first-class participant in the
     global cross-highlight network. */
  const activeSessionPairKeys = activeSession.pairs.map((p) => `pair:${p}`)
  const nextSessionPairKeys = next.session.pairs.map((p) => `pair:${p}`)
  const focusPairKeys = plan.focusPairs.map((p) => `pair:${p}`)
  const newsAffectedPairs =
    nextEvent && PAIRS_BY_CURRENCY[nextEvent.currency]
      ? PAIRS_BY_CURRENCY[nextEvent.currency]
      : []
  const newsPairKeys = newsAffectedPairs.map((p) => `pair:${p}`)

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ delay: 0.05, duration: 0.5, ease: EASE_V }}
      className="relative overflow-hidden"
      style={{ borderBottom: `1px solid ${VANTARY.rule}` }}
    >
      {/* breathing bloom strip — preserved, but at lower intensity since
          the capsules now provide the visual texture */}
      <motion.div
        aria-hidden="true"
        className="absolute inset-0 pointer-events-none"
        style={{
          background: `linear-gradient(90deg, transparent 0%, ${VANTARY.amberWash} 50%, transparent 100%)`,
          opacity: 0.4,
        }}
        animate={{ opacity: [0.18, 0.42, 0.18] }}
        transition={{ duration: 7, repeat: Infinity, ease: "easeInOut" }}
      />

      <div className="relative max-w-screen-xl mx-auto px-6 lg:px-8 py-1.5 flex items-center gap-0 overflow-x-auto">
        {/* SESSION — keyed in the global `session:{city}` namespace so this
            capsule lights up alongside its puck in the SessionsRadar and any
            session anchor in the Oracle answer. Broadcasts pair:* keys for
            every tradeable pair in the active session. */}
        <TickerCapsule
          eyebrow="SESSION"
          value={checkin.sessionInfo.name}
          category="session"
          crossKey={`session:${activeSession.city.toLowerCase()}`}
          broadcastKeys={activeSessionPairKeys}
          delay={0}
          preview={<SessionPopoverContent active={activeSession} />}
          signal={
            <motion.span
              aria-hidden="true"
              className="inline-block rounded-full"
              style={{ width: 5, height: 5, background: VANTARY.onlineDot, boxShadow: `0 0 6px ${VANTARY.onlineDot}` }}
              animate={{ opacity: [0.5, 1, 0.5] }}
              transition={{ duration: 2.4, repeat: Infinity, ease: "easeInOut" }}
            />
          }
        />
        <CapsuleDivider />

        {/* OPENS IN — points at the upcoming session. Uses a `next:` prefix
            so it has its own selectable identity, but also broadcasts the
            target session's `session:{city}` key so hovering this capsule
            lights up the matching puck in the SessionsRadar and every pair
            traded inside that session. */}
        <TickerCapsule
          eyebrow="OPENS IN"
          value={
            <span className="font-mono tabular-nums" style={{ color: VANTARY.paper }}>
              {liveOpensIn}
            </span>
          }
          category="session"
          crossKey={`next:session:${next.session.city.toLowerCase()}`}
          broadcastKeys={[
            `session:${next.session.city.toLowerCase()}`,
            ...nextSessionPairKeys,
          ]}
          delay={0.04}
          preview={<OpensInPopoverContent next={next} />}
          signal={<Clock size={10} strokeWidth={1.6} style={{ color: VANTARY.ashSoft, marginLeft: 2 }} />}
        />
        <CapsuleDivider />

        {/* PLAN */}
        <TickerCapsule
          eyebrow="PLAN"
          value={`${tradesLeft} TRADES LEFT`}
          category={tradesCategory}
          crossKey="plan-today"
          delay={0.08}
          preview={<PlanPopoverContent plan={plan} />}
          signal={
            <span
              aria-hidden="true"
              className="inline-flex items-center gap-0.5 ml-1"
            >
              {Array.from({ length: plan.maxTrades }).map((_, i) => (
                <span
                  key={i}
                  className="inline-block rounded-sm"
                  style={{
                    width: 7,
                    height: 4,
                    background:
                      i < plan.tradesUsed
                        ? VANTARY.amberHalo
                        : "rgba(34,197,94,0.55)",
                  }}
                />
              ))}
            </span>
          }
        />
        <CapsuleDivider />

        {/* RISK USED */}
        <TickerCapsule
          eyebrow="RISK USED"
          value={
            <span className="font-mono tabular-nums">
              <span style={{ color: VANTARY.paper, fontWeight: 600 }}>
                {plan.dailyLossUsed.toFixed(1)}%
              </span>
              <span style={{ color: VANTARY.ashSoft, margin: "0 4px" }}>/</span>
              <span style={{ color: VANTARY.ash }}>{plan.maxDailyLoss}%</span>
            </span>
          }
          category={riskCategory}
          crossKey="risk-today"
          delay={0.12}
          preview={<RiskPopoverContent plan={plan} />}
          signal={
            <span
              aria-hidden="true"
              className="relative ml-1 overflow-hidden rounded-sm"
              style={{
                width: 28,
                height: 3,
                background: "rgba(255,255,255,0.06)",
              }}
            >
              <span
                className="absolute inset-y-0 left-0"
                style={{
                  width: `${Math.min(100, riskPct * 100)}%`,
                  background:
                    riskCategory === "session"
                      ? VANTARY.chartUp
                      : riskCategory === "alert"
                        ? VANTARY.amber
                        : VANTARY.chartDown,
                  transition: "width 600ms cubic-bezier(0.22,1,0.36,1)",
                }}
              />
            </span>
          }
        />
        <CapsuleDivider />

        {/* FOCUS — broadcasts every pair in the user's focus list, so hovering
            this capsule lights up matching rows in WatchlistMatrix, matching
            session-pair chips inside SessionPucks, and matching anchors inside
            any open Oracle answer. */}
        <TickerCapsule
          eyebrow="FOCUS"
          value={plan.focusPairs.join(" · ")}
          category="focus"
          crossKey="focus:today"
          broadcastKeys={focusPairKeys}
          delay={0.16}
          preview={<FocusPopoverContent plan={plan} />}
          signal={<Target size={10} strokeWidth={1.6} style={{ color: VANTARY.ashSoft, marginLeft: 2 }} />}
        />
        <CapsuleDivider />

        {/* NEWS — keyed in an `event:` namespace consistent with MacroRow.
            Broadcasts the issuer-currency's likely-affected pairs so hovering
            "ECB" lights up EUR/USD, EUR/GBP, EUR/JPY across the dashboard
            (Watchlist + Macro affected-pair chips + Oracle anchors). */}
        {nextEvent && (
          <TickerCapsule
            eyebrow="NEWS"
            value={
              <span className="flex items-center gap-1.5">
                <span style={{ color: VANTARY.paper }}>
                  {nextEvent.event.split(" ")[0].toUpperCase()}
                </span>
                <span style={{ color: VANTARY.ashSoft }}>·</span>
                <span className="font-mono tabular-nums" style={{ color: VANTARY.paperDim }}>
                  {nextEvent.time}
                </span>
              </span>
            }
            category="macro"
            crossKey={`event:${nextEvent.currency.toLowerCase()}-${nextEvent.time.replace(":", "")}`}
            broadcastKeys={newsPairKeys}
            delay={0.20}
            preview={<NewsPopoverContent plan={plan} />}
            signal={
              newsSec > 0 && newsSec < 60 * 60 ? (
                <motion.span
                  aria-hidden="true"
                  className="inline-block rounded-full ml-1"
                  style={{
                    width: 5,
                    height: 5,
                    background: VANTARY.chartDown,
                    boxShadow: `0 0 8px ${VANTARY.chartDown}`,
                  }}
                  animate={{ opacity: [0.4, 1, 0.4], scale: [1, 1.18, 1] }}
                  transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
                />
              ) : (
                <Calendar size={10} strokeWidth={1.6} style={{ color: VANTARY.ashSoft, marginLeft: 2 }} />
              )
            }
          />
        )}
      </div>
    </motion.div>
  )
}

/* ──────────────────────────────────────────────────────────��────────────�����
   <LiveEquityVolume> — paired-bar chart card, the protagonist of the page.
   Reference: image #2 + #12 — "122,580 Month" with paired Jan-Jul bars
   and the amber-haloed tooltip pill on the highlighted month.
   ────��──────────────────────────────────────────────────────────────────── */

function LiveEquityVolume({ checkin }: { checkin: typeof AI_CHECKIN }) {
  const [period, setPeriod] = useState<"day" | "week" | "month" | "year">("week")
  const [hover, setHover] = useState(false)

  // Generate 7-bar paired data — current week vs previous week of P&L
  const data = useMemo(() => [
    { lbl: "Mon", cur: 92, prev: 64 },
    { lbl: "Tue", cur: 142, prev: 88 },   // <- highlighted (today)
    { lbl: "Wed", cur: 76, prev: 110 },
    { lbl: "Thu", cur: 0,  prev: 132 },
    { lbl: "Fri", cur: 0,  prev: 96 },
    { lbl: "Sat", cur: 0,  prev: 22 },
    { lbl: "Sun", cur: 0,  prev: 8 },
  ], [])
  const highlightIdx = 1
  const max = 160

  return (
    <CardShell deepLink>
      <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}>
        <header className="flex items-center justify-between mb-5">
          <h3 className="font-sans" style={{ fontSize: 15, color: VANTARY.paper, fontWeight: 500 }}>
            Live Equity Volume
          </h3>
          <ArrowUpRight size={16} strokeWidth={1.5} color={VANTARY.ash} className="opacity-60" />
        </header>

        <div className="flex items-baseline gap-3 mb-1">
          <ProtagonistNumber value={checkin.stateSummary.accountBalance} size={64} hover={hover} />
          <span style={{ fontSize: 14, color: VANTARY.ash }}>{period === "week" ? "Week" : period === "month" ? "Month" : period}</span>
        </div>

        {/* tabs — Week / Month / Quater / Year (frame #2 spelling preserved as a wink) */}
        <div className="flex items-center gap-5 mt-4 mb-6">
          {(["week", "month", "year"] as const).map(p => (
            <button
              key={p}
              onClick={() => setPeriod(p)}
              className="font-sans relative"
              style={{
                fontSize: 12,
                color: period === p ? VANTARY.paper : VANTARY.ash,
                paddingBottom: 4,
                fontWeight: period === p ? 500 : 400,
                textTransform: "capitalize",
              }}
            >
              {p === "year" ? "Year" : p === "month" ? "Month" : p === "week" ? "Week" : p}
              {period === p && (
                <motion.span
                  layoutId="period-underline"
                  className="absolute left-0 right-0 bottom-0 h-px"
                  style={{ background: VANTARY.paper }}
                />
              )}
            </button>
          ))}
        </div>

        {/* Chart canvas */}
        <PairedBarChart
          data={data}
          highlightIdx={highlightIdx}
          max={max}
          tooltip={{ label: "Tue +135.48", subLabel: "$135.48 floating P&L" }}
          chromaActive={hover}
        />
      </div>
    </CardShell>
  )
}

/* ═════════════��═══════���══════════��══════════════════��═══════════════════════
 * ╔═══��������════════════════════════════════��═════════════════════════════��═══╗
 * ║                                                                       ║
 * ║                  H E R O   B R I E F I N G                           ║
 * ║                  ──────────────��──────���───                           ║
 * ║                                                                       ║
 * ���   "Marcus — here is what matters in the next hour."                  ║
 * ���                                                                       ║
 * ║   The first thing the trader sees when the dashboard loads. Replaces ║
 * ║   the previous `eyebrow + headline + caption-paragraph` layout with  ║
 * ║   a fully-composed editorial briefing built from atomic chips.       ║
 * ║                                                                       ║
 * ║   Composition:                                                        ║
 * ║                                                                       ║
 * ║       ● DASHBOARD · WED 04 APR 2026 · 02:01 UTC · LIVE              ���
 * ���                                                                       ║
 * ║       Good morning, Marcus.                                          ║
 * ║       London opens in  47m                                            ║
 * ║                                                                       ║
 * ║       Focus  EUR/USD · London ·  74% WR                              ║
 * ║       Cap    2/2 trades remaining ·  FTMO 4.2%                       ║
 * ║                                                                       ║
 * ║       ─────────────────────                                          ║
 * ║       AI BRIEF · refreshed 06:14 UTC · in 14m  ↻                     ║
 * ║                                                                       ║
 * ║   Designed at three densities (`comfortable | compact | minimal`)    ║
 * ║   so when the dashboard becomes user-customizable in Edit 09, the    ���
 * ║   briefing degrades gracefully into a corner widget without rewrite. ���
 * ║                                                                       ║
 * ╚════════════���══════════════════════════════════════��═══════════════════╝
 * ═��═════════════��═══════════════════��════���════════════��═════════════��═══ */

/** Density mode for the HeroBriefing widget. Drives typography ladder
 *  and which sub-blocks render. Future Edit 09 (LayoutKit) will let the
 *  user resize the briefing widget; the corresponding density flips
 *  automatically based on the widget's grid span. */
type BriefingDensity = "comfortable" | "compact" | "minimal"

/* ����──────────────────�����──────������──────────────────��───────────────────────────
 *  CHIP ATOMS — the briefing's typographic vocabulary.
 *
 *  Five atomic chip primitives used across the briefing. Introduced here
 *  in Edit 01 because they will be reused in Edit 02 (KPI grid),
 *  Edit 07 (session pucks), and the customisable widget canvas in Edit 09.
 *
 *  Visual contract:
 *    · 4px corner radius
 *    · 1px hairline border
 *    · 1.5px / 6px padding
 *    · 11pt mono caps with 0.14em tracking
 *    · tabular-nums for any chip carrying a numeric value
 *    · accept `size?: "sm" | "md"` for density-driven sizing
 * ─────────────────────────────────���──────────────��─────────────────────���── */

function ChipShell({
  children,
  borderColor,
  backgroundColor,
  textColor,
  title,
  size = "md",
}: {
  children: React.ReactNode
  borderColor: string
  backgroundColor: string
  textColor: string
  title?: string
  size?: "sm" | "md"
}) {
  const fs = size === "sm" ? 9.5 : 11
  const py = size === "sm" ? 1   : 1.5
  const px = size === "sm" ? 5   : 6
  return (
    <span
      title={title}
      className="inline-flex items-center gap-1 font-mono uppercase tabular-nums"
      style={{
        fontSize: fs,
        letterSpacing: "0.14em",
        padding: `${py}px ${px}px`,
        border: `1px solid ${borderColor}`,
        background: backgroundColor,
        color: textColor,
        borderRadius: 4,
        whiteSpace: "nowrap",
        lineHeight: 1.2,
      }}
    >
      {children}
    </span>
  )
}

/** Currency pair atom · paper text on hairline outline. Used inline
 *  in briefing copy and reused in the future watchlist atoms. */
function PairChip({ pair, size }: { pair: string; size?: "sm" | "md" }) {
  return (
    <ChipShell
      borderColor={VANTARY.rule}
      backgroundColor="transparent"
      textColor={VANTARY.paper}
      title={`Currency pair: ${pair}`}
      size={size}
    >
      {pair}
    </ChipShell>
  )
}

/** Trading region / session atom · amber to denote "live time-sensitive". */
function RegionChip({ region, size }: { region: string; size?: "sm" | "md" }) {
  return (
    <ChipShell
      borderColor={VANTARY.amberHalo}
      backgroundColor={VANTARY.amberWash}
      textColor={VANTARY.amber}
      title={`Trading region: ${region}`}
      size={size}
    >
      {region}
    </ChipShell>
  )
}

/** Win-rate atom · color tier reflects the strength of the edge.
 *  ≥70% amber (strong edge) · ≥55% paper (positive) · <55% paperDim (weak). */
function WRChip({ pct, size, label = "WR" }: { pct: number; size?: "sm" | "md"; label?: string }) {
  const tier = pct >= 70 ? "strong" : pct >= 55 ? "positive" : "weak"
  const colors =
    tier === "strong"
      ? { border: VANTARY.amberHalo, bg: VANTARY.amberWash, text: VANTARY.amber }
      : tier === "positive"
      ? { border: VANTARY.rule, bg: "transparent", text: VANTARY.paper }
      : { border: VANTARY.rule, bg: "transparent", text: VANTARY.paperDim }
  return (
    <ChipShell
      borderColor={colors.border}
      backgroundColor={colors.bg}
      textColor={colors.text}
      title={`Historical win-rate on this setup: ${pct}%`}
      size={size}
    >
      {pct}% {label}
    </ChipShell>
  )
}

/** Trade-cap atom · 2 visual dots representing trades remaining today.
 *  Filled dot = remaining, hollow dot = consumed. */
function CapChip({ used, max, size = "md" }: { used: number; max: number; size?: "sm" | "md" }) {
  const remaining = Math.max(0, max - used)
  const dotSize   = size === "sm" ? 3.5 : 4
  return (
    <ChipShell
      borderColor={VANTARY.rule}
      backgroundColor="transparent"
      textColor={VANTARY.paper}
      title={`${used} of ${max} trades used today · ${remaining} remaining`}
      size={size}
    >
      <span style={{ marginRight: 2 }}>
        {remaining}/{max} TRADES LEFT
      </span>
      <span className="inline-flex items-center gap-[3px]" aria-hidden>
        {Array.from({ length: max }).map((_, i) => {
          const filled = i >= used
          return (
            <span
              key={i}
              style={{
                width: dotSize,
                height: dotSize,
                borderRadius: 99,
                background: filled ? VANTARY.amber : "transparent",
                border: `1px solid ${filled ? VANTARY.amber : VANTARY.ash}`,
                display: "inline-block",
              }}
            />
          )
        })}
      </span>
    </ChipShell>
  )
}

/** FTMO / prop-firm drawdown atom · color band by drawdown severity.
 *  <5% amberWash · 5–7% amberInk · >7% warnWash. */
function FTMOChip({ pct, size }: { pct: number; size?: "sm" | "md" }) {
  const band: "ok" | "warn" | "danger" =
    pct < 5 ? "ok" : pct < 7 ? "warn" : "danger"
  const colors =
    band === "ok"
      ? { border: VANTARY.amberHalo,                bg: VANTARY.amberWash, text: VANTARY.amber }
      : band === "warn"
      ? { border: "rgba(239,68,68,0.35)",           bg: "rgba(239,68,68,0.08)", text: VANTARY.amber }
      : { border: "rgba(239,68,68,0.55)",           bg: "rgba(239,68,68,0.16)", text: "rgb(239,68,68)" }
  return (
    <ChipShell
      borderColor={colors.border}
      backgroundColor={colors.bg}
      textColor={colors.text}
      title={`FTMO challenge drawdown: ${pct}% of 10% max allowed`}
      size={size}
    >
      FTMO {pct.toFixed(1)}%
    </ChipShell>
  )
}

/* ═══════���══════════���════════════���════��═����══���═══════════��════════════════════
 * ╔═══════════════════════════════���═══════════════════════════════════════╗
 * ║          B R I E F I N G   S U B - C O M P O N E N T S               ║
 * ║                                                                       ║
 * ║   Edit 01 v2 — full-width editorial briefing band.                    ║
 * ║                                                                       ║
 * ║   The previous greeting block was a single 44pt headline + 14pt       ║
 * ║   caption sentence. This redesign upgrades it into a four-tier        ║
 * ��   editorial composition spanning the full dashboard width:            ║
 * ║                                                                       ║
 * ���       ◯ ──�� ● LIVE ���─ THE TRADER'S BRIEFING ── 02:01 UTC ──��� ◯       ║
 * ║                                                                       ║
 * ║       TRADER   Marcus      | Good morning,        | STATUS   ACTIVE  ║
 * ║       PLAN     FTMO 50K    |   Marcus.            | DAY P&L  +$135   ║
 * ║       STRATEGY MOMENTUM    | London opens in 47m  | WEEK     +$1,247 ║
 * ║       SESSION  SYD + TKY   | ✦ AI BRIEF · 06:14   | STREAK   7 GREEN ║
 * ║                                                                       ║
 * ║       ⊙ FOCUS  | ↗ EDGE   | ��� CAP        | 🛡 RISK                  ║
 * ║       EUR/USD  | 74%      | 2/2 ● ●      | 4.2%                     ║
 * ║       London   | WR · LDN | remaining    | FTMO drawdown             ���
 * ║       #1 setup | +12 vs   | 0 used 24h   | 5.8% headroom             ║
 * ║                                                                       ║
 * ║       ✦ AI BRIEF  "Staying disciplined here protects…"   ↻           ║
 * ║                                                                       ║
 * ║   Architecture:                                                       ║
 * ║       <HeroBriefing/>                                                 ║
 * ║         ├─ <BriefingFrameBar/>     cinematic top frame                ║
 * ║         ├─ <BriefingSpecHeadline/> 3-col spec-flanked centerpiece     ║
 * ║         │   ├─ <SpecTable/>            left  trader ledger            ║
 * ║         │   ├─ <GreetingHeadline/>     mid   52pt + countdown         ║
 * ║         │   └─ <SpecTable/>            right live state ledger        ║
 * ║         ├─ <BriefingMatrix/>       4-station horizontal data row      ║
 * ║         │   └─ <BriefingMatrixStation/>  × 4                          ║
 * ║         └─ <BriefingWhisper/>      italic AI quote + refresh          ║
 * ║                                                                       ║
 * ║   All densities ("comfortable" | "compact" | "minimal") supported,    ║
 * ║   so when LayoutKit (Edit 09) lets the user resize/minimize this      ║
 * ║   widget, every sub-component degrades gracefully without rewrite.    ║
 * ║                                                                       ║
 * ╚══════���═���════════════════════════════════════════════════���════════���════╝
 * �����═══════��═════��══════════��══��════��═══���═══��═══������������═���══��═══�����════════����══ */

/* �����───�����─��─���─����──────���─────��─��───�����─────���────���─────────────���───────��������──────
 *  <BriefingFrameBar/>
 *  ���───��────���───��───────��────────────��─────────────────────────────────���───���
 *  Cinematic top frame. Two outline circles anchor the band; hairlines
 *  travel between them with the LIVE pulse on the left, the centered
 *  title in the middle, and the live datestamp + UTC clock on the right.
 *  The UTC segment refreshes every 30s.
 *
 *  Density-aware:
 *      comfortable  full bar with all clusters
 *      compact      drops the LIVE cluster, keeps title + UTC clock
 *      minimal      title only, both anchors collapse to small dashes
 * ─��──��───────────────────────────────────────────────────��──────────��───�����─ */
function BriefingFrameBar({ density }: { density: BriefingDensity }) {
  // Live UTC clock �� editorial cadence, refreshes every 30s.
  const [utc, setUtc] = useState(() => formatUTCNow())
  useEffect(() => {
    const id = setInterval(() => setUtc(formatUTCNow()), 30_000)
    return () => clearInterval(id)
  }, [])

  const titleSize = density === "minimal" ? 9.5 : 11
  const showClusters = density !== "minimal"

  return (
    <div className="flex items-center gap-3 select-none" aria-hidden={false}>
      {/* Left anchor */}
      <span
        aria-hidden
        className="rounded-full"
        style={{ width: 6, height: 6, border: `1px solid ${VANTARY.ash}` }}
      />
      <span aria-hidden style={{ width: 22, height: 1, background: VANTARY.rule }} />

      {/* LIVE cluster — pulsing amber dot + label */}
      {showClusters && density === "comfortable" && (
        <span className="inline-flex items-center gap-1.5">
          <motion.span
            aria-hidden
            className="rounded-full"
            style={{
              width: 5, height: 5,
              background: VANTARY.amber,
              boxShadow: `0 0 6px ${VANTARY.amber}`,
            }}
            animate={{ opacity: [0.45, 1, 0.45], scale: [0.85, 1.1, 0.85] }}
            transition={{ duration: 2.4, repeat: Infinity, ease: "easeInOut" }}
          />
          <span
            className="font-mono uppercase"
            style={{
              fontSize: 9.5,
              letterSpacing: "0.20em",
              color: VANTARY.amber,
              fontWeight: 500,
            }}
          >
            LIVE
          </span>
        </span>
      )}

      {/* Long hairline travelling toward the centered title */}
      <span aria-hidden style={{ flex: 1, height: 1, background: VANTARY.rule }} />

      {/* Centered title */}
      <span
        className="font-mono uppercase whitespace-nowrap"
        style={{
          fontSize: titleSize,
          letterSpacing: "0.32em",
          color: VANTARY.paper,
          fontWeight: 500,
        }}
      >
        THE TRADER&apos;S BRIEFING
      </span>

      {/* Long hairline travelling toward the right cluster */}
      <span aria-hidden style={{ flex: 1, height: 1, background: VANTARY.rule }} />

      {/* Right cluster — weekday + date + live UTC clock */}
      {showClusters && (
        <div className="flex items-center gap-2">
          <span
            className="font-mono uppercase whitespace-nowrap"
            style={{
              fontSize: 10,
              letterSpacing: "0.22em",
              color: VANTARY.ashSoft,
            }}
          >
            WED 04 APR 2026
          </span>
          <span
            aria-hidden
            style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }}
          />
          <span
            className="font-mono uppercase tabular-nums whitespace-nowrap"
            style={{
              fontSize: 10,
              letterSpacing: "0.22em",
              color: VANTARY.paperDim,
            }}
            aria-label={`Current UTC time: ${utc}`}
          >
            {utc} UTC
          </span>
        </div>
      )}

      <span aria-hidden style={{ width: 22, height: 1, background: VANTARY.rule }} />
      <span
        aria-hidden
        className="rounded-full"
        style={{ width: 6, height: 6, border: `1px solid ${VANTARY.ash}` }}
      />
    </div>
  )
}

/* ──────────────────���────────────────���────────────────────────��───────���────
 *  <SpecRow/> + <SpecTable/>
 *  ──────────────────���──────────��────��──────────────────────────────────────
 *  Editorial key-value spec rows used by the left and right ledgers in
 *  the spec headline. Each row has a mono-caps label on the left and a
 *  mono tabular value on the right. Optional `accent` flag tints the
 *  value amber for live / time-critical facts. Optional `live` flag
 *  pulses a small amber dot next to the value.
 *
 *  Visual contract:
 *      · row height: 32px
 *      · 1px hairline divider between rows (40% opacity)
 *      · `title` attribute on the row gives a hover tooltip with context
 * ─────────��─────────────────────────────────────────────────────────────── */
type SpecRowDef = {
  label: string
  value: React.ReactNode
  accent?: boolean
  live?: boolean
  title?: string
}

function SpecRow({ row }: { row: SpecRowDef }) {
  const valueColor = row.accent ? VANTARY.amber : VANTARY.paper
  return (
    <div
      title={row.title}
      className="flex items-baseline justify-between gap-3 py-2.5"
    >
      <span
        className="font-mono uppercase"
        style={{
          fontSize: 9.5,
          letterSpacing: "0.22em",
          color: VANTARY.ashSoft,
          fontWeight: 400,
        }}
      >
        {row.label}
      </span>
      <span className="inline-flex items-center gap-1.5">
        {row.live && (
          <motion.span
            aria-hidden
            className="rounded-full"
            style={{
              width: 4, height: 4,
              background: VANTARY.amber,
              boxShadow: `0 0 4px ${VANTARY.amber}`,
            }}
            animate={{ opacity: [0.45, 1, 0.45] }}
            transition={{ duration: 2.4, repeat: Infinity, ease: "easeInOut" }}
          />
        )}
        <span
          className="font-mono uppercase tabular-nums whitespace-nowrap"
          style={{
            fontSize: 11,
            letterSpacing: "0.10em",
            color: valueColor,
            fontWeight: 500,
          }}
        >
          {row.value}
        </span>
      </span>
    </div>
  )
}

function SpecTable({ rows }: { rows: SpecRowDef[] }) {
  return (
    <div className="flex flex-col w-full">
      {rows.map((row, i) => (
        <React.Fragment key={i}>
          {i > 0 && (
            <div
              aria-hidden
              style={{ height: 1, background: VANTARY.rule, opacity: 0.5 }}
            />
          )}
          <SpecRow row={row} />
        </React.Fragment>
      ))}
    </div>
  )
}

/* ───────────────────────────────────────────────���─────��─────��────────��────
 *  <BriefingSeal/> — DEPRECATED in v2 but retained as a thin compatibility
 *  shim that proxies to <BriefingFrameBar/>. Kept to avoid breaking any
 *  external callers; will be removed once the codebase is fully migrated.
 * ───────────────────────────────────────────────────────────────────────── */
function BriefingSeal({ density }: { density: BriefingDensity }) {
  // Live UTC clock. Updates every 30s — the seal is editorial, not a stopwatch.
  const [utcLabel, setUtcLabel] = useState(() => formatUTCNow())
  useEffect(() => {
    const id = setInterval(() => setUtcLabel(formatUTCNow()), 30_000)
    return () => clearInterval(id)
  }, [])
  // Static parts (the real product would derive these from `new Date()` too,
  // but the demo dashboard data freezes the date to 04 APR 2026 — so we
  // surface the LIVE part via UTC time only).
  const datePart = "WED 04 APR 2026"
  const fs = density === "minimal" ? 9.5 : 11

  return (
    <div className="flex items-center gap-2 mb-3 flex-wrap">
      <motion.span
        aria-hidden
        className="rounded-full"
        style={{
          width: 5, height: 5, background: VANTARY.amber,
          boxShadow: `0 0 6px ${VANTARY.amber}`,
        }}
        animate={{ opacity: [0.45, 1, 0.45], scale: [0.85, 1.1, 0.85] }}
        transition={{ duration: 2.4, repeat: Infinity, ease: "easeInOut" }}
      />
      <span
        className="font-mono uppercase"
        style={{ fontSize: fs, letterSpacing: "0.22em", color: VANTARY.ashSoft }}
      >
        DASHBOARD
      </span>
      <span style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }} />
      <span
        className="font-mono uppercase"
        style={{ fontSize: fs, letterSpacing: "0.22em", color: VANTARY.ash }}
      >
        {datePart}
      </span>
      <span style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }} />
      <span
        className="font-mono uppercase tabular-nums"
        style={{ fontSize: fs, letterSpacing: "0.22em", color: VANTARY.paperDim }}
        aria-label={`Current UTC time: ${utcLabel}`}
      >
        {utcLabel} UTC
      </span>
      {density !== "minimal" && (
        <>
          <span style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }} />
          <span
            className="font-mono uppercase"
            style={{
              fontSize: 9,
              letterSpacing: "0.18em",
              color: VANTARY.amber,
              padding: "1px 5px",
              border: `1px solid ${VANTARY.amberHalo}`,
              borderRadius: 99,
              background: VANTARY.amberWash,
            }}
          >
            LIVE
          </span>
        </>
      )}
    </div>
  )
}

/** Format the current UTC time as HH:MM. Tiny helper colocated with the seal. */
function formatUTCNow(): string {
  const d  = new Date()
  const hh = String(d.getUTCHours()).padStart(2, "0")
  const mm = String(d.getUTCMinutes()).padStart(2, "0")
  return `${hh}:${mm}`
}

/* ──────────────���───────────────���──────────────────────────────────────────
 *  <CountdownPill/> — the most important number on the page.
 *
 *  Displays the time until the next major session opens (e.g. "47m" or
 *  "1h 23m"). Renders inline at headline weight (52pt mono) and pulses
 *  on a slow halo loop so the eye snaps to it.
 *
 *  Updates every 60 seconds. Uses tabular-nums so the pulse doesn't
 *  cause horizontal jitter when the digit count changes.
 * ────────────────────────────��────�����──────────────────────────────────��──── */
function CountdownPill({
  initialMinutes,
  size = 52,
}: {
  initialMinutes: number
  size?: number
}) {
  const [minutes, setMinutes] = useState(initialMinutes)
  useEffect(() => {
    const id = setInterval(() => {
      setMinutes((m) => Math.max(0, m - 1))
    }, 60_000)
    return () => clearInterval(id)
  }, [])

  const label = minutes >= 60
    ? `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, "0")}m`
    : `${minutes}m`

  return (
    <motion.span
      className="font-mono tabular-nums inline-block"
      style={{
        fontSize: size,
        lineHeight: 1.0,
        fontWeight: 500,
        letterSpacing: "-0.020em",
        color: VANTARY.amber,
      }}
      animate={{
        textShadow: [
          `0 0 0px ${VANTARY.amberHalo}`,
          `0 0 12px ${VANTARY.amberHalo}`,
          `0 0 0px ${VANTARY.amberHalo}`,
        ],
      }}
      transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
      aria-live="polite"
      title={`${minutes} minutes until the next session opens`}
    >
      {label}
    </motion.span>
  )
}

/* ────────────────────────────────────────────────────���─────���─────��────────
 *  <GreetingHeadline/> — the 52pt anchor of the dashboard.
 *
 *  Two-clause composition. Line 1 introduces the trader; line 2 names
 *  the next time-critical event with a live countdown pill. The two
 *  clauses are visually balanced so the eye treats them as a single
 *  headline beat, not "title + subtitle".
 * ─────────────────────────────��──────────��──────────────────────────────── */
function GreetingHeadline({
  greeting,
  name,
  sessionName,
  opensInMinutes,
  isHolographic,
  density,
}: {
  greeting: string
  name: string
  sessionName: string
  opensInMinutes: number
  isHolographic: boolean
  density: BriefingDensity
}) {
  // Density-driven typography ladder
  const ladder = {
    comfortable: { fs: 52, lh: 1.00, ls: "-0.030em" },
    compact:     { fs: 40, lh: 1.02, ls: "-0.028em" },
    minimal:     { fs: 28, lh: 1.06, ls: "-0.020em" },
  }[density]

  const Wrap: any = isHolographic ? HolographicText : "h1"

  return (
    <Wrap
      className="font-sans"
      style={{
        fontSize:      ladder.fs,
        lineHeight:    ladder.lh,
        fontWeight:    500,
        letterSpacing: ladder.ls,
        color:         VANTARY.paper,
        maxWidth:      900,
      }}
    >
      <span style={{ color: VANTARY.paper }}>
        {greeting}, {name}.
      </span>
      {density !== "minimal" && (
        <>
          {" "}
          <span style={{ color: VANTARY.ash }}>
            {sessionName} opens in&nbsp;
          </span>
          <CountdownPill initialMinutes={opensInMinutes} size={ladder.fs} />
          <span style={{ color: VANTARY.ash }}>.</span>
        </>
      )}
    </Wrap>
  )
}

/* ─���───────────────────��───────────────────────────────────────────────────
 *  <BriefingFocusLine/> — "Focus on …" line composed of chip atoms.
 *
 *  Reads:   Focus on  [EUR/USD]  during  [London]  ·  [74% WR]  ·  Max 2 trades
 *
 *  Built from PairChip + RegionChip + WRChip. The supporting copy
 *  ("Focus on", "during") is paperDim so the chips visually lead.
 * ────────��──��─���───��───����──────��──���──��──────�����───�����──��─�����─────��───���──────��──── */
function BriefingFocusLine({
  pair,
  region,
  wr,
  maxTrades,
}: {
  pair: string
  region: string
  wr: number
  maxTrades: number
}) {
  // Deprecated in v2 — superseded by <BriefingMatrix/>. Retained as a
  // thin shim returning the same chip composition for any external caller.
  return (
    <div
      className="flex items-center gap-x-2 gap-y-2 flex-wrap font-sans"
      style={{ fontSize: 16, lineHeight: 1.5, color: VANTARY.paperDim, maxWidth: 760 }}
    >
      <span
        className="font-mono uppercase"
        style={{ fontSize: 9.5, letterSpacing: "0.22em", color: VANTARY.ashSoft, minWidth: 44 }}
      >
        FOCUS
      </span>
      <PairChip pair={pair} />
      <span style={{ color: VANTARY.ash }}>during</span>
      <RegionChip region={region} />
      <span style={{ color: VANTARY.rule }}>��</span>
      <WRChip pct={wr} />
      <span style={{ color: VANTARY.ash }}>·</span>
      <span style={{ color: VANTARY.paperDim }}>
        max <strong style={{ color: VANTARY.paper, fontWeight: 600 }}>{maxTrades} trades</strong> today
      </span>
    </div>
  )
}

/* ─────────────────────────────���────────���──────────────────────────────────
 *  <BriefingMatrixStation/>
 *  ───���─���───────���───────────────────────────────────────────────────────────
 *  A single column in the 4-station data matrix. Composition (top→bottom):
 *
 *      [icon] LABEL
 *      BIG NUMBER  (32–36pt mono)
 *      descriptor sentence (13pt sans paperDim)
 *      ─ ─ ─ ─    (dashed hairline · 70% width)
 *      INSIGHT   (mono caps · amber for time-critical, ashSoft otherwise)
 *
 *  Hover lifts the whole station's background to amberWash and brightens
 *  the icon + label + big number to amber, with the big number gaining a
 *  subtle text-shadow halo. The transition is short (180ms) so the row
 *  reads as crisp data, not a button.
 *
 *  Optional `dots` prop renders small "remaining" indicators next to the
 *  big number — used by the CAP station to show "2/2 ● ●".
 *
 *  Optional `accent` prop forces the insight line to amber (used by the
 *  FOCUS and RISK stations where the insight is time-critical).
 * ─────────────────────────���────────────────────────────��────────────────── */
type MatrixStationDef = {
  icon: any                      // lucide-react component reference
  label: string
  big: string
  descriptor: string
  insight: string
  accent?: boolean
  dots?: { remaining: number; total: number }
  title?: string
}

function BriefingMatrixStation({ station }: { station: MatrixStationDef }) {
  const [hover, setHover] = useState(false)
  const Icon = station.icon
  return (
    <motion.div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      title={station.title}
      className="flex flex-col cursor-default relative"
      style={{ padding: "20px 24px" }}
      animate={{ background: hover ? VANTARY.amberWash : "transparent" }}
      transition={{ duration: 0.18, ease: EASE_V }}
    >
      {/* Top accent bar — appears on hover, anchored to top edge */}
      <motion.span
        aria-hidden
        className="absolute left-0 right-0 top-0"
        style={{ height: 1, background: VANTARY.amber, transformOrigin: "left" }}
        initial={{ scaleX: 0 }}
        animate={{ scaleX: hover ? 1 : 0 }}
        transition={{ duration: 0.3, ease: EASE_V }}
      />

      {/* Label row · icon + uppercase mono caption */}
      <div className="flex items-center gap-2 mb-3">
        <Icon
          size={14}
          strokeWidth={1.5}
          color={hover ? VANTARY.amber : VANTARY.ash}
        />
        <span
          className="font-mono uppercase"
          style={{
            fontSize: 10,
            letterSpacing: "0.22em",
            color: hover ? VANTARY.amber : VANTARY.ashSoft,
            fontWeight: 500,
            transition: "color 180ms",
          }}
        >
          {station.label}
        </span>
      </div>

      {/* Big number + optional dots */}
      <div className="flex items-baseline gap-2 mb-1">
        <motion.span
          className="font-mono tabular-nums"
          style={{
            fontSize: 36,
            lineHeight: 1.0,
            fontWeight: 500,
            letterSpacing: "-0.025em",
            color: VANTARY.paper,
          }}
          animate={{
            textShadow: hover
              ? `0 0 14px ${VANTARY.amberHalo}`
              : `0 0 0px transparent`,
          }}
          transition={{ duration: 0.25 }}
        >
          {station.big}
        </motion.span>
        {station.dots && (
          <span className="inline-flex items-center gap-1 ml-1">
            {Array.from({ length: station.dots.total }).map((_, i) => {
              const filled = i < station.dots!.remaining
              return (
                <span
                  key={i}
                  aria-hidden
                  style={{
                    width: 6, height: 6, borderRadius: 99,
                    background: filled ? VANTARY.amber : "transparent",
                    border: `1px solid ${filled ? VANTARY.amber : VANTARY.ash}`,
                    boxShadow: filled ? `0 0 4px ${VANTARY.amberHalo}` : "none",
                  }}
                />
              )
            })}
          </span>
        )}
      </div>

      {/* Descriptor */}
      <div
        className="font-sans"
        style={{ fontSize: 13, color: VANTARY.paperDim, lineHeight: 1.4 }}
      >
        {station.descriptor}
      </div>

      {/* Dashed hairline · 70% width to give the insight a defined start */}
      <div
        aria-hidden
        className="my-3"
        style={{
          height: 1,
          width: "70%",
          borderTop: `1px dashed ${VANTARY.rule}`,
        }}
      />

      {/* Insight · amber for time-critical, ashSoft for neutral data */}
      <span
        className="font-mono uppercase"
        style={{
          fontSize: 10,
          letterSpacing: "0.20em",
          color: station.accent ? VANTARY.amber : VANTARY.ashSoft,
          fontWeight: 500,
        }}
      >
        {station.insight}
      </span>
    </motion.div>
  )
}

/* ─────────────────────────────────────��───────────────────────────────────
 *  <BriefingMatrix/>
 *  ──────────────────────────────────────────────��──────────────────────���───
 *  Horizontal 4-station data row. Top + bottom 1px hairlines bound the
 *  band; vertical 1px hairlines separate stations. On mobile the 4
 *  stations collapse to a 2×2 grid; the dividers stay clean because
 *  Tailwind handles them via `divide-x` / `divide-y` utility-style logic
 *  expressed with explicit border styles (no `divide-*` because we need
 *  per-side control for mobile).
 * ──────���────────────��───────────────���───��───────────────────────────────── */
function BriefingMatrix({ stations }: { stations: MatrixStationDef[] }) {
  return (
    <div
      className="grid grid-cols-2 lg:grid-cols-4"
      style={{
        borderTop:    `1px solid ${VANTARY.rule}`,
        borderBottom: `1px solid ${VANTARY.rule}`,
      }}
    >
      {stations.map((station, i) => {
        // Compute per-tile borders so 2x2 mobile and 1x4 desktop both look right
        const isFirstCol      = i === 0
        const isSecondCol     = i === 1
        const isThirdCol      = i === 2
        const isFourthCol     = i === 3
        const isTopRowMobile  = i < 2
        return (
          <div
            key={i}
            style={{
              // Vertical separators · always between stations on lg
              borderLeft:
                i > 0 ? `1px solid ${VANTARY.rule}` : "none",
              // Mobile-only horizontal separator between rows
              borderTop:
                !isTopRowMobile
                  ? `1px solid ${VANTARY.rule}`
                  : "none",
            }}
            className={
              // On mobile, second column needs left border too; on lg, all do.
              [
                isFirstCol  ? "lg:border-l-0" : "",
                isSecondCol ? "border-l lg:border-l" : "",
                isThirdCol  ? "lg:border-t-0 border-l-0 lg:border-l" : "",
                isFourthCol ? "lg:border-t-0" : "",
              ].join(" ")
            }
          >
            <BriefingMatrixStation station={station} />
          </div>
        )
      })}
    </div>
  )
}

/* ──────────────────────────────────────────���───���──────────��──����───────────
 *  <BriefingRiskLine/> — the risk posture line.
 *
 *  Reads:   Cap  [2/2 TRADES LEFT • ��� ]  ·  [FTMO 4.2%]  · staying disciplined
 *           protects everything you have built.
 * ───��──────��───────────────────────��────────��───────────────────────────── */
function BriefingRiskLine({
  tradesUsed,
  maxTrades,
  ftmoPct,
}: {
  tradesUsed: number
  maxTrades: number
  ftmoPct: number
}) {
  // Deprecated in v2 — superseded by <BriefingMatrix/>. Kept as shim.
  return (
    <div
      className="flex items-center gap-x-2 gap-y-2 flex-wrap font-sans"
      style={{ fontSize: 14, lineHeight: 1.5, color: VANTARY.paperDim, maxWidth: 760 }}
    >
      <span
        className="font-mono uppercase"
        style={{ fontSize: 9.5, letterSpacing: "0.22em", color: VANTARY.ashSoft, minWidth: 44 }}
      >
        CAP
      </span>
      <CapChip used={tradesUsed} max={maxTrades} />
      <span style={{ color: VANTARY.ash }}>·</span>
      <FTMOChip pct={ftmoPct} />
      <span style={{ color: VANTARY.ash }}>·</span>
      <span style={{ color: VANTARY.paperDim }}>
        staying disciplined here protects everything you have built.
      </span>
    </div>
  )
}

/* ─────────────��──────────────��───────────────────────────────────���────────
 *  <BriefingFlankStation/>
 *  ────────��──────────────��───���──────────────────������──────���───────���────────���─
 *  Vertical compact variant of <BriefingMatrixStation/>. Used to flank the
 *  greeting headline on the left (FOCUS, EDGE) and the right (CAP, RISK).
 *
 *  Layout (top → bottom):
 *      [icon] LABEL ───��───────��──────���────  (mono caps eyebrow)
 *      BIG VALUE                              (28pt mono · tabular-nums)
 *      descriptor                             (12.5pt sans paperDim)
 *      ─ ─ ─ ─                                (dashed hairline · 60% width)
 *      INSIGHT                                (10pt mono caps · amber if accent)
 *
 *  Hover: amberWash bg + amber tint on icon/label + halo on big value.
 *  The whole station is borderless — only the dashed hairline stays.
 *  Stations stack vertically and are separated by a horizontal dashed
 *  hairline between them; the column itself is bounded by a vertical
 *  dashed hairline against the greeting.
 * ──��─────────────────────────────────────────────────────────────────────�� */
function BriefingFlankStation({
  icon: Icon,
  label,
  big,
  descriptor,
  insight,
  accent,
  dots,
  align = "left",
  title,
  phase = 0,
}: {
  icon: any
  label: string
  big: string
  descriptor: string
  insight: string
  accent?: boolean
  dots?: { remaining: number; total: number }
  align?: "left" | "right"
  title?: string
  /** Stagger index so breathing loops never sync across the 4 stations. */
  phase?: number
}) {
  const [hover, setHover] = useState(false)
  const justify = align === "right" ? "items-end text-right" : "items-start text-left"
  return (
    <BreathingScope phase={phase} period={5.6} intensity={0.7}>
      <MagneticGlass radius={10} strength={3} borderLight={false} reflection ripple>
    <motion.div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      title={title}
      className={`relative flex flex-col cursor-default ${justify}`}
      style={{ paddingTop: 16, paddingBottom: 16, paddingLeft: 4, paddingRight: 4 }}
      animate={{ background: hover ? VANTARY.amberWash : "transparent" }}
      transition={{ duration: 0.18, ease: EASE_V }}
    >
      {/* Top accent strip — appears on hover */}
      <motion.span
        aria-hidden
        className="absolute left-0 right-0 top-0"
        style={{ height: 1, background: VANTARY.amber, transformOrigin: align === "right" ? "right" : "left" }}
        initial={{ scaleX: 0 }}
        animate={{ scaleX: hover ? 1 : 0 }}
        transition={{ duration: 0.3, ease: EASE_V }}
      />

      {/* Eyebrow row · icon + label · order swaps for right alignment */}
      <div className={`flex items-center gap-1.5 mb-2 ${align === "right" ? "flex-row-reverse" : ""}`}>
        <Icon
          size={12}
          strokeWidth={1.5}
          color={hover ? VANTARY.amber : VANTARY.ash}
        />
        <span
          className="font-mono uppercase"
          style={{
            fontSize: 9.5,
            letterSpacing: "0.22em",
            color: hover ? VANTARY.amber : VANTARY.ashSoft,
            fontWeight: 500,
            transition: "color 180ms",
          }}
        >
          {label}
        </span>
      </div>

      {/* Big value + optional dots */}
      <div className={`flex items-baseline gap-1.5 ${align === "right" ? "flex-row-reverse" : ""} mb-1`}>
        <motion.span
          className="font-mono tabular-nums"
          style={{
            fontSize: 26,
            lineHeight: 1.0,
            fontWeight: 500,
            letterSpacing: "-0.022em",
            color: VANTARY.paper,
          }}
          animate={{
            textShadow: hover
              ? `0 0 12px ${VANTARY.amberHalo}`
              : `0 0 0px transparent`,
          }}
          transition={{ duration: 0.25 }}
        >
          {big}
        </motion.span>
        {dots && (
          <span className="inline-flex items-center gap-1">
            {Array.from({ length: dots.total }).map((_, i) => {
              const filled = i < dots.remaining
              return (
                <span
                  key={i}
                  aria-hidden
                  style={{
                    width: 5, height: 5, borderRadius: 99,
                    background: filled ? VANTARY.amber : "transparent",
                    border: `1px solid ${filled ? VANTARY.amber : VANTARY.ash}`,
                    boxShadow: filled ? `0 0 4px ${VANTARY.amberHalo}` : "none",
                  }}
                />
              )
            })}
          </span>
        )}
      </div>

      {/* Descriptor */}
      <div
        className="font-sans"
        style={{
          fontSize: 12.5,
          color: VANTARY.paperDim,
          lineHeight: 1.4,
          maxWidth: 200,
        }}
      >
        {descriptor}
      </div>

      {/* Dashed hairline · 60% width */}
      <div
        aria-hidden
        className="my-2.5"
        style={{
          height: 1,
          width: "60%",
          borderTop: `1px dashed ${VANTARY.rule}`,
          alignSelf: align === "right" ? "flex-end" : "flex-start",
        }}
      />

      {/* Insight */}
      <span
        className="font-mono uppercase"
        style={{
          fontSize: 9.5,
          letterSpacing: "0.20em",
          color: accent ? VANTARY.amber : VANTARY.ashSoft,
          fontWeight: 500,
          lineHeight: 1.3,
        }}
      >
        {insight}
      </span>
    </motion.div>
      </MagneticGlass>
    </BreathingScope>
  )
}

/* ──────────────────────────���────────────────────────────────────────────���─
 *  <BriefingSpecHeadline/>
 *  ─────────────────────────���───────────────────────────────────────────────
 *  The cinematic centerpiece of the briefing band. A 3-column composition:
 *
 *     ┌────────────┬────────────────────────────���────┬────────────┐
 *     │   FOCUS    │                                  │    CAP    │
 *     │   EDGE     │  GREETING + COUNTDOWN + AI BRIEF │    RISK   │
 *     │ (3 cols)   │           (6 cols)               │ (3 cols)  │
 *     └────────────┴───���─────────��───────────────────┴────────────┘
 *
 *  Left flank holds FOCUS (top) and EDGE (bottom) stacked vertically.
 *  Right flank holds CAP (top) and RISK (bottom).
 *  Vertical dashed hairlines flank the centerpiece column, giving the
 *  greeting its own stage. On mobile (< lg) the flanks stack below the
 *  centerpiece in a 2x2 grid, preserving information density.
 *
 *  The AI BRIEF sub-line lives directly under the headline. Its style
 *  matches the Mercury/Linear "feature provenance" pattern — small mono
 *  caps amber pill-row.
 * ─────────────────���─────────────────────────────────────────────────────── */
type FlankStationDef = {
  icon: any
  label: string
  big: string
  descriptor: string
  insight: string
  accent?: boolean
  dots?: { remaining: number; total: number }
  title?: string
}
function BriefingSpecHeadline({
  greeting,
  name,
  sessionName,
  opensInMinutes,
  isHolographic,
  density,
  leftStations,
  rightStations,
  refreshedAt,
  refreshInMin,
  }: {
  greeting: string
  name: string
  sessionName: string
  opensInMinutes: number
  isHolographic: boolean
  density: BriefingDensity
  leftStations: FlankStationDef[]
  rightStations: FlankStationDef[]
  refreshedAt: string
  refreshInMin: number
}) {
  const showSpecs = density !== "minimal"
  const headlineGap = density === "comfortable" ? 32 : 20

  return (
    <div
      className="grid grid-cols-1 lg:grid-cols-12 items-stretch"
      style={{
        gap: 0,
        paddingTop: density === "comfortable" ? 32 : 24,
        paddingBottom: density === "comfortable" ? 32 : 24,
      }}
    >
      {/* LEFT FLANK — FOCUS (top) + EDGE (bottom) · dashed right border */}
      {showSpecs && (
        <div
          className="hidden lg:flex lg:col-span-3 flex-col justify-center"
          style={{
            borderRight: `1px dashed ${VANTARY.rule}`,
            paddingRight: 24,
          }}
        >
          {leftStations.map((s, i) => (
            <React.Fragment key={`L-${i}`}>
              {i > 0 && (
                <div
                  aria-hidden
                  className="my-1"
                  style={{ height: 1, borderTop: `1px dashed ${VANTARY.rule}`, opacity: 0.7 }}
                />
              )}
              <BriefingFlankStation
                icon={s.icon}
                label={s.label}
                big={s.big}
                descriptor={s.descriptor}
                insight={s.insight}
                accent={s.accent}
                dots={s.dots}
                align="left"
                title={s.title}
                phase={i}
              />
            </React.Fragment>
          ))}
        </div>
      )}

      {/* CENTER — greeting + countdown + AI brief sub-line */}
      <div
        className={`lg:col-span-6 flex flex-col justify-center ${showSpecs ? "lg:px-8" : ""}`}
      >
        <GreetingHeadline
          greeting={greeting}
          name={name}
          sessionName={sessionName}
          opensInMinutes={opensInMinutes}
          isHolographic={isHolographic}
          density={density}
        />

        {/* AI brief provenance sub-line */}
        {density !== "minimal" && (
          <div
            className="flex items-center gap-2 flex-wrap"
            style={{ marginTop: headlineGap - 6 }}
          >
            <Sparkles size={11} strokeWidth={1.5} color={VANTARY.amber} />
            <span
              className="font-mono uppercase"
              style={{
                fontSize: 10,
                letterSpacing: "0.22em",
                color: VANTARY.amber,
                fontWeight: 500,
              }}
            >
              AI BRIEF
            </span>
            <span
              aria-hidden
              style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }}
            />
            <span
              className="font-mono uppercase tabular-nums"
              style={{ fontSize: 10, letterSpacing: "0.22em", color: VANTARY.ashSoft }}
            >
              REFRESHED {refreshedAt}
            </span>
            <span
              aria-hidden
              style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }}
            />
            <span
              className="font-mono uppercase tabular-nums"
              style={{ fontSize: 10, letterSpacing: "0.22em", color: VANTARY.ashSoft }}
            >
              NEXT IN {refreshInMin}M
            </span>
          </div>
        )}
      </div>

      {/* RIGHT FLANK — CAP (top) + RISK (bottom) · dashed left border */}
      {showSpecs && (
        <div
          className="hidden lg:flex lg:col-span-3 flex-col justify-center"
          style={{
            borderLeft: `1px dashed ${VANTARY.rule}`,
            paddingLeft: 24,
          }}
        >
          {rightStations.map((s, i) => (
            <React.Fragment key={`R-${i}`}>
              {i > 0 && (
                <div
                  aria-hidden
                  className="my-1"
                  style={{ height: 1, borderTop: `1px dashed ${VANTARY.rule}`, opacity: 0.7 }}
                />
              )}
              <BriefingFlankStation
                icon={s.icon}
                label={s.label}
                big={s.big}
                descriptor={s.descriptor}
                insight={s.insight}
                accent={s.accent}
                dots={s.dots}
                align="right"
                title={s.title}
                phase={i + 2}
              />
            </React.Fragment>
          ))}
        </div>
      )}
    </div>
  )
}

/* ��─���────────��────────��─────────��────────────���────────���───────���────────────
 *  <BriefingFooter/> — provenance + refresh affordance.
 *
 *  Hairline rule above a small caption that tells the trader where the
 *  briefing came from and when it will refresh. The Refresh icon is a
 *  ghost button — clicking it would re-trigger the AI brief generation
 *  (wired in a later edit when the brief becomes a server-streamed RSC).
 * ─────────────────────────────��─────────────────────────────────────────── */
function BriefingFooter({ refreshedAt = "06:14 UTC", refreshInMin = 14 }: {
  refreshedAt?: string
  refreshInMin?: number
}) {
  // Deprecated in v2 — superseded by <BriefingWhisper/>. Kept as shim.
  const [pressing, setPressing] = useState(false)
  return (
    <div className="flex items-center gap-2 mt-4 pt-3" style={{ borderTop: `1px dashed ${VANTARY.rule}` }}>
      <Sparkles size={11} strokeWidth={1.5} color={VANTARY.amber} />
      <span
        className="font-mono uppercase"
        style={{ fontSize: 10, letterSpacing: "0.18em", color: VANTARY.amber }}
      >
        AI BRIEF
      </span>
      <span style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }} />
      <span
        className="font-mono uppercase tabular-nums"
        style={{ fontSize: 10, letterSpacing: "0.18em", color: VANTARY.ashSoft }}
      >
        REFRESHED {refreshedAt}
      </span>
      <span style={{ width: 3, height: 3, background: VANTARY.rule, borderRadius: 99 }} />
      <span
        className="font-mono uppercase tabular-nums"
        style={{ fontSize: 10, letterSpacing: "0.18em", color: VANTARY.ashSoft }}
      >
        NEXT IN {refreshInMin}M
      </span>
      <button
        type="button"
        aria-label="Refresh AI brief"
        onMouseDown={() => setPressing(true)}
        onMouseUp={() => setPressing(false)}
        onMouseLeave={() => setPressing(false)}
        className="ml-auto inline-flex items-center justify-center rounded-full transition-colors"
        style={{
          width: 22, height: 22,
          background: pressing ? VANTARY.amberWash : "transparent",
          border: `1px solid ${pressing ? VANTARY.amberHalo : VANTARY.rule}`,
        }}
      >
        <RefreshCw size={11} strokeWidth={1.5} color={pressing ? VANTARY.amber : VANTARY.ash} />
      </button>
    </div>
  )
}

/* ──────────────────────────────────────────────────────────��──────────────
 *  <BriefingWhisper/>
 *  ────────────────────────────��──────────���───���────────��────����──────────────
 *  The italic AI quote line that closes the briefing band. Reads like a
 *  pull-quote in an editorial — left-anchored AI BRIEF pip, italic quote
 *  in the middle, refresh ghost button on the right.
 *
 *  The quote is the philosophical / behavioural takeaway the AI wants
 *  the trader to internalise before they place a trade. It is intentionally
 *  short and human; it is NOT another data point.
 * ──────────────────��─────────────��─�����───────────���──────────��────────────── */
function BriefingWhisper({
  quote,
  density,
}: {
  quote: string
  density: BriefingDensity
}) {
  const [pressing, setPressing] = useState(false)
  if (density === "minimal") return null

  return (
    <div
      className="flex items-center gap-4 flex-wrap"
      style={{
        paddingTop: 18,
        paddingBottom: 4,
      }}
    >
      {/* Left · provenance pip */}
      <div className="inline-flex items-center gap-2 shrink-0">
        <Sparkles size={11} strokeWidth={1.5} color={VANTARY.amber} />
        <span
          className="font-mono uppercase"
          style={{
            fontSize: 10,
            letterSpacing: "0.22em",
            color: VANTARY.amber,
            fontWeight: 500,
          }}
        >
          AI BRIEF
        </span>
      </div>

      {/* Center · italic quote */}
      <p
        className="font-sans italic flex-1"
        style={{
          fontSize: 14,
          color: VANTARY.paperDim,
          lineHeight: 1.5,
          minWidth: 200,
        }}
      >
        <span style={{ color: VANTARY.ash, fontStyle: "normal" }}>“</span>
        {quote}
        <span style={{ color: VANTARY.ash, fontStyle: "normal" }}>”</span>
      </p>

      {/* Right · refresh ghost button */}
      <button
        type="button"
        aria-label="Refresh AI brief"
        onMouseDown={() => setPressing(true)}
        onMouseUp={() => setPressing(false)}
        onMouseLeave={() => setPressing(false)}
        className="inline-flex items-center justify-center rounded-full transition-colors shrink-0"
        style={{
          width: 26, height: 26,
          background: pressing ? VANTARY.amberWash : "transparent",
          border: `1px solid ${pressing ? VANTARY.amberHalo : VANTARY.rule}`,
        }}
      >
        <RefreshCw
          size={12}
          strokeWidth={1.5}
          color={pressing ? VANTARY.amber : VANTARY.ash}
        />
      </button>
    </div>
  )
}

/* ═══════════════════════════════════════════════════════════════════════════
 * ╔═════════════════════════════════════���═════════════════════════════════╗
 * ║                                                                       ║
 * ║         J A R V I S   W E L C O M E   B A N D                         ║
 * ║         ─────��────���─��────────────��────────                            ║
 * ║                                                                       ║
 * ║   "At your service, Marcus."                                          ║
 * ║                                                                       ║
 * ║   The first thing you see when the dashboard loads. A welcoming,      ║
 * ║   editorial Jarvis-style overview band that wraps the existing        ║
 * ║   Vantary Oracle Ask-Me-Anything pill with:                           ║
 * ║                                                                       ║
 * ║       1. AT YOUR SERVICE eyebrow with framed hairlines                ║
 * ║       2. Welcome line + context (accounts under management)           ║
 * ║       3. 4-station period overview (TODAY · WEEK · MONTH · YTD)       ║
 * ║       4. The existing <VantaryOracle/> Ask-Me-Anything pill           ║
 * ║       5. Quick-action chips row · "Compare Mentors", etc.             ║
 * ║                                                                       ║
 * ║   Goal: the trader has a complete picture of what they're managing    ║
 * ║   and how it's performing BEFORE they scroll. The trader's briefing   ���
 * ���   below answers "what should I do today"; this band answers "what     ║
 * ║   shape am I in overall."                                             ║
 * ║                                                                       ║
 * ╚������══════════���══════��═══���════��════════����═══���═���══��������══════���══��═���══════���════╝
 * ══��═══════════��═════════��══��════����══���══════════������═════���════��═══════════ */

/* ──────────���──��────────────────────────────����────��─────────────────────────
 *  <PeriodOverviewCell/>
 *  ─���─────────────��─────────────────────────────────────────────────────────
 *  A single column in the Jarvis period-overview row. Shows:
 *      eyebrow      "TODAY" / "WEEK" / "MONTH" / "YTD"
 *      big value    +$135  (24pt mono · tabular-nums)
 *      delta        +0.04% vs ⌃ YESTERDAY  (small mono caps · amber if positive)
 *
 *  Hover: amberWash background + halo on the big value.
 * ───���───────────────────���───────────────────────────────────────────────── */
function PeriodOverviewCell({
  eyebrow,
  big,
  delta,
  comparison,
  positive = true,
  title,
}: {
  eyebrow: string
  big: string
  delta: string
  comparison: string
  positive?: boolean
  title?: string
}) {
  const [hover, setHover] = useState(false)
  const valueColor = positive ? VANTARY.amber : VANTARY.paperDim
  return (
    <motion.div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      title={title}
      className="flex flex-col cursor-default relative"
      style={{ padding: "16px 20px" }}
      animate={{ background: hover ? VANTARY.amberWash : "transparent" }}
      transition={{ duration: 0.18, ease: EASE_V }}
    >
      <span
        className="font-mono uppercase mb-2"
        style={{
          fontSize: 9.5,
          letterSpacing: "0.22em",
          color: hover ? VANTARY.amber : VANTARY.ashSoft,
          fontWeight: 500,
          transition: "color 180ms",
        }}
      >
        {eyebrow}
      </span>
      <motion.span
        className="font-mono tabular-nums mb-1.5"
        style={{
          fontSize: 24,
          lineHeight: 1.0,
          fontWeight: 500,
          letterSpacing: "-0.022em",
          color: VANTARY.paper,
        }}
        animate={{
          textShadow: hover
            ? `0 0 12px ${VANTARY.amberHalo}`
            : `0 0 0px transparent`,
        }}
        transition={{ duration: 0.25 }}
      >
        {big}
      </motion.span>
      <div className="flex items-center gap-1.5">
        <ArrowUpRight
          size={11}
          strokeWidth={1.75}
          color={valueColor}
          style={{ transform: positive ? "rotate(0deg)" : "rotate(90deg)" }}
        />
        <span
          className="font-mono uppercase tabular-nums"
          style={{
            fontSize: 10,
            letterSpacing: "0.16em",
            color: valueColor,
            fontWeight: 500,
          }}
        >
          {delta}
        </span>
        <span
          className="font-mono uppercase"
          style={{
            fontSize: 9,
            letterSpacing: "0.18em",
            color: VANTARY.ash,
          }}
        >
          {comparison}
        </span>
      </div>
    </motion.div>
  )
}

/* ─────────────────────────────────────��───────────��─────────────������────────
 *  <JarvisQuickActionChip/>
 *  ────────────────────�����─��─────���────────────────────��───────────────────────
 *  Pill-shaped quick action used in the JarvisWelcomeBand action row.
 *  Hairline border + amber tint on hover. The chip carries an icon, label,
 *  and an optional kbd-style keyboard hint.
 * ───��───────��──────────────────────────────���─────���─────────────────����───── */
function JarvisQuickActionChip({
  icon: Icon,
  label,
  hint,
  onClick,
}: {
  icon: any
  label: string
  hint?: string
  onClick?: () => void
}) {
  const [hover, setHover] = useState(false)
  return (
    <motion.button
      type="button"
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onClick={onClick}
      className="inline-flex items-center gap-2 rounded-full transition-colors"
      style={{
        padding: "7px 14px",
        background: hover ? VANTARY.amberWash : "transparent",
        border: `1px solid ${hover ? VANTARY.amberHalo : VANTARY.rule}`,
      }}
      whileTap={{ scale: 0.97 }}
    >
      <Icon size={12} strokeWidth={1.5} color={hover ? VANTARY.amber : VANTARY.ash} />
      <span
        className="font-mono uppercase whitespace-nowrap"
        style={{
          fontSize: 10.5,
          letterSpacing: "0.18em",
          color: hover ? VANTARY.amber : VANTARY.paper,
          fontWeight: 500,
          transition: "color 180ms",
        }}
      >
        {label}
      </span>
      {hint && (
        <span
          className="font-mono uppercase ml-1"
          style={{
            fontSize: 9,
            letterSpacing: "0.16em",
            color: VANTARY.ashSoft,
            padding: "1px 4px",
            border: `1px solid ${VANTARY.rule}`,
            borderRadius: 3,
          }}
        >
          {hint}
        </span>
      )}
    </motion.button>
  )
}

/* ����───────────────────────────────────────────────────────────────────────
 *  <JarvisWelcomeBand/>
 *  ───────────────────��──��────���──────────────────────────────��───��─���────────
 *  The composed Jarvis welcome band. Composition (top → bottom):
 *
 *      ◯ ���� ● AT YOUR SERVICE ── ────���────────── ⌘ K · ASK ──── ◯
 *
 *      Welcome back, Marcus.                                    [LIVE]
 *      Three accounts under management · $324,580 total equity · all systems green.
 *
 *      ┌─────��─────┬───��────────┬────────────┬────────────┐
 *      │ TODAY     │ THIS WEEK  │ THIS MONTH │ YEAR TO    │
 *      │ +$135     │ +$1,247    │ +$4,820    │ +$28,400   │
 *      │ +0.04% ↗  │ +11.1% ↗   │ +18.4% ↗   │ +97.5% ↗   │
 *      │ vs YDAY   │ vs PRIOR   │ vs PRIOR   │ vs JAN 1   │
 *      └───────────┴───��────────┴────────────┴──────���─────┘
 *
 *      [⌘ Sparkles] ASK ME ANYTHING — compare mentors, audits…
 *
 *      [Compare Mentors] [Audit Profile] [Today's Stats] [Schedule Review]
 *
 * ─────────────────�����───���─────────���──────────────────────────────────────── */
/* ═══���══����══════════════════════════════════════════════════��════════════════
 * ╔═════════════════════════════════��═════════════════════════════════════╗
 * ║                                                                       ║
 * ���         T H E   F L I G H T   D E C K  ·  N A V I G A T I O N         ║
 * ║         ───────����───────────────��────────────────���──────               ║
 * ║                                                                       ║
 * ║   The cockpit that lives ABOVE the Ask-Me-Anything pill.              ║
 * ║                                                                       ║
 * ║   Designed around the trader's natural cognitive loop:                ║
 * ║                                                                       ║
 * ║       OBSERVE → CREATE → LEARN → REFLECT                              ║
 * ║                                                                       ║
 * ║   Four "rooms" map 1-to-1 with those mental modes:                    ║
 * ║                                                                       ║
 * ║     ┌────────�����─��────┬����─────��─────────┬��───────��───────┬��─────────��  ║
 * ║     │ MARKET FLOOR   │ THE STUDIO     │ MENTOR HALL    │ REVIEW   │  ║
 * ���     │  (observe)     │  (create)      │  (learn)       │ (reflect)│  ║
 * ║     │                │                │                │          ��  ║
 * ║     │ Signal Room    │ Create Forecast│ Compare Mentors│ Today's  │  ║
 * ║     │ Forecast Room  │ Publish Signal │ Mentor Library │ Stats    │  ║
 * ║     │ Live Charts    │ Journal Entry  │ Replay Sessions│ Audit    │  ║
 * ║     │ News Wire      │ Build Setup    │ Insights Vault │ Schedule │  ║
 * ║     └────────────────����────────────────┴────────────────┴──────────┘  ║
 * ║                                                                       ║
 * ║   Reading the cockpit left-to-right is the same cognitive path the    ║
 * ║   trader instinctively walks every session — first they look at the   ║
 * ║   market (observe), then they decide to act (create), they cross-     ║
 * ║   check against mentors (learn), and finally they reflect on what     ║
 * ║   they did (review). The hairline grid is the architecture; the       ║
 * ║   destinations are the doors.                                         ��
 * ║                                                                       ║
 * ║   Why this lives ABOVE the Ask-Me-Anything pill:                      ║
 * ║   When the user submits a prompt, the entire region BELOW the pill    ��
 * ║   (briefing, equity, etc.) collapses to make room for the AI answer   ║
 * ║   panel. The cockpit must remain visible as persistent navigation     ║
 * ║   so the trader can still reach any room without dismissing the AI    ║
 * ���   conversation.                                                       ║
 * ║                                                                       ║
 * ╚═══════════════════════════════════════���════════���════��═════════════════╝
 * ══════════════════════════════════════════════════════����════════════════ */

/* ───────────────────────────────────────────────���─────���───────────────────
 *  <FlightDeckDestination/>
 *  ──────���─────────────────────��──────────����──────�����─��─────────��─��──────��───
 *  A single navigable row inside a Flight Deck room. Renders as:
 *
 *      [icon]  Destination Name              →  [⌘1]
 *
 *  Hover behaviour:
 *      · row background washes amber
 *      · icon + name brighten to amber
 *      · the arrow translates 2px to the right
 *      · the keyboard hint badge tints amber
 *
 *  Press behaviour:
 *      · row scales 99% briefly (active state cue)
 *      · onSelect callback fires (host wires it to router.push)
 *
 *  Accessibility:
 *      �� semantic <button> with aria-label
 *      · `title` attribute carries the descriptor for tooltips
 *      · keyboard focus ring matches hover state
 * ──────���────────────────────────────��───────────────────────────────────── */
type FlightDeckDestinationDef = {
  icon: any                 // lucide-react component reference
  label: string             // visible name e.g. "Signal Room"
  descriptor?: string       // hover tooltip e.g. "Live signals from your mentors"
  hint?: string             // keyboard shortcut e.g. "1" or "��F"
  onSelect?: () => void     // navigation handler
  status?: "live" | "new" | null
  /* ── ARCHIO ROOM-NAVIGATOR fields (masterplan P5, drawer re-map) ──────
     `system`     — which of the 8 official systems this door belongs to.
                    Rendered as an italic micro-eyebrow that groups the
                    chips inside the open drawer (2 systems per room on
                    the 3×3 ecosystem map, expressed as grouped pairs).
     `templateId` — EXPLICIT template wiring. The old label→template
                    lookup silently died whenever a chip label was
                    shortened for width ("Signals" ≠ "Signal Room"), which
                    left most cockpit doors as dead no-ops. An explicit id
                    can never rot when labels change, and it also lets a
                    room borrow a template registered under another room
                    id (e.g. THE STUDIO housing review.todays-stats).
     `askPrompt`  — routes the click into the Intelligence Chamber as a
                    REAL Ask-Archio question (systems that have no
                    template yet get a live AI door instead of a dead
                    button — Agent Market, Scenario Lab, …).
     `event`      — dispatches a window CustomEvent (e.g. the community
                    controls-mode toggle `flight-deck-hub:toggle`). */
  system?: string
  templateId?: string
  askPrompt?: string
  event?: string
  /* `href` — the HIGHEST-priority species: navigates to a REAL page of
     the platform (/communities, /forecast, /intelligence, /hub, /nexus,
     /copilot, /cockpit, /history, /profile). The rooms are the
     navigator to the site's actual working features — a door that opens
     a real surface always beats one that paints a warming stub. */
  href?: string
}

function FlightDeckDestination({
  icon: Icon,
  label,
  descriptor,
  hint,
  onSelect,
  status,
  accent,
}: FlightDeckDestinationDef & { accent: ThemeAccent }) {
  /* ─────────────────────────────��────────────────────────────────────────
     Theme-aware glass refit.
     The accent is taken from the ACTIVE Vantary theme (Teal / Cyber /
     Neural / Quantum / Solar / Light / Obsidian). Every visual cue that
     previously hardcoded amber now reads from `accent.{hex,rgb,halo}`:
       · hover row wash      → accent.rgb @ low alpha
       · hover hairline      → accent.rgb @ mid alpha
       · icon active color   → accent.hex
       · "live" LED pip      → accent.hex + accent halo ring
       · "new" badge         → accent-tinted glass pill
       · trailing arrow      → accent.hex on hover
       · keyboard hint chip  → accent-aware border + tint
     All callbacks, a11y semantics, and the `whileTap` press cue are
     preserved verbatim.
  ─────────────��──────────────────────────────────────────────────��───── */
  const [hover, setHover] = useState(false)

  /* COMPACTED CHIP LAYOUT
   * ─────────────────────────────────────────────────────────────────────
   * The chip lives inside a 2-column grid within each narrow room
   * column, so every spare horizontal pixel matters. Four tweaks land
   * every default room label on a single, non-ellipsised line:
   *   · padding `10px 12px` → `8px 4px 8px 2px` (icon hugs the left
   *     edge; trailing padding shrinks because there's no trailing
   *     chrome anymore)
   *   · gap-3 (12px) → 6px between icon box and label
   *   · icon bounding box 22 → 16, glyph 14 → 13 (still tappable,
   *     reclaims ~6px of horizontal real estate per chip)
   *   · label fontSize 13.5 → 12.5, letter-spacing -0.005em → -0.012em
   *     (denser glyph rhythm; reads sharper at this size)
   * `truncate` is kept as a safety net but the default room labels no
   * longer hit it after these changes + the label shortening below. */
  return (
    <motion.button
      type="button"
      title={descriptor}
      aria-label={`${label}${descriptor ? " — " + descriptor : ""}`}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onClick={onSelect}
      whileTap={{ scale: 0.99 }}
      className="group relative flex items-center w-full text-left"
      style={{
        padding: "8px 4px 8px 2px",
        gap: 6,
        borderRadius: 8,
        background: hover
          ? `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.07)} 0%, ${vgRgba(accent.rgb, 0.02)} 55%, transparent 100%)`
          : "transparent",
        transition: "background 200ms ease",
      }}
    >
      {/* Hover hairline — a barely-there 1px line under the row */}
      <motion.span
        aria-hidden
        className="absolute left-1 right-1 bottom-0"
        style={{
          height: 1,
          background: `linear-gradient(90deg, transparent 0%, ${vgRgba(accent.rgb, 0.32)} 50%, transparent 100%)`,
          transformOrigin: "center",
        }}
        initial={{ scaleX: 0, opacity: 0 }}
        animate={{ scaleX: hover ? 1 : 0, opacity: hover ? 1 : 0 }}
        transition={{ duration: 0.24, ease: EASE_V }}
      />

      {/* Leading icon — 16×16 box, glyph 13px. Hugged to the left edge
          via the parent's `padding-left: 2px`. */}
      <span
        className="inline-flex items-center justify-center shrink-0"
        style={{ width: 16, height: 16 }}
      >
        <Icon
          size={13}
          strokeWidth={1.5}
          color={hover ? accent.hex : VG_VT.ash}
          style={{ transition: "color 180ms" }}
        />
      </span>

      {/* Destination name — denser type, tighter tracking, still
          truncates as a last-resort safety net. */}
      <span
        className="font-sans flex-1 truncate"
        style={{
          fontSize: 12.5,
          color: hover ? VG_VT.paper : VG_VT.paperDim,
          fontWeight: 500,
          letterSpacing: "-0.012em",
          transition: "color 180ms",
        }}
      >
        {label}
      </span>

      {/* ── ARCHIO surgical cleanup ─────────────────────────────────────��
            All trailing chrome (live pip, NEW badge, arrow, hint chip)
            removed at the trader's request — the chip is now reduced to
            its essence: icon + name. The hover row-wash and the
            underline hairline still telegraph interactivity, and `status`
            / `hint` are kept on the type so the catalog data shape is
            unchanged. Anything that wants to surface "live" or shortcut
            metadata can read them from the FlightDeckDestinationDef
            without re-rendering chrome on this row. */}
    </motion.button>
  )
}

/* ───────────���───────────────���─────────────────────────────────────────────
 *  <FlightDeckRoom/>
 *  ───────────��─────────��───────────────────────────────────────���──��────────
 *  A single column in the cockpit. Layout (top → bottom):
 *
 *      [room icon] ROOM NAME
 *      tagline · "what's happening right now"
 *      ────────────────────��────────────────  hairline divider
 *      [destination 1]
 *      [destination 2]
 *      [destination 3]
 *      [destination 4]
 *
 *  Visual treatment:
 *      · The room itself has NO border — vertical hairlines are owned by
 *        the parent <FlightDeckCockpit/> grid so they stay perfectly
 *        aligned across columns.
 *      · A 1px amber accent bar appears on the room's TOP edge when the
 *        cursor enters the room (any destination triggers it).
 *      · Destinations are stacked vertically with 2px gap; each row owns
 *        its own hover state.
 *
 *  Accessibility:
 *      · The room renders as <section> with aria-labelledby on the
 *        room-name heading.
 * ────────────────────────────────────────────────────��───���──────────────── */
type FlightDeckRoomDef = {
  id: string                    // stable id used for aria + key
  icon: any                     // lucide component for the room header
  name: string                  // ROOM NAME e.g. "MARKET FLOOR"
  tagline: string               // small italic tagline
  destinations: FlightDeckDestinationDef[]
}

function FlightDeckRoom({
  room,
  isOpen = false,
  stagger = 0,
  accent,
}: {
  room: FlightDeckRoomDef
  /** Controlled open state from parent cockpit - ALL rooms open together */
  isOpen?: boolean
  /** Active theme accent (theme-aware glow / hairline / hover colors). */
  accent: ThemeAccent
  /** Index of this room within the row for stagger animation */
  stagger?: number
}) {
  const reduceMotion = useReducedMotion()
  const open = isOpen
  const RoomIcon = room.icon
  const headingId = `flight-deck-${room.id}-heading`

  /* ── HOVER-TO-OPEN behavior ──────────��────────────────────────────────��
     All rooms open together when hovering anywhere on the cockpit row.
     Clean, unified reveal experience.
  ───────────────────────────────────────────────────────────────���─────── */

  /* ── PER-ROOM HOVER SHEEN ─────────────────────��────────���───────────────
     The trader moved the "flashy" one-shot shimmer OFF the Ask-Vantary
     prompt suggestions and asked for it to live HERE instead — on each
     individual room label band (MARKET FLOOR / THE STUDIO / MENTOR HALL
     / COLLECTIVE). When the mouse enters any one room, that single room
     plays a slow accent sheen sweep across its own header area. The
     other rooms still open in lockstep (controlled by `isOpen`) but
     only the room directly under the cursor flashes.

     The shimmer span is conditionally MOUNTED on `selfHover === true`
     with `animation-iteration-count: 1` so it plays EXACTLY ONCE per
     hover-enter and never loops. Duration is intentionally generous
     (≈1.6s vs the old 0.85s) for that slow, considered, billion-luxury
     feel the trader described. */
  const [selfHover, setSelfHover] = React.useState(false)
  const sheenKf = `flight-room-sheen-${room.id}`
  /* Rising light-bubble particles — mounted only while the cursor is
     inside THIS room (never neighbours), looping softly upward like
     champagne in glass. Each bubble gets a deterministic left offset,
     size, duration and delay from its index so the pattern is organic
     but never random-on-render (no hydration mismatch). */
  const bubbleKf = `flight-room-bubbles-${room.id}`

  // Stagger keyframe — each destination delays by index × stagger.
  const STAGGER = 0.045

  /* ──────────────────────────────────────────────────────────────────────
     Forecast-room glass refit.
     The room now layers three subtle effects behind the content instead
     of a single solid wash:
       1. A vertical radial-gradient glow that fades from the top, so the
          room reads as illuminated from above (matches the GlassCard
          inner highlight).
       2. A gradient top accent strip that fades at both ends instead of
          a hard 1px bar across the column.
       3. A bottom hairline separator that lengthens AND dims out at the
          edges using a 3-stop gradient — feels carved, not stamped.
     Open / stagger behaviour, a11y, and prop contract are unchanged.
  ───���───────────────────────────────���───���────────────────────────────── */
  return (
    <section
      aria-labelledby={headingId}
      className="relative flex flex-col"
      style={{ padding: "14px 14px", overflow: "hidden" }}
      onMouseEnter={() => setSelfHover(true)}
      onMouseLeave={() => setSelfHover(false)}
    >
      {/* ── PER-ROOM ONE-SHOT SHEEN · slow, luxe, single sweep ─────────
            Plays exactly once per hover-enter — wipes a soft accent
            tinted band across the room from left to right, then sits
            offscreen until the cursor leaves and re-enters. The
            animation is set to `animation-iteration-count: 1` and
            duration ≈1.6s, more than DOUBLE the speed of the old
            prompt-row shimmer, so it reads as a slow considered
            "reveal" rather than a quick flash. Mounted only while
            `selfHover === true` so neighbouring rooms never play
            this animation even though they all open in lockstep. */}
      {!reduceMotion && selfHover && (
        <span
          aria-hidden
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 1,
          }}
        >
          <span
            style={{
              position: "absolute",
              top: 0, bottom: 0,
              width: "55%",
              left: 0,
              background: `linear-gradient(110deg, transparent 0%, ${vgRgba(accent.rgb, 0.30)} 50%, transparent 100%)`,
              filter: "blur(3px)",
              animation: `${sheenKf} 1.6s cubic-bezier(0.22, 0.61, 0.36, 1) 1 forwards`,
            }}
          />
          <style>{`
            @keyframes ${sheenKf} {
              0%   { transform: translateX(-110%); opacity: 0; }
              18%  {                               opacity: 1; }
              82%  {                               opacity: 1; }
              100% { transform: translateX(220%);  opacity: 0; }
            }
          `}</style>
        </span>
      )}

      {/* ── RISING LIGHT BUBBLES · per-room hover particles ─���──────────
            Six accent-tinted orbs float up from the room floor while the
            cursor rests inside — the "champagne" cue that this room is
            alive and pressurised. Deterministic per-index offsets (no
            Math.random → no hydration drift), infinite loop while
            hovered, unmounts the instant the cursor leaves. Skipped
            entirely under prefers-reduced-motion. */}
      {!reduceMotion && selfHover && (
        <span
          aria-hidden
          style={{
            position: "absolute",
            inset: 0,
            pointerEvents: "none",
            overflow: "hidden",
            zIndex: 1,
          }}
        >
          {[0, 1, 2, 3, 4, 5].map((b) => (
            <span
              key={b}
              style={{
                position: "absolute",
                bottom: -6,
                left: `${(14 + b * 59) % 82}%`,
                width: 3 + (b % 3),
                height: 3 + (b % 3),
                borderRadius: 9999,
                background: vgRgba(accent.rgb, 0.55),
                boxShadow: `0 0 ${6 + (b % 3) * 4}px ${vgRgba(accent.rgb, 0.5)}`,
                filter: "blur(0.4px)",
                opacity: 0,
                animation: `${bubbleKf} ${2.2 + (b % 4) * 0.55}s cubic-bezier(0.22, 0.61, 0.36, 1) ${b * 0.34}s infinite`,
              }}
            />
          ))}
          <style>{`
            @keyframes ${bubbleKf} {
              0%   { transform: translateY(0) translateX(0); opacity: 0; }
              14%  { opacity: 0.85; }
              62%  { opacity: 0.45; }
              100% { transform: translateY(-88px) translateX(7px); opacity: 0; }
            }
          `}</style>
        </span>
      )}

      {/* ── Top accent strip — fades at both ends on hover ───────────── */}
      <motion.span
        aria-hidden
        className="absolute left-0 right-0 top-0"
        style={{
          height: 1,
          background: `linear-gradient(90deg, transparent 0%, ${vgRgba(accent.rgb, 0.55)} 50%, transparent 100%)`,
          transformOrigin: "center",
        }}
        initial={{ scaleX: 0, opacity: 0 }}
        animate={{ scaleX: open ? 1 : 0, opacity: open ? 1 : 0 }}
        transition={{ duration: 0.32, ease: EASE_V }}
      />

      {/* ── Vertical illumination glow on hover — "top-down lit" ─────── */}
      <motion.span
        aria-hidden
        className="absolute inset-0 pointer-events-none"
        style={{
          background: `radial-gradient(ellipse 120% 80% at 50% 0%, ${vgRgba(accent.rgb, 0.06)} 0%, transparent 70%)`,
        }}
        initial={{ opacity: 0 }}
        animate={{ opacity: open ? 1 : 0 }}
        transition={{ duration: 0.28, ease: EASE_V }}
      />

      {/* ── Room header · CENTERED with PERFECT vertical balance ─────────
            Grid: [1fr · auto · 1fr]. The center cluster (icon · label ·
            mirror icon) lives in the AUTO column so it is always exactly
            centered regardless of label length. Left and right hairlines
            fill the 1fr cells equally, guaranteeing the top and bottom
            of the row span the same horizontal distance — no more visual
            asymmetry between STUDIO (6 chars) and MENTOR HALL (11 chars).
            Hairlines are theme-tinted at rest (never neutral gray) and
            brighten on open. */}
      <div
        className="relative grid items-center gap-2"
        style={{ gridTemplateColumns: "1fr auto 1fr", marginBottom: -2 }}
      >
        {/* Left feeder hairline — accent-tinted at rest, brighter on open */}
        <motion.span
          aria-hidden
          className="min-w-0 justify-self-stretch"
          style={{ height: 1, transformOrigin: "right" }}
          animate={{
            background: open
              ? `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.06)} 0%, ${vgRgba(accent.rgb, 0.55)} 100%)`
              : `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.04)} 0%, ${vgRgba(accent.rgb, 0.22)} 100%)`,
            scaleX: open ? 1 : 0.92,
            opacity: open ? 1 : 0.85,
          }}
          transition={{ duration: 0.32, ease: EASE_V }}
        />

        {/* CENTER cluster — single icon + label.
            The old "icon · NAME · mirror-icon" grammar was visually
            noisy because each room name has a different character
            count (MARKET FLOOR 12 / THE STUDIO 10 / MENTOR HALL 11 /
            THE COLLECTIVE 14), so the wrapped triplet rendered at
            four different widths. With a single leading icon, every
            header is a uniform `[icon] NAME` pair and the parent
            `1fr auto 1fr` grid still centers the cluster inside its
            column — so all four headers now sit on the same optical
            centerline across the cockpit footer. */}
        <div className="inline-flex items-center gap-2 justify-self-center whitespace-nowrap">
          <motion.span
            aria-hidden
            animate={{ scale: open ? 1.1 : 1, rotate: open ? -4 : 0 }}
            transition={{ duration: 0.28, ease: EASE_V }}
            style={{ display: "inline-flex" }}
          >
            <RoomIcon
              size={12}
              strokeWidth={1.5}
              color={open ? accent.hex : vgRgba(accent.rgb, 0.55)}
            />
          </motion.span>

          <h3
            id={headingId}
            className="font-mono uppercase"
            style={{
              fontSize: 10.5,
              letterSpacing: "0.32em",
              color: open ? accent.hex : vgRgba(accent.rgb, 0.85),
              fontWeight: 500,
              transition: "color 180ms, text-shadow 220ms",
              margin: 0,
              textShadow: open
                ? `0 0 10px ${vgRgba(accent.rgb, 0.4)}`
                : "none",
            }}
          >
            {room.name}
          </h3>
        </div>

        {/* Right feeder hairline — mirrored */}
        <motion.span
          aria-hidden
          className="min-w-0 justify-self-stretch"
          style={{ height: 1, transformOrigin: "left" }}
          animate={{
            background: open
              ? `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.55)} 0%, ${vgRgba(accent.rgb, 0.06)} 100%)`
              : `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.22)} 0%, ${vgRgba(accent.rgb, 0.04)} 100%)`,
            scaleX: open ? 1 : 0.92,
            opacity: open ? 1 : 0.85,
          }}
          transition={{ duration: 0.32, ease: EASE_V }}
        />
      </div>

      {/* ���─ Tagline · centered under the room name ─────────���────────────
            Symmetric breathing contract: top side of the closed band is
            14px (section padding) �� title row; bottom side mirrors with
            14px (section padding) → italic. No negative-margin hacks
            here, no orphan hairline below — the hairline separator now
            lives INSIDE the destinations drawer (see below) so it only
            appears when there are actual destinations to separate from.
            This is what gives the closed-state band its luxury rhythm:
            equal whitespace top and bottom around the protagonist
            content, nothing floating in dead space. */}
      <motion.p
        className="relative font-sans italic text-center text-balance"
        style={{
          fontSize: 11.5,
          lineHeight: 1.4,
          margin: "0 auto",
          marginTop: 2,
          letterSpacing: "0.005em",
          maxWidth: "85%",
        }}
        animate={{
          color: open ? VG_VT.paper : VG_VT.paperDim,
        }}
        transition={{ duration: 0.22, ease: EASE_V }}
      >
        {room.tagline}
      </motion.p>

      {/* ── Destinations drawer · height-animated ──────��────────────────────
            Hairline separator now lives INSIDE this drawer so it ONLY
            appears when the drawer is open. When closed, the band ends
            cleanly at the italic — symmetric whitespace top + bottom
            around the protagonist content, no orphan elements. */}
      <motion.div
        className="relative overflow-hidden"
        initial={false}
        animate={{ height: open ? "auto" : 0, opacity: open ? 1 : 0 }}
        transition={{ duration: 0.32, ease: EASE_V }}
      >
        {/* Hairline separator removed — the drawer now opens directly
            into the destinations grid with a small top margin for
            breathing room. The italic subheader above (in the closed
            band) reads as a clean handoff into the destinations on
            hover, with no extra horizontal line in between. */}

        {/* Destinations cascade in with stagger ���──────���──────────────────
              Layout: 2-column grid so each room presents its destinations
              as a tidy pair-per-row tableau (e.g. Signal Room ┊ Forecast
              Room on row 1, Live Charts ┊ News Wire on row 2). This is
              the luxury-airline cabin layout — paired seats, never a
              single dangling row — and it halves the vertical footprint
              of the open drawer while keeping each destination at full
              tap-target width. `auto-rows-min` prevents Flex/Grid from
              stretching uneven rows; `gap-x-3` gives a clean alley
              between the two columns. */}
        <motion.div
          className="grid grid-cols-2 gap-x-3 gap-y-0.5 auto-rows-min pt-3"
          initial="closed"
          animate={open ? "open" : "closed"}
          variants={{
            open: {
              transition: {
                staggerChildren: STAGGER,
                delayChildren: 0.04 + stagger * 0.06,
              },
            },
            closed: {
              transition: {
                staggerChildren: 0.02,
                staggerDirection: -1,
              },
            },
          }}
        >
          {/* ── SYSTEM-GROUPED DOORS · masterplan P5 ──────────────────
                Destinations are grouped by their `system` tag into the
                room's 2-3 official systems. Each group opens with an
                italic micro-eyebrow ([glowing dot] system name ──
                hairline) that spans both columns, then its paired door
                chips. Grouping preserves catalog order and degrades
                gracefully — untagged destinations render chip-only. */}
          {(() => {
            type Grp = { system: string | null; items: { d: FlightDeckDestinationDef; i: number }[] }
            const groups: Grp[] = []
            room.destinations.forEach((d, i) => {
              const sys = d.system ?? null
              const last = groups[groups.length - 1]
              if (last && last.system === sys) last.items.push({ d, i })
              else groups.push({ system: sys, items: [{ d, i }] })
            })
            const chipVariants = {
              open: {
                opacity: 1,
                y: 0,
                filter: reduceMotion ? "none" : "blur(0px)",
                transition: { duration: 0.24, ease: EASE_V },
              },
              closed: {
                opacity: 0,
                y: -4,
                filter: reduceMotion ? "none" : "blur(1px)",
                transition: { duration: 0.15, ease: EASE_V },
              },
            }
            return groups.map((g, gi) => (
              <React.Fragment key={`${room.id}-g${gi}`}>
                {g.system && (
                  <motion.div
                    className="col-span-2 min-w-0 flex items-center gap-1.5"
                    style={{ marginTop: gi === 0 ? 0 : 7 }}
                    variants={chipVariants}
                  >
                    {/* glowing system pip */}
                    <span
                      aria-hidden
                      className="shrink-0 rounded-full"
                      style={{
                        width: 3,
                        height: 3,
                        background: accent.hex,
                        boxShadow: `0 0 5px ${vgRgba(accent.rgb, 0.7)}`,
                      }}
                    />
                    {/* italic system eyebrow — the 8-system map, spoken
                        in the cockpit's own voice */}
                    <span
                      className="font-sans italic uppercase whitespace-nowrap"
                      style={{
                        fontSize: 8.5,
                        letterSpacing: "0.18em",
                        fontWeight: 500,
                        color: vgRgba(accent.rgb, 0.75),
                      }}
                    >
                      {g.system}
                    </span>
                    {/* trailing hairline — carves the group boundary */}
                    <span
                      aria-hidden
                      className="min-w-0 flex-1"
                      style={{
                        height: 1,
                        background: `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.28)} 0%, transparent 100%)`,
                      }}
                    />
                  </motion.div>
                )}
                {g.items.map(({ d, i }) => (
                  <motion.div
                    key={`${room.id}-${i}`}
                    className="min-w-0"
                    variants={chipVariants}
                  >
                    <FlightDeckDestination {...d} accent={accent} />
                  </motion.div>
                ))}
              </React.Fragment>
            ))
          })()}
        </motion.div>
      </motion.div>
    </section>
  )
}

/* ────────��─────────────���──────────────────────────────────────────────────
 *  <FlightDeckCockpit/>
 *  ─────────────────────────────────────────────────────────────────────────
 *  The 4-room navigation grid. On lg screens the rooms render in one row
 *  (1×4); on mobile they collapse to a 2×2 grid with horizontal hairlines
 *  between the rows.
 *
 *  Hairline architecture:
 *      · Top + bottom 1px borders bound the cockpit
 *      · Vertical 1px hairlines separate adjacent rooms
 *      · On mobile (2×2) a horizontal 1px hairline separates rows 1 & 2
 *
 *  The cockpit itself owns ALL hairlines so room components stay clean
 *  and perfectly aligned regardless of breakpoint.
 * ────────────��──────────────────────��────��─────��───��────────────────────── */
function FlightDeckCockpit({ rooms, onCustomize }: { rooms: FlightDeckRoomDef[], onCustomize?: () => void }) {
  /* ��─ HOVER TO OPEN — all rooms open together ──────────────────────────���
     When cursor enters ANY room, ALL rooms open simultaneously.
     This creates a unified cockpit reveal experience.
  ───────────────────────────────────────────────────────────────────── */
  const [rowOpen, setRowOpen] = useState(false)

  /* ── Universal Template Engine bridge ───────────────────────────────��─
     When a viewport context is mounted above us, every destination's
     `onSelect` resolves to opening the matching template above the
     TradingView chart. When the context is null (e.g. cockpit reused
     in a context without the viewport), clicks remain no-ops — the
     destinations stay informational, exactly as they were before.
  ───����────────────────���──────��────────────��───────────────────────��──��� */
  const viewportApi = useFlightDeckViewportContext()
  /* Ask Vantary state machine — clicking a cockpit destination must
     advance the FSM into `submitted`/`answering`, otherwise the
     <AskAnswerSurface/> (which hosts the FlightDeckViewportSurface
     where templates paint) stays collapsed at height:0 and the
     resolved template renders into a hidden box. */
  const askState = useAskVantaryState()
  const enrichedRooms = useMemo<FlightDeckRoomDef[]>(() => {
    if (!viewportApi) return rooms
    return rooms.map((room) => ({
      ...room,
      destinations: room.destinations.map((d) => {
        const userOnSelect = d.onSelect

        /* ── door species 0 · PAGE — real navigation, highest priority.
              These are the platform's actual features (community search,
              forecast journal, market intelligence, collab hub, …); a
              real page always outranks any in-dashboard painting. */
        if (d.href) {
          const target = d.href
          return {
            ...d,
            onSelect: () => {
              userOnSelect?.()
              window.location.assign(target)
            },
          }
        }

        /* ── door species 1 · TEMPLATE — explicit id first (immune to
              label shortening), legacy label-lookup as fallback so any
              older catalog entries keep working. */
        const tid =
          (d.templateId as FlightDeckTemplateId | undefined) ??
          templateIdForDestinationLabel(room.id as FlightDeckRoomId, d.label)
        if (tid) {
          return {
            ...d,
            onSelect: () => {
              // Open the answer surface so the template is visible…
              askState.submit(d.label, d.label)
              askState.markAnswerReady(d.label)
              // …then paint the matching template inside it.
              viewportApi.open(tid)
              // Preserve any caller-defined behaviour (analytics, etc.).
              userOnSelect?.()
            },
          }
        }

        /* ── door species 2 · ASK — a REAL Ask-Archio question. Mirrors
              the AskVantaryBar submit path (submit + markAnswerReady) and
              CLOSES the viewport so the chamber discriminator
              (isAnswering && activeId == null) engages the Intelligence
              Chamber, which then streams the live answer. */
        if (d.askPrompt) {
          const prompt = d.askPrompt
          return {
            ...d,
            onSelect: () => {
              viewportApi.close()
              askState.submit(prompt, d.label)
              askState.markAnswerReady(prompt)
              userOnSelect?.()
            },
          }
        }

        /* ── door species 3 · EVENT — window CustomEvent dispatch. */
        if (d.event) {
          const eventName = d.event
          return {
            ...d,
            onSelect: () => {
              window.dispatchEvent(new CustomEvent(eventName))
              userOnSelect?.()
            },
          }
        }

        return d
      }),
    }))
  }, [rooms, viewportApi, askState])

  /* ── Theme-aware glass refit ────���─────────────────────────��───���───────
     The cockpit is a single GlassCard shell whose accent now ROUTES
     through the active VantaryTheme:
       · 22px radius, 24px backdrop-blur, top inner highlight, theme
         accent corner glow that intensifies on hover.
       · Vertical / horizontal dividers stay neutral-white-alpha so they
         read consistently across all 7 themes.
       · The accent is captured once here and threaded down to every
         room and destination, so the entire deck retints in a single
         render when the theme changes.
     Behaviour: hover-to-open semantics, the viewport bridge, and the
     `displayRooms.slice(0, 4)` cap remain identical.
  ─────────────────────────────────────���──────────────────────────────── */
  const accents = useThemeAccent()
  const accent = accents.primary

  // Only take first 4 rooms
  const displayRooms = enrichedRooms.slice(0, 4)

  return (
    <motion.div
      onMouseEnter={() => setRowOpen(true)}
      onMouseLeave={() => setRowOpen(false)}
      onFocus={() => setRowOpen(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node)) {
          setRowOpen(false)
        }
      }}
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: VG_VT.easeOut }}
      className="relative w-full overflow-hidden"
      style={{
        borderRadius: 22,
        background: `linear-gradient(180deg, ${vgRgba(accent.rgb, 0.05)} 0%, ${vgRgba(accent.rgb, 0.015)} 50%, ${vgRgba(accent.rgb, 0.03)} 100%)`,
        /* border removed — the cockpit now relies on its inner-top
           accent highlight + corner glows for the surface read, so the
           rooms section no longer carries a hard outline across the
           full perimeter. The radius, blur, glow and shadow are kept. */
        border: "none",
        backdropFilter: "blur(24px) saturate(150%)",
        WebkitBackdropFilter: "blur(24px) saturate(150%)",
        boxShadow: `inset 0 1px 0 ${vgRgba(accent.rgb, 0.10)}, 0 8px 24px rgba(0,0,0,0.3), 0 1px 2px rgba(0,0,0,0.2)`,
      }}
    >
      {/* Inner top highlight — theme-tinted wet-glass gleam */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-x-0 top-0 h-px"
        style={{
          background: `linear-gradient(90deg, transparent 5%, ${vgRgba(accent.rgb, 0.4)} 50%, transparent 95%)`,
        }}
      />

      {/* Accent corner glow — intensifies when the cockpit is open */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute"
        style={{
          top: 0,
          right: 0,
          width: 220,
          height: 220,
        }}
        animate={{
          opacity: rowOpen ? 1 : 0.55,
          background: rowOpen
            ? `radial-gradient(circle at top right, ${vgRgba(accent.rgb, 0.16)}, transparent 65%)`
            : `radial-gradient(circle at top right, ${vgRgba(accent.rgb, 0.07)}, transparent 65%)`,
        }}
        transition={{ duration: 0.4, ease: EASE_V }}
      />

      {/* Bottom accent glow — mirrored on the opposite corner for symmetry */}
      <motion.div
        aria-hidden
        className="pointer-events-none absolute"
        style={{
          bottom: 0,
          left: 0,
          width: 220,
          height: 220,
        }}
        animate={{
          opacity: rowOpen ? 0.65 : 0,
          background: `radial-gradient(circle at bottom left, ${vgRgba(accent.rgb, 0.08)}, transparent 65%)`,
        }}
        transition={{ duration: 0.4, ease: EASE_V }}
      />

      {/* ── Rooms grid — relative so dividers can absolute-position ──── */}
      <div className="relative grid grid-cols-2 md:grid-cols-4">
        {displayRooms.map((room, i) => (
          <div key={room.id} className="relative">
            {/* Phase 2 · each room is a live cockpit instrument:
                  · BreathingScope → staggered idle breathing (out of sync)
                  · MagneticGlass  → magnetic lift, cursor reflection, a
                    one-shot border-light sweep on hover, click ripple.
                The divider siblings below stay OUTSIDE the wrapper so the
                magnetic transform never drags the column hairlines. */}
            <BreathingScope phase={i} period={5.2} intensity={0.8}>
              <MagneticGlass
                radius={16}
                strength={4}
                accentRgb={accent.rgb}
                style={{ height: "100%" }}
              >
                <FlightDeckRoom
                  room={room}
                  isOpen={rowOpen}
                  stagger={i}
                  accent={accent}
                />
              </MagneticGlass>
            </BreathingScope>

            {/* Vertical divider — THEME-TINTED gradient hairline between
                columns. Never neutral gray; always reads as a colour
                statement that belongs to the active palette. */}
            {i < displayRooms.length - 1 && (
              <span
                aria-hidden
                className="pointer-events-none absolute top-2 bottom-2 hidden md:block"
                style={{
                  right: 0,
                  width: 1,
                  background: `linear-gradient(180deg, transparent 0%, ${vgRgba(accent.rgb, 0.18)} 35%, ${vgRgba(accent.rgb, 0.18)} 65%, transparent 100%)`,
                }}
              />
            )}
            {/* Mobile mirror — cols 1 & 3 only, theme-tinted */}
            {i % 2 === 0 && i < displayRooms.length - 1 && (
              <span
                aria-hidden
                className="pointer-events-none absolute top-2 bottom-2 md:hidden"
                style={{
                  right: 0,
                  width: 1,
                  background: `linear-gradient(180deg, transparent 0%, ${vgRgba(accent.rgb, 0.18)} 35%, ${vgRgba(accent.rgb, 0.18)} 65%, transparent 100%)`,
                }}
              />
            )}
          </div>
        ))}

        {/* Mobile mid-row horizontal divider — theme-tinted */}
        <span
          aria-hidden
          className="pointer-events-none absolute left-2 right-2 md:hidden"
          style={{
            top: "50%",
            height: 1,
            background: `linear-gradient(90deg, transparent 0%, ${vgRgba(accent.rgb, 0.18)} 35%, ${vgRgba(accent.rgb, 0.18)} 65%, transparent 100%)`,
          }}
        />
      </div>
    </motion.div>
  )
}

