/* ═════════════════════════════════════════════════════════════════════���═════
 *  useFlightDeckConfig — localStorage persistence hook
 * ═══════════════════════════════════════════════════════════════════════════
 *  Manages user's custom Flight Deck configuration with persistence.
 *  Stores: active rooms, room order, and per-room destination selections.
 * ═════════════════════════════════════════���═════════════════════════════════ */
interface FlightDeckConfigState {
  version: number
  activeRoomIds: string[]
  roomDestinations: Record<string, string[]>
}

const DEFAULT_FLIGHT_DECK_CONFIG: FlightDeckConfigState = {
  /* v3 — REAL FEATURES ONLY. Purges v1/v2 storage so every visitor
     receives the audited 16-door catalog (9 real pages, 2 real
     templates, 4 live AI doors, 1 control). An untouched (default)
     room renders straight from FLIGHT_DECK_ROOMS — the canonical
     catalog carrying `system` eyebrows + `href`/`templateId`/
     `askPrompt`/`event` wiring. Custom picks come from ALL_DESTINATIONS. */
  version: 3,
  // Default: Market Floor, The Studio, Mentor Hall, The Collective (skip Review Room)
  activeRoomIds: ["market", "studio", "mentors", "collective"],
  roomDestinations: {
    market: ["signal-room", "forecast-room", "live-charts", "news-wire"],
    studio: ["create-forecast", "publish-signal", "journal-entry", "build-setup"],
    mentors: ["compare-mentors", "mentor-library", "replay-sessions", "insights-vault"],
    review: ["todays-stats", "performance-audit", "risk-audit", "schedule-review"],
    collective: ["community-hub", "compare-ecosystems", "my-fit-analysis", "live-activity"],
  },
}

function useFlightDeckConfig() {
  const [config, setConfig] = useState<FlightDeckConfigState>(() => {
    if (typeof window === "undefined") return DEFAULT_FLIGHT_DECK_CONFIG
    try {
      const saved = localStorage.getItem("vantary-flight-deck-config")
      if (saved) {
        const parsed = JSON.parse(saved)
        if (parsed.version === 3) return parsed
      }
    } catch {}
    return DEFAULT_FLIGHT_DECK_CONFIG
  })

  // Debounced save to localStorage
  useEffect(() => {
    const timer = setTimeout(() => {
      try {
        localStorage.setItem("vantary-flight-deck-config", JSON.stringify(config))
      } catch {}
    }, 500)
    return () => clearTimeout(timer)
  }, [config])

  const toggleRoom = useCallback((roomId: string) => {
    setConfig(prev => ({
      ...prev,
      activeRoomIds: prev.activeRoomIds.includes(roomId)
        ? prev.activeRoomIds.filter(id => id !== roomId)
        : [...prev.activeRoomIds, roomId],
    }))
  }, [])

  const reorderRooms = useCallback((newOrder: string[]) => {
    setConfig(prev => ({ ...prev, activeRoomIds: newOrder }))
  }, [])

  const toggleDestination = useCallback((roomId: string, destId: string) => {
    setConfig(prev => {
      const currentDests = prev.roomDestinations[roomId] || []
      const newDests = currentDests.includes(destId)
        ? currentDests.filter(id => id !== destId)
        : [...currentDests, destId]
      return {
        ...prev,
        roomDestinations: { ...prev.roomDestinations, [roomId]: newDests },
      }
    })
  }, [])

  const addDestinationToRoom = useCallback((roomId: string, destId: string) => {
    setConfig(prev => {
      const currentDests = prev.roomDestinations[roomId] || []
      if (currentDests.includes(destId)) return prev
      return {
        ...prev,
        roomDestinations: { ...prev.roomDestinations, [roomId]: [...currentDests, destId] },
      }
    })
  }, [])

  const removeDestinationFromRoom = useCallback((roomId: string, destId: string) => {
    setConfig(prev => {
      const currentDests = prev.roomDestinations[roomId] || []
      return {
        ...prev,
        roomDestinations: { ...prev.roomDestinations, [roomId]: currentDests.filter(id => id !== destId) },
      }
    })
  }, [])

  const resetToDefault = useCallback(() => {
    setConfig(DEFAULT_FLIGHT_DECK_CONFIG)
    try {
      localStorage.removeItem("vantary-flight-deck-config")
    } catch {}
  }, [])

  return {
    config,
    toggleRoom,
    reorderRooms,
    toggleDestination,
    addDestinationToRoom,
    removeDestinationFromRoom,
    resetToDefault,
  }
}

/* ══════���══════════════════════════════════════════������══════════════════��═════
 *  <FlightDeckCustomizer/>
 * ════════════════════════════════════════��══════════��═══════════════════════
 *  Premium customization panel with:
 *  - Room selection (toggle on/off, max 4 visible)
 *  - Per-room destination management (expand room to add/remove)
 *  - Search across all destinations
 *  - Drag destinations between rooms
 *  - Reset to defaults
 * ══════════════════════��════════════════════════════════════════════════════ */
function FlightDeckCustomizer({
  config,
  toggleRoom,
  toggleDestination,
  addDestinationToRoom,
  removeDestinationFromRoom,
  resetToDefault,
  onClose,
}: {
  config: FlightDeckConfigState
  toggleRoom: (roomId: string) => void
  toggleDestination: (roomId: string, destId: string) => void
  addDestinationToRoom: (roomId: string, destId: string) => void
  removeDestinationFromRoom: (roomId: string, destId: string) => void
  resetToDefault: () => void
  onClose: () => void
}) {
  const [searchQuery, setSearchQuery] = useState("")
  const [expandedRoom, setExpandedRoom] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<"rooms" | "library">("rooms")

  // Filter destinations by search
  const filteredDestinations = useMemo(() => {
    if (!searchQuery.trim()) return ALL_DESTINATIONS
    const q = searchQuery.toLowerCase()
    return ALL_DESTINATIONS.filter(d =>
      d.label.toLowerCase().includes(q) ||
      d.descriptor?.toLowerCase().includes(q) ||
      d.category.toLowerCase().includes(q)
    )
  }, [searchQuery])

  // Group destinations by category for library view
  const destinationsByCategory = useMemo(() => {
    const grouped: Record<string, DestinationTemplate[]> = {}
    filteredDestinations.forEach(d => {
      if (!grouped[d.category]) grouped[d.category] = []
      grouped[d.category].push(d)
    })
    return grouped
  }, [filteredDestinations])

  // Get visible room count
  const visibleRoomCount = Math.min(config.activeRoomIds.length, 4)

  return (
    <motion.div
      initial={{ opacity: 0, y: -12, scale: 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: -12, scale: 0.98 }}
      transition={{ duration: 0.32, ease: EASE_V }}
      className="mb-4"
    >
      <div
        className="rounded-2xl overflow-hidden"
        style={{
          background: `linear-gradient(180deg, rgba(18,18,18,0.98) 0%, ${VANTARY.ink} 100%)`,
          border: `1px solid ${VANTARY.rule}`,
          boxShadow: `0 12px 48px rgba(0,0,0,0.5), 0 0 0 1px ${VANTARY.ruleSoft}, inset 0 1px 0 rgba(255,255,255,0.03)`,
        }}
      >
        {/* ═══ HEADER ═══════════════════════════════════════════════════════ */}
        <div
          className="flex items-center justify-between px-5 py-4"
          style={{ borderBottom: `1px solid ${VANTARY.rule}` }}
        >
          <div className="flex items-center gap-3">
            <div
              className="flex items-center justify-center rounded-xl"
              style={{
                width: 36,
                height: 36,
                background: `linear-gradient(135deg, ${VANTARY.amberWash} 0%, rgba(245,158,11,0.08) 100%)`,
                border: `1px solid ${VANTARY.amberHalo}`,
                boxShadow: `0 0 20px ${VANTARY.amberWash}`,
              }}
            >
              <Settings2 size={17} strokeWidth={1.5} color={VANTARY.amber} />
            </div>
            <div>
              <h2
                className="font-mono uppercase"
                style={{
                  fontSize: 11,
                  letterSpacing: "0.22em",
                  color: VANTARY.amber,
                  fontWeight: 600,
                  margin: 0,
                }}
              >
                CUSTOMIZE FLIGHT DECK
              </h2>
              <p
                className="font-sans"
                style={{
                  fontSize: 12,
                  color: VANTARY.ash,
                  margin: 0,
                  marginTop: 1,
                }}
              >
                Choose your quick-access rooms and destinations
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <motion.button
              type="button"
              onClick={resetToDefault}
              whileHover={{ scale: 1.02, backgroundColor: VANTARY.glass }}
              whileTap={{ scale: 0.98 }}
              className="font-mono uppercase rounded-lg"
              style={{
                fontSize: 9,
                letterSpacing: "0.12em",
                padding: "8px 14px",
                color: VANTARY.ash,
                background: "transparent",
                border: `1px solid ${VANTARY.rule}`,
              }}
            >
              RESET
            </motion.button>
            <motion.button
              type="button"
              onClick={onClose}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              className="font-mono uppercase rounded-lg"
              style={{
                fontSize: 9,
                letterSpacing: "0.12em",
                padding: "8px 16px",
                color: VANTARY.ink,
                background: VANTARY.amber,
                border: "none",
                fontWeight: 600,
              }}
            >
              DONE
            </motion.button>
          </div>
        </div>

        {/* ═══ TAB NAVIGATION ════════════��══════════════════════════════════ */}
        <div
          className="flex items-center gap-1 px-5 py-3"
          style={{ borderBottom: `1px solid ${VANTARY.ruleSoft}` }}
        >
          {(["rooms", "library"] as const).map((tab) => (
            <button
              key={tab}
              type="button"
              onClick={() => setActiveTab(tab)}
              className="font-mono uppercase rounded-lg transition-all"
              style={{
                fontSize: 9,
                letterSpacing: "0.14em",
                padding: "6px 16px",
                color: activeTab === tab ? VANTARY.amber : VANTARY.ashSoft,
                background: activeTab === tab ? VANTARY.amberWash : "transparent",
                border: `1px solid ${activeTab === tab ? VANTARY.amberHalo : "transparent"}`,
              }}
            >
              {tab === "rooms" ? "YOUR ROOMS" : "DESTINATION LIBRARY"}
            </button>
          ))}
          <span className="flex-1" />
          <div className="flex items-center gap-3">
            <span
              className="font-mono"
              style={{ fontSize: 10, color: VANTARY.ashSoft }}
            >
              <span style={{ color: VANTARY.amber }}>{visibleRoomCount}</span>/4 rooms
            </span>
            <span
              aria-hidden
              style={{ width: 1, height: 14, background: VANTARY.rule }}
            />
            <span
              className="font-mono"
              style={{ fontSize: 10, color: VANTARY.ashSoft }}
            >
              <span style={{ color: VANTARY.paper }}>
                {Object.values(config.roomDestinations).flat().length}
              </span> destinations
            </span>
          </div>
        </div>

        {/* ═══ CONTENT ════════════════════════════════���═��═══════════════════ */}
        <div className="p-5" style={{ maxHeight: 480, overflowY: "auto" }}>
          {activeTab === "rooms" ? (
            /* ─── ROOMS TAB ────────���──────────��─────��───────��───����───��─��────���─ */
            <div className="space-y-4">
              {/* Active Rooms Grid */}
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <span
                    className="font-mono uppercase"
                    style={{ fontSize: 9, letterSpacing: "0.16em", color: VANTARY.amber }}
                  >
                    YOUR QUICK-ACCESS ROOMS
                  </span>
                  <span className="flex-1" style={{ height: 1, background: VANTARY.rule }} />
                  <span
                    className="font-mono"
                    style={{ fontSize: 9, color: VANTARY.ashSoft }}
                  >
                    click room to expand
                  </span>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
                  {FLIGHT_DECK_ROOMS.map((room) => {
                    const isActive = config.activeRoomIds.includes(room.id)
                    const isExpanded = expandedRoom === room.id
                    const roomDestIds = config.roomDestinations[room.id] || []
                    const RoomIcon = room.icon
                    const isVisible = config.activeRoomIds.slice(0, 4).includes(room.id)

                    return (
                      <motion.div
                        key={room.id}
                        layout
                        className="rounded-xl overflow-hidden"
                        style={{
                          background: isActive
                            ? `linear-gradient(135deg, ${VANTARY.glass} 0%, rgba(18,18,18,0.6) 100%)`
                            : VANTARY.ink,
                          border: `1px solid ${isActive ? (isVisible ? VANTARY.amber : VANTARY.amberHalo) : VANTARY.rule}`,
                          boxShadow: isActive && isVisible ? `0 0 24px ${VANTARY.amberWash}` : "none",
                        }}
                      >
                        {/* Room Header */}
                        <div
                          className="flex items-center gap-3 p-4 cursor-pointer"
                          onClick={() => setExpandedRoom(isExpanded ? null : room.id)}
                          style={{ borderBottom: isExpanded ? `1px solid ${VANTARY.ruleSoft}` : "none" }}
                        >
                          <motion.div
                            className="flex items-center justify-center rounded-xl shrink-0"
                            style={{
                              width: 38,
                              height: 38,
                              background: isActive
                                ? `linear-gradient(135deg, ${VANTARY.amberWash} 0%, rgba(245,158,11,0.05) 100%)`
                                : VANTARY.glass,
                              border: `1px solid ${isActive ? VANTARY.amber : VANTARY.rule}`,
                            }}
                          >
                            <RoomIcon
                              size={17}
                              strokeWidth={1.5}
                              color={isActive ? VANTARY.amber : VANTARY.ash}
                            />
                          </motion.div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <h4
                                className="font-mono uppercase truncate"
                                style={{
                                  fontSize: 10,
                                  letterSpacing: "0.16em",
                                  color: isActive ? VANTARY.amber : VANTARY.ashSoft,
                                  fontWeight: 500,
                                  margin: 0,
                                }}
                              >
                                {room.name}
                              </h4>
                              {isVisible && (
                                <span
                                  className="font-mono uppercase shrink-0"
                                  style={{
                                    fontSize: 7,
                                    letterSpacing: "0.1em",
                                    color: VANTARY.ink,
                                    background: VANTARY.amber,
                                    padding: "2px 5px",
                                    borderRadius: 3,
                                  }}
                                >
                                  VISIBLE
                                </span>
                              )}
                            </div>
                            <p
                              className="font-sans truncate"
                              style={{
                                fontSize: 11,
                                color: VANTARY.ash,
                                margin: 0,
                                marginTop: 2,
                              }}
                            >
                              {roomDestIds.length} destinations configured
                            </p>
                          </div>
                          <div className="flex items-center gap-2">
                            <motion.button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation()
                                toggleRoom(room.id)
                              }}
                              whileHover={{ scale: 1.1 }}
                              whileTap={{ scale: 0.9 }}
                              className="flex items-center justify-center rounded-lg shrink-0"
                              style={{
                                width: 28,
                                height: 28,
                                background: isActive ? VANTARY.amber : "transparent",
                                border: `1px solid ${isActive ? VANTARY.amber : VANTARY.rule}`,
                              }}
                            >
                              {isActive ? (
                                <Check size={13} strokeWidth={2.5} color={VANTARY.ink} />
                              ) : (
                                <Plus size={13} strokeWidth={1.5} color={VANTARY.ash} />
                              )}
                            </motion.button>
                            <motion.span
                              animate={{ rotate: isExpanded ? 180 : 0 }}
                              transition={{ duration: 0.25, ease: EASE_V }}
                            >
                              <ChevronDown size={16} strokeWidth={1.5} color={VANTARY.ash} />
                            </motion.span>
                          </div>
                        </div>

                        {/* Expanded Destinations */}
                        <AnimatePresence>
                          {isExpanded && (
                            <motion.div
                              initial={{ height: 0, opacity: 0 }}
                              animate={{ height: "auto", opacity: 1 }}
                              exit={{ height: 0, opacity: 0 }}
                              transition={{ duration: 0.28, ease: EASE_V }}
                              className="overflow-hidden"
                            >
                              <div className="p-4 pt-3 space-y-2">
                                <span
                                  className="font-mono uppercase block mb-2"
                                  style={{ fontSize: 8, letterSpacing: "0.14em", color: VANTARY.ashSoft }}
                                >
                                  DESTINATIONS IN THIS ROOM
                                </span>
                                <div className="flex flex-col gap-1.5">
                                  {ALL_DESTINATIONS.filter(d => d.defaultRoom === room.id).map((dest) => {
                                    const isEnabled = roomDestIds.includes(dest.id)
                                    const DestIcon = dest.icon
                                    return (
                                      <motion.button
                                        key={dest.id}
                                        type="button"
                                        onClick={() => toggleDestination(room.id, dest.id)}
                                        whileHover={{ backgroundColor: VANTARY.glass }}
                                        className="flex items-center gap-2.5 rounded-lg text-left w-full group"
                                        style={{
                                          padding: "10px 12px",
                                          background: isEnabled ? VANTARY.amberWash : "transparent",
                                          border: `1px solid ${isEnabled ? VANTARY.amberHalo : VANTARY.ruleSoft}`,
                                        }}
                                      >
                                        <div
                                          className="flex items-center justify-center rounded-lg shrink-0"
                                          style={{
                                            width: 28,
                                            height: 28,
                                            background: isEnabled ? VANTARY.amber : VANTARY.glass,
                                            border: `1px solid ${isEnabled ? VANTARY.amber : VANTARY.rule}`,
                                          }}
                                        >
                                          <DestIcon
                                            size={13}
                                            strokeWidth={1.5}
                                            color={isEnabled ? VANTARY.ink : VANTARY.ash}
                                          />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                          <span
                                            className="font-sans block truncate"
                                            style={{
                                              fontSize: 12,
                                              color: isEnabled ? VANTARY.paper : VANTARY.ash,
                                              fontWeight: 500,
                                            }}
                                          >
                                            {dest.label}
                                          </span>
                                          <span
                                            className="font-sans block truncate"
                                            style={{
                                              fontSize: 10,
                                              color: VANTARY.ashSoft,
                                            }}
                                          >
                                            {dest.descriptor}
                                          </span>
                                        </div>
                                        {dest.hint && (
                                          <span
                                            className="font-mono shrink-0"
                                            style={{
                                              fontSize: 9,
                                              color: isEnabled ? VANTARY.amber : VANTARY.ashSoft,
                                              padding: "2px 6px",
                                              background: isEnabled ? VANTARY.ink : VANTARY.glass,
                                              borderRadius: 4,
                                              border: `1px solid ${isEnabled ? VANTARY.amberHalo : VANTARY.rule}`,
                                            }}
                                          >
                                            {dest.hint}
                                          </span>
                                        )}
                                        <span className="shrink-0">
                                          {isEnabled ? (
                                            <Check size={12} strokeWidth={2} color={VANTARY.amber} />
                                          ) : (
                                            <Plus size={12} strokeWidth={1.5} color={VANTARY.ash} />
                                          )}
                                        </span>
                                      </motion.button>
                                    )
                                  })}
                                </div>
                              </div>
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </motion.div>
                    )
                  })}
                </div>
              </div>
            </div>
          ) : (
            /* ─── DESTINATION LIBRARY TAB ────────────────��──────────────────── */
            <div className="space-y-5">
              {/* Search Bar */}
              <div
                className="flex items-center gap-3 rounded-xl"
                style={{
                  padding: "12px 16px",
                  background: VANTARY.glass,
                  border: `1px solid ${VANTARY.rule}`,
                }}
              >
                <Search size={16} strokeWidth={1.5} color={VANTARY.ash} />
                <input
                  type="text"
                  placeholder="Search all destinations..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="flex-1 bg-transparent outline-none font-sans"
                  style={{ fontSize: 13, color: VANTARY.paper }}
                />
                {searchQuery && (
                  <button
                    type="button"
                    onClick={() => setSearchQuery("")}
                    className="p-1.5 rounded-lg"
                    style={{ background: VANTARY.rule }}
                  >
                    <X size={12} strokeWidth={2} color={VANTARY.ash} />
                  </button>
                )}
              </div>

              {/* Destinations by Category */}
              {Object.entries(destinationsByCategory).map(([category, dests]) => (
                <div key={category}>
                  <div className="flex items-center gap-2 mb-3">
                    <span
                      className="font-mono uppercase"
                      style={{ fontSize: 9, letterSpacing: "0.16em", color: VANTARY.amber }}
                    >
                      {category}
                    </span>
                    <span className="flex-1" style={{ height: 1, background: VANTARY.rule }} />
                    <span
                      className="font-mono"
                      style={{ fontSize: 9, color: VANTARY.ashSoft }}
                    >
                      {dests.length} destinations
                    </span>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-2">
                    {dests.map((dest) => {
                      const DestIcon = dest.icon
                      // Check which rooms have this destination
                      const inRooms = Object.entries(config.roomDestinations)
                        .filter(([, destIds]) => destIds.includes(dest.id))
                        .map(([roomId]) => roomId)
                      const primaryRoom = inRooms[0]
                      const roomData = primaryRoom
                        ? FLIGHT_DECK_ROOMS.find(r => r.id === primaryRoom)
                        : null

                      return (
                        <motion.div
                          key={dest.id}
                          whileHover={{ scale: 1.02, y: -2 }}
                          className="rounded-xl p-3"
                          style={{
                            background: inRooms.length > 0 ? VANTARY.glass : VANTARY.ink,
                            border: `1px solid ${inRooms.length > 0 ? VANTARY.amberHalo : VANTARY.rule}`,
                          }}
                        >
                          <div className="flex items-start gap-2.5 mb-2">
                            <div
                              className="flex items-center justify-center rounded-lg shrink-0"
                              style={{
                                width: 30,
                                height: 30,
                                background: inRooms.length > 0 ? VANTARY.amberWash : VANTARY.glass,
                                border: `1px solid ${inRooms.length > 0 ? VANTARY.amber : VANTARY.rule}`,
                              }}
                            >
                              <DestIcon
                                size={14}
                                strokeWidth={1.5}
                                color={inRooms.length > 0 ? VANTARY.amber : VANTARY.ash}
                              />
                            </div>
                            <div className="flex-1 min-w-0">
                              <h4
                                className="font-sans truncate"
                                style={{
                                  fontSize: 12,
                                  color: inRooms.length > 0 ? VANTARY.paper : VANTARY.ash,
                                  fontWeight: 500,
                                  margin: 0,
                                }}
                              >
                                {dest.label}
                              </h4>
                              <p
                                className="font-sans truncate"
                                style={{
                                  fontSize: 10,
                                  color: VANTARY.ashSoft,
                                  margin: 0,
                                }}
                              >
                                {dest.descriptor}
                              </p>
                            </div>
                          </div>
                          {inRooms.length > 0 && roomData && (
                            <div
                              className="flex items-center gap-1.5 rounded-md mt-2"
                              style={{
                                padding: "4px 8px",
                                background: VANTARY.amberWash,
                                width: "fit-content",
                              }}
                            >
                              <Check size={9} strokeWidth={2.5} color={VANTARY.amber} />
                              <span
                                className="font-mono uppercase"
                                style={{
                                  fontSize: 8,
                                  letterSpacing: "0.1em",
                                  color: VANTARY.amber,
                                }}
                              >
                                IN {roomData.name}
                              </span>
                            </div>
                          )}
                        </motion.div>
                      )
                    })}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </motion.div>
  )
}

/* ════��══════════════════════════════════════════════════════════════════════
 *  <FlightDeckCockpitWithCustomizer/>
 * ═══════════���═══════════════════════════════════════════════════════════════
 *  Premium wrapper with customize button and full customization panel.
 *  Builds rooms dynamically from user configuration.
 * ═══════════════════════════════════════════════════════════════════════════ */
function FlightDeckCockpitWithCustomizer() {
  const [showCustomizer, setShowCustomizer] = useState(false)
  const {
    config,
    toggleRoom,
    toggleDestination,
    addDestinationToRoom,
    removeDestinationFromRoom,
    resetToDefault,
  } = useFlightDeckConfig()

  // Build rooms from config with custom destinations
  const visibleRooms = useMemo(() => {
    const activeRoomIds = config.activeRoomIds.slice(0, 4)
    return activeRoomIds
      .map(roomId => {
        const baseRoom = FLIGHT_DECK_ROOMS.find(r => r.id === roomId)
        if (!baseRoom) return null

        /* ── ROOM-NAVIGATOR RESOLUTION (masterplan P5) ─────────────────
           A room whose saved destination list still equals the shipped
           default is UNTOUCHED — it renders the full canonical catalog
           from FLIGHT_DECK_ROOMS (6 doors, 3 italic system-eyebrow
           groups, template/ask/event wiring). Only a room the user has
           actively customized swaps to their hand-picked list from
           ALL_DESTINATIONS — spread whole (`...d`) so every wiring
           field a library entry carries survives; template resolution
           for legacy labels still works via the label-lookup fallback
           inside enrichedRooms. No slice cap: the drawer is the
           platform's PERMANENT navigation, every door must be present. */
        const destIds = config.roomDestinations[roomId] || []
        const defaultIds = DEFAULT_FLIGHT_DECK_CONFIG.roomDestinations[roomId] || []
        const isCustomized =
          destIds.length > 0 && JSON.stringify(destIds) !== JSON.stringify(defaultIds)

        const customDestinations = isCustomized
          ? (destIds
              .map(destId => ALL_DESTINATIONS.find(d => d.id === destId))
              .filter(Boolean)
              .map(d => ({ ...d! })) as FlightDeckDestinationDef[])
          : []

        return {
          ...baseRoom,
          destinations: customDestinations.length > 0 ? customDestinations : baseRoom.destinations,
        }
      })
      .filter(Boolean) as FlightDeckRoomDef[]
  }, [config])

  // Keyboard shortcut for customizer
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault()
        setShowCustomizer(prev => !prev)
      }
    }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [])

  return (
    /* OUTER WRAPPER — DUAL ANCHOR:
         · `mb-1` keeps the TradingView chart navigator below us
           sitting tight against the 4-room band (4px gap before
           the chart toolbar begins — each room already has its own
           internal 14px padding).
         · `marginTop: -16` LIFTS the entire cockpit upward by 16px
           per direct trader directive ("MORE CLOSED to the flight
           deck"). The cartouche above us has `mb-0`, AskQuickActions
           outer margins are now 0, so the only remaining dead band
           between the ASK / cycler-pill row and the rooms is the
           visual overrun from the flame column (which intentionally
           hangs ~44px down into the rooms' top zone). A -16px lift
           on the cockpit collapses that overrun INTO the rooms'
           top hairline — the flame now reads as actively burning
           THROUGH the navigator's top edge, not floating in a gap
           above it. -16px is enough to seal the gap without
           clipping the flame's combustion tips, since the cockpit's
           top hairline is a soft horizontal gradient (not a hard
           border) and tolerates the flame layer rendering above
           the seam via `mix-blend-mode: screen`. */
    /* `position: relative` + `overflow: visible` (new): the
       `<FlightDeckRoomIgnitionOverlay/>` rendered below as a SIBLING
       of `<FlightDeckCockpit/>` is absolutely positioned at the top
       of THIS wrapper (which coincides with the top of the cockpit,
       i.e. the top hairline of the 4 rooms). Its flame elements
       extend UPWARD via negative top offsets into the cartouche
       zone above — feeding the EXECUTION and DEVELOPMENT pills'
       underside reception glows. The cockpit itself still has its
       own `overflow: hidden` (for its rounded-corner mask), so we
       can NOT render the flames inside the cockpit if we want them
       to extend up out of it — this wrapper is the correct
       containment level. `overflow: visible` is the default on
       div but stated explicitly here as documentation. */
    /* SPACING RETUNE (rooms-first stack): the cockpit is now TIER 2 —
       the FIRST visible tier (eyebrow rail hidden). The old
       `marginTop: 28` (tuned for sitting BELOW the cartouche) created
       a dead band at the very top of the deck, so it drops to 0. The
       old `mb-1` (4px, tuned for the chart toolbar directly beneath)
       becomes a deliberate small 14px breath down to the cartouche
       gadget wings per trader directive ("small lil space from the
       flight deck to the 4 rooms wheres gadgets"). */
    <div style={{ marginTop: 0, marginBottom: 14, position: "relative", overflow: "visible" }}>
      {/* ── CUSTOMIZE FLIGHT DECK · temporarily hidden ───────────────────
            The full-width customize rail and its companion customizer
            panel are intentionally suppressed for this iteration. The
            state (`showCustomizer`) and all wiring (`toggleRoom`,
            `toggleDestination`, `addDestinationToRoom`, `removeDestinationFromRoom`,
            `resetToDefault`, `FlightDeckCustomizeRail`, `FlightDeckCustomizer`)
            are preserved so we can re-enable in one line later by
            restoring the block below. Leaving the imports/components in
            place is deliberate — pulling them would break the redesign
            we're about to fold back in. */}
      {/*
      <FlightDeckCustomizeRail
        open={showCustomizer}
        onToggle={() => setShowCustomizer((v) => !v)}
      />
      <AnimatePresence>
        {showCustomizer && (
          <FlightDeckCustomizer
            config={config}
            toggleRoom={toggleRoom}
            toggleDestination={toggleDestination}
            addDestinationToRoom={addDestinationToRoom}
            removeDestinationFromRoom={removeDestinationFromRoom}
            resetToDefault={resetToDefault}
            onClose={() => setShowCustomizer(false)}
          />
        )}
      </AnimatePresence>
      */}

      {/* ── ROOM IGNITION OVERLAY · the NEW fire-breathing system ──────
            Per direct trader directive: "remove horizontal burning
            on execution and development tab! can you please make
            the fire to come from the top hbar of the marketfloor
            and studio. like border to burn realistically and have
            some breathing energetic connection."

            This overlay renders 4 vertical flame pillars (one per
            room), each anchored at the cockpit's top hairline and
            extending UPWARD into the cartouche zone above. Pillars
            0-1 lean slightly RIGHTWARD (toward the EXECUTION pill
            center above the left pair-card); pillars 2-3 lean
            LEFTWARD (toward the DEVELOPMENT pill center). The
            convergence creates the visual "these 2 rooms feed
            this 1 pill" metaphor without explicit lines/arrows.

            The overlay is a SIBLING of the cockpit (not a child),
            so the cockpit's own `overflow: hidden` does not clip
            the flames extending upward. */}
      <FlightDeckRoomIgnitionOverlay rooms={visibleRooms} />

      {/* The actual cockpit */}
      <FlightDeckCockpit rooms={visibleRooms} />
    </div>
  )
}

/* ─────────────────────────────────────��───────────────────────────────────
 *  <FlightDeckRoomIgnitionOverlay/>
 *
 *  A 4-column flame overlay that visually anchors the EXECUTION and
 *  DEVELOPMENT pills (above, in the cartouche) to their two source
 *  rooms (below, in the cockpit). Each room's TOP HAIRLINE appears
 *  to burn, and flames RISE upward from it, licking the pill's
 *  underside reception glow above.
 *
 *  LAYER COMPOSITION (back → front, all `mix-blend-mode: screen`
 *  so overlapping layers BLOOM brighter rather than stacking
 *  opaquely — reads as light, not paint):
 *
 *    1. IGNITING TOP BAND · a horizontal accent gradient sitting
 *       AT y=0 (the top hairline of the room). Travels left → center
 *       → right on a slow loop — the seam appears HOT, like an
 *       ignited fuse line. Subtle, never barber-pole.
 *
 *    2. HEAT HAZE FIELD · a wide soft accent radial above the
 *       igniting band, fading upward ~60px into the cartouche zone.
 *       Slow 3-4s breathing — the atmosphere "heating up."
 *
 *    3. FLAME TONGUES · three teardrop tongues per room, each with
 *       its own width / height / blur / flicker period / delay.
 *       Tongues are anchored at y=0 (the room's top hairline) and
 *       rise UPWARD into the cartouche zone. They `transform` with
 *       a slight rotate(±2-4deg) so rooms 0-1 lean RIGHT and rooms
 *       2-3 lean LEFT — the four flames converge in two Vs, one
 *       under each pill.
 *
 *    4. EMBER SPARKS · 2 tiny accent sparks per room rising past
 *       the cartouche bottom into the pill area, fading as they
 *       climb. Sparse — adds "alive, combusting" texture without
 *       crowding.
 *
 *  RHYTHM: every pillar has its OWN delay (0.0s / 0.4s / 0.7s /
 *  1.0s) and period (2.6s / 3.1s / 2.4s / 3.5s) so the four flames
 *  NEVER pulse in unison. The eye reads organic combustion, not
 *  metronomic UI animation.
 *
 *  ACCESSIBILITY: respects `useReducedMotion()` — when motion is
 *  reduced, the overlay renders only the static igniting top band
 *  + heat haze at fixed opacity; no rising flames or embers.
 * ──────────────���─────────────────────���──────���─────���─────────────────── */
function FlightDeckRoomIgnitionOverlay({
  rooms,
}: {
  rooms: FlightDeckRoomDef[]
}) {
  const reduced = useReducedMotion()
  const accent = useThemeAccent().primary
  /* Stable id so all keyframes for this overlay instance are scoped
     and don't collide with other ignition overlays elsewhere. */
  const kfId = React.useId().replace(/[:]/g, "")

  /* Per-room variation table — every parameter is deterministic
     from the room index so the four pillars never pulse in
     lockstep but always render the same on re-mount. Tilt
     direction encodes which pill the pillar "feeds":
       index 0 (MARKET FLOOR)   →  +3.5deg  (lean right → EXECUTION)
       index 1 (STUDIO)         →  +1.5deg  (lean right → EXECUTION)
       index 2 (MENTOR HALL)    →  -1.5deg  (lean left  → DEVELOPMENT)
       index 3 (COLLECTIVE)     →  -3.5deg  (lean left  → DEVELOPMENT)
     Periods + delays are all coprime-ish so no two columns ever
     peak together. */
  const PILLAR_VARIANTS: ReadonlyArray<{
    tilt: number
    bandDelay: number
    bandDur: number
    hazeDelay: number
    hazeDur: number
    tongues: ReadonlyArray<{ x: number; h: number; w: number; b: number; dur: number; delay: number }>
    embers: ReadonlyArray<{ x: number; dur: number; delay: number }>
  }> = [
    {
      tilt: 3.5,
      bandDelay: 0.0,
      bandDur: 3.4,
      hazeDelay: 0.0,
      hazeDur: 2.6,
      tongues: [
        { x: 32, h: 26, w: 10, b: 2.0, dur: 0.88, delay: 0.00 },
        { x: 50, h: 40, w: 12, b: 1.2, dur: 0.66, delay: 0.16 },
        { x: 68, h: 28, w: 10, b: 2.0, dur: 0.94, delay: 0.30 },
      ],
      embers: [
        { x: 44, dur: 2.9, delay: 0.0 },
        { x: 58, dur: 3.2, delay: 1.1 },
      ],
    },
    {
      tilt: 1.5,
      bandDelay: 0.4,
      bandDur: 3.8,
      hazeDelay: 0.4,
      hazeDur: 3.1,
      tongues: [
        { x: 30, h: 30, w: 10, b: 2.0, dur: 0.96, delay: 0.10 },
        { x: 50, h: 44, w: 12, b: 1.2, dur: 0.72, delay: 0.24 },
        { x: 70, h: 24, w: 9,  b: 2.2, dur: 0.86, delay: 0.05 },
      ],
      embers: [
        { x: 46, dur: 3.1, delay: 0.4 },
        { x: 56, dur: 2.8, delay: 1.6 },
      ],
    },
    {
      tilt: -1.5,
      bandDelay: 0.7,
      bandDur: 3.2,
      hazeDelay: 0.7,
      hazeDur: 2.4,
      tongues: [
        { x: 30, h: 26, w: 9,  b: 2.2, dur: 0.90, delay: 0.22 },
        { x: 50, h: 42, w: 12, b: 1.2, dur: 0.68, delay: 0.08 },
        { x: 70, h: 30, w: 10, b: 2.0, dur: 0.92, delay: 0.34 },
      ],
      embers: [
        { x: 42, dur: 3.0, delay: 0.9 },
        { x: 60, dur: 3.3, delay: 2.0 },
      ],
    },
    {
      tilt: -3.5,
      bandDelay: 1.0,
      bandDur: 4.0,
      hazeDelay: 1.0,
      hazeDur: 3.5,
      tongues: [
        { x: 32, h: 28, w: 10, b: 2.0, dur: 0.84, delay: 0.04 },
        { x: 50, h: 38, w: 12, b: 1.2, dur: 0.70, delay: 0.20 },
        { x: 68, h: 26, w: 9,  b: 2.2, dur: 0.98, delay: 0.32 },
      ],
      embers: [
        { x: 44, dur: 3.2, delay: 0.0 },
        { x: 58, dur: 2.9, delay: 1.3 },
      ],
    },
  ]

  return (
    <div
      aria-hidden
      className="pointer-events-none absolute inset-x-0 grid grid-cols-2 md:grid-cols-4"
      style={{
        /* Anchor at the top hairline of the cockpit (which begins
           at top: 0 of this wrapper). Height: 0 — the visual flame
           elements all use absolute positioning with negative top
           values to extend upward INTO the cartouche zone above
           this wrapper. We don't need this container to have any
           height of its own. */
        top: 0,
        height: 0,
        zIndex: 2,
      }}
    >
      {rooms.slice(0, 4).map((room, i) => {
        const v = PILLAR_VARIANTS[i] ?? PILLAR_VARIANTS[0]
        const isLeftPair = i < 2
        return (
          <div key={`ignition-${room.id}`} className="relative">
            {/* ════════════════════════════════════════════════════════════
                  CONTROLLED IGNITION GLOW  ·  v4 "Reactor Seam"
                ════════════════════════════════════════════════════════════
                  Per approved direction: retire the literal fire vocabulary
                  (flame tongues / barber-pole band / heat column) and replace
                  it with an INSTITUTIONAL ignition glow — the room's top
                  hairline reads as a softly powered reactor seam, breathing
                  with the deck rather than burning. Three calm layers, all
                  `mix-blend-mode: screen` so overlap BLOOMS as light:

                    1. IGNITION SEAM  · a soft horizontal accent gradient at
                       y=0 (the room's top edge). It breathes in intensity +
                       gently expands/contracts on its own irrational period
                       so the seam feels "energised", never a hard UI line.
                    2. CORE BLOOM     · a low radial bloom rising ~46px above
                       the seam, the controlled heat halo. Breathes out of
                       phase with the seam.
                    3. EMBERS         · the rising light particles the trader
                       liked — kept, but slowed + softened so they read as
                       lazy reactor sparks, not crypto confetti.

                  Reduced-motion: the seam + bloom render at a FIXED calm
                  opacity (still themed, still alive-looking) and the embers
                  are suppressed. */}

            {/* 1 · IGNITION SEAM — the powered top hairline */}
            <span
              aria-hidden
              style={{
                position: "absolute",
                left: "12%",
                right: "12%",
                top: 0,
                height: 2,
                borderRadius: 999,
                background: `linear-gradient(90deg, transparent 0%, ${vgRgba(accent.rgb, 0.55)} 50%, transparent 100%)`,
                filter: "blur(0.6px)",
                mixBlendMode: "screen",
                transformOrigin: "center",
                ...(reduced
                  ? { opacity: 0.5 }
                  : { animation: `fdr-seam-${kfId} ${v.bandDur}s ${v.bandDelay}s ease-in-out infinite` }),
              }}
            />

            {/* 2 · CORE BLOOM — the controlled heat halo rising off the seam */}
            <span
              aria-hidden
              style={{
                position: "absolute",
                left: "50%",
                top: 0,
                width: 120,
                height: 56,
                marginLeft: -60,
                transform: "translateY(-46px)",
                background: `radial-gradient(60% 100% at 50% 100%, ${vgRgba(accent.rgb, 0.22)} 0%, ${vgRgba(accent.rgb, 0.07)} 45%, transparent 75%)`,
                mixBlendMode: "screen",
                transformOrigin: "50% 100%",
                ...(reduced
                  ? { opacity: 0.45 }
                  : { animation: `fdr-bloom-${kfId} ${v.hazeDur}s ${v.hazeDelay}s ease-in-out infinite` }),
              }}
            />

            {/* 3 · EMBERS — lazy reactor sparks rising into the cartouche */}
            {!reduced && v.embers.map((e, ei) => (
              <span
                key={`ember-${i}-${ei}`}
                style={{
                  position: "absolute",
                  left: `${e.x}%`,
                  top: 0,
                  width: 3,
                  height: 3,
                  borderRadius: 999,
                  background: vgRgba(accent.rgb, 0.8),
                  boxShadow: `0 0 6px ${vgRgba(accent.rgb, 0.6)}`,
                  mixBlendMode: "screen",
                  animation: `fdr-ember-${kfId} ${e.dur + 0.8}s ${e.delay}s ease-in infinite`,
                }}
              />
            ))}

            {/* Documents which execution/development pill this column feeds. */}
            <span data-feeds={isLeftPair ? "execution" : "development"} hidden />
          </div>
        )
      })}

      <style>{`
        @keyframes fdr-seam-${kfId} {
          /* The powered seam breathes: it brightens and gently widens,
             then settles. Never a hard barber-pole sweep. */
          0%,  100% { opacity: 0.32; transform: scaleX(0.82); }
          50%        { opacity: 0.9;  transform: scaleX(1);    }
        }
        @keyframes fdr-bloom-${kfId} {
          /* The heat halo rises and falls in intensity, out of phase
             with the seam so the column never strobes in unison. */
          0%,  100% { opacity: 0.3; transform: translateY(-46px) scaleY(0.85); }
          50%        { opacity: 0.85; transform: translateY(-52px) scaleY(1);   }
        }
        @keyframes fdr-ember-${kfId} {
          /* Embers rise from the seam (top: 0) UPWARD by 84px into the
             cartouche zone, fading as they climb. */
          0%   { transform: translateY(0)    scale(1);    opacity: 0; }
          14%  {                                           opacity: 0.9; }
          80%  {                                           opacity: 0.4; }
          100% { transform: translateY(-84px) scale(0.35); opacity: 0; }
        }
      `}</style>
    </div>
  )
}

/* ────────────────────────────────────────�����───────────────���───────���───────
 *  <FlightDeckCustomizeRail/>
 *
 *  Full-width Customize control surface sitting directly above the
 *  cockpit. Span = 100% of the deck so it visually frames the four-room
 *  grid below. Behaves as a single button (the whole bar is clickable),
 *  with three slots inside:
 *
 *    ┌─ ⚙ ── SETTINGS LABEL ───────  CUSTOMIZE FLIGHT DECK  ────���───  ⌘K ─┐
 *
 *  · Left:   theme-tinted gear icon + mono "CONFIGURE" label
 *  · Center: protagonist "CUSTOMIZE FLIGHT DECK" headline
 *  · Right:  ⌘K kbd hint chip + state caret
 *
 *  Open state lights the entire surface with an accent border, an inner
 *  highlight, a corner glow, and a faint diagonal sheen. Closed state is
 *  a quiet glass plate, still theme-tinted at the hairline so the surface
 *  never reads as neutral gray on Cyber / Solar / Light themes.
 * ───��──��───────────────────────────��────────────────────────────────── */
function FlightDeckCustomizeRail({
  open,
  onToggle,
}: {
  open: boolean
  onToggle: () => void
}) {
  const accent = useThemeAccent().primary
  return (
    <motion.button
      type="button"
      onClick={onToggle}
      aria-expanded={open}
      aria-label={open ? "Close Flight Deck customizer" : "Open Flight Deck customizer"}
      whileTap={{ scale: 0.995 }}
      className="relative w-full mb-3 overflow-hidden text-left group"
      style={{
        borderRadius: 14,
        padding: "10px 16px",
        background: open
          ? `linear-gradient(180deg, ${vgRgba(accent.rgb, 0.10)} 0%, ${vgRgba(accent.rgb, 0.03)} 100%)`
          : `linear-gradient(180deg, ${vgRgba(accent.rgb, 0.04)} 0%, rgba(255,255,255,0.012) 100%)`,
        border: `1px solid ${open ? vgRgba(accent.rgb, 0.38) : vgRgba(accent.rgb, 0.14)}`,
        backdropFilter: "blur(20px) saturate(140%)",
        WebkitBackdropFilter: "blur(20px) saturate(140%)",
        boxShadow: open
          ? `inset 0 1px 0 rgba(255,255,255,0.07), 0 0 24px ${vgRgba(accent.rgb, 0.14)}`
          : "inset 0 1px 0 rgba(255,255,255,0.04)",
        transition: "background 220ms ease, border-color 220ms ease, box-shadow 220ms ease",
      }}
    >
      {/* Inner top highlight — the wet-glass gleam */}
      <span
        aria-hidden
        className="pointer-events-none absolute inset-x-3 top-0 h-px"
        style={{
          background: `linear-gradient(90deg, transparent 0%, ${vgRgba(accent.rgb, open ? 0.35 : 0.18)} 50%, transparent 100%)`,
        }}
      />

      {/* Left corner glow — intensifies on hover/open */}
      <span
        aria-hidden
        className="pointer-events-none absolute"
        style={{
          top: 0,
          left: 0,
          width: 160,
          height: 60,
          background: `radial-gradient(ellipse at top left, ${vgRgba(accent.rgb, open ? 0.18 : 0.08)}, transparent 70%)`,
          opacity: open ? 1 : 0.7,
          transition: "opacity 220ms ease",
        }}
      />
      {/* Right corner glow — mirrored */}
      <span
        aria-hidden
        className="pointer-events-none absolute"
        style={{
          top: 0,
          right: 0,
          width: 160,
          height: 60,
          background: `radial-gradient(ellipse at top right, ${vgRgba(accent.rgb, open ? 0.18 : 0.08)}, transparent 70%)`,
          opacity: open ? 1 : 0.7,
          transition: "opacity 220ms ease",
        }}
      />

      {/* 3-column layout: left meta · center headline · right kbd hint */}
      <div
        className="relative grid items-center"
        style={{ gridTemplateColumns: "1fr auto 1fr", gap: 16 }}
      >
        {/* LEFT — gear + label */}
        <div className="flex items-center gap-2 min-w-0">
          <motion.span
            aria-hidden
            animate={{ rotate: open ? 90 : 0 }}
            transition={{ duration: 0.32, ease: EASE_V }}
            style={{ display: "inline-flex" }}
          >
            <Settings2
              size={13}
              strokeWidth={1.5}
              color={open ? accent.hex : vgRgba(accent.rgb, 0.7)}
            />
          </motion.span>
          <span
            className="font-mono uppercase whitespace-nowrap"
            style={{
              fontSize: 9.5,
              letterSpacing: "0.24em",
              color: vgRgba(accent.rgb, 0.75),
              fontWeight: 500,
            }}
          >
            CONFIGURE
          </span>
          {/* Trailing dot · hairline that fades into the center */}
          <span
            aria-hidden
            className="rounded-full"
            style={{
              width: 3,
              height: 3,
              background: vgRgba(accent.rgb, 0.5),
            }}
          />
          <span
            aria-hidden
            className="flex-1 min-w-0"
            style={{
              height: 1,
              background: `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.22)} 0%, ${vgRgba(accent.rgb, 0.04)} 100%)`,
            }}
          />
        </div>

        {/* CENTER — headline */}
        <span
          className="font-mono uppercase whitespace-nowrap"
          style={{
            fontSize: 10.5,
            letterSpacing: "0.36em",
            color: accent.hex,
            fontWeight: 500,
            textShadow: `0 0 12px ${vgRgba(accent.rgb, open ? 0.4 : 0.25)}`,
            transition: "text-shadow 220ms ease",
          }}
        >
          CUSTOMIZE FLIGHT DECK
        </span>

        {/* RIGHT — hairline + kbd hint chip + caret */}
        <div className="flex items-center gap-2 min-w-0 justify-end">
          <span
            aria-hidden
            className="flex-1 min-w-0"
            style={{
              height: 1,
              background: `linear-gradient(90deg, ${vgRgba(accent.rgb, 0.04)} 0%, ${vgRgba(accent.rgb, 0.22)} 100%)`,
            }}
          />
          <span
            aria-hidden
            className="rounded-full"
            style={{
              width: 3,
              height: 3,
              background: vgRgba(accent.rgb, 0.5),
            }}
          />
          <span
            className="font-mono uppercase whitespace-nowrap"
            style={{
              fontSize: 9.5,
              letterSpacing: "0.24em",
              color: vgRgba(accent.rgb, 0.75),
              fontWeight: 500,
            }}
          >
            PRESS
          </span>
          <span
            className="inline-flex items-center justify-center font-mono"
            style={{
              minWidth: 26,
              padding: "2px 7px",
              borderRadius: 4,
              background: vgRgba(accent.rgb, 0.07),
              border: `1px solid ${vgRgba(accent.rgb, 0.28)}`,
              boxShadow: "inset 0 1px 0 rgba(255,255,255,0.05)",
              color: accent.hex,
              letterSpacing: "0.18em",
              fontSize: 9.5,
              fontWeight: 500,
            }}
          >
            {"\u2318"}K
          </span>
          <motion.span
            aria-hidden
            animate={{ rotate: open ? 90 : 0 }}
            transition={{ duration: 0.32, ease: EASE_V }}
            style={{ display: "inline-flex", marginLeft: 2 }}
          >
            <ArrowRight
              size={11}
              strokeWidth={1.5}
              color={open ? accent.hex : vgRgba(accent.rgb, 0.6)}
            />
          </motion.span>
        </div>
      </div>
    </motion.button>
  )
}

/* ───────────────────────────────────────────────────────────���─────────────
 *  <MarketFloorEyebrowRail/>
 *
 *  The signature centered section eyebrow shown at the very top of the
 *  Flight Deck. Anatomy (left → right):
 *
 *    ⊙ ─────────── ● MARKET FLOOR · WHAT'S HAPPENING NOW ─────────── ⊙
 *
 *   • Two outer ring anchors (small 6px circles, ash-bordered).
 *   • A gradient hairline on EACH SIDE that fades from rule-soft into
 *     theme accent at its inner end, so the hairlines feel like they're
 *     "feeding" the headline with energy.
 *   • A pulsing center pip in the active theme accent.
 *   • The headline in mono-caps, wide letter-spacing, theme-tinted.
 *   • A trailing micro-tail pip mirroring the lead pip for symmetry.
 *
 *  Theme-aware via `useThemeAccent()` — works for Teal, Cyber, Neural,
 *  Quantum, Solar, Light, Obsidian, and any future palette.
 * ────────────────────────────��───────────────────────���──────────────── */
/* ─────────────────────────────────────────────────────────────────────────
 *  <MarketFloorEyebrowRail/>  ·  v3 "Living Eyebrow"
 *
 *  A breathing organism made of seven coordinated motion layers, every
 *  one of them themed to the active accent so the rail never reads as
 *  neutral gray on any palette:
 *
 *    1.  Outer anchor rings · slow breath (4.6s) + 360°/72s drift
 *    2.  Left hairline base · drifting accent gradient (10s loop)
 *    3.  Left hairline photon · bright pixel traveling INWARD toward
 *        the title every 5.7s — pulls energy into the headline
 *    4.  Pip pings · radar halos expanding outward every 2.4s, staggered
 *        180° between left and right so the deck always has one alive
 *    5.  Letter shimmer · diagonal accent gradient sweeping through the
 *        clipped glyphs of THE FLIGHT DECK on a 6.4s irrational period
 *    6.  Letter-spacing breath · 0.31em → 0.335em → 0.31em on 4.8s,
 *        out of phase with the shimmer for incommensurable cadence
 *    7.  Right hairline · mirror of (2)+(3) on 6.3s — never lock-step
 *
 *  The pairwise irrational periods (2.4 · 4.6 · 4.8 · 5.7 · 6.3 · 6.4 ·
 *  10 · 72) guarantee the rail never visually loops — exactly the
 *  cockpit feeling of "alive without moving the mouse".
 * ─────────────────────────────��─────────────────────────────────────── */
function MarketFloorEyebrowRail() {
  const accent = useThemeAccent().primary
  /* Stable id per accent so keyframes that depend on the active rgb
     are kept distinct in the document CSS — when the theme changes,
     a fresh keyframe set is generated and the previous one is GC'd. */
  const kfId = useId().replace(/[:]/g, "")
  const rgb = accent.rgb
  /* Injected via dangerouslySetInnerHTML, NOT as a text child: the server
     HTML-escapes text children (" → &quot;, ' → &#x27;) but browsers parse
     <style> as raw text, so the quotes inside the CSS comments below made
     the DOM differ from the client render → hydration mismatch → the whole
     dashboard Suspense boundary fell back to client rendering. */
  const railCss = `
        @keyframes mferail-hair-${kfId} {
          0%   { background-position: 0% 50%; }
          50%  { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        @keyframes mferail-photon-l-${kfId} {
          0%   { left: -8%;  opacity: 0; }
          15%  { opacity: 1; }
          85%  { opacity: 1; }
          100% { left: 102%; opacity: 0; }
        }
        @keyframes mferail-photon-r-${kfId} {
          0%   { right: -8%;  opacity: 0; }
          15%  { opacity: 1; }
          85%  { opacity: 1; }
          100% { right: 102%; opacity: 0; }
        }
        @keyframes mferail-ping-${kfId} {
          0%   { transform: scale(0.6); opacity: 0.55; }
          80%  { transform: scale(2.6); opacity: 0;    }
          100% { transform: scale(2.6); opacity: 0;    }
        }
        @keyframes mferail-shimmer-${kfId} {
          0%   { background-position: -150% 50%; }
          100% { background-position:  250% 50%; }
        }
        @keyframes mferail-letterbreath-${kfId} {
          0%   { letter-spacing: 0.31em;  text-shadow: 0 0 10px rgba(${rgb}, 0.30); }
          50%  { letter-spacing: 0.335em; text-shadow: 0 0 18px rgba(${rgb}, 0.55); }
          100% { letter-spacing: 0.31em;  text-shadow: 0 0 10px rgba(${rgb}, 0.30); }
        }
        @keyframes mferail-anchor-${kfId} {
          0%   { transform: scale(1);    box-shadow: 0 0 4px rgba(${rgb}, 0.25); }
          50%  { transform: scale(1.18); box-shadow: 0 0 9px rgba(${rgb}, 0.55); }
          100% { transform: scale(1);    box-shadow: 0 0 4px rgba(${rgb}, 0.25); }
        }
        @keyframes mferail-anchor-spin-${kfId} {
          0%   { transform: rotate(0deg);   }
          100% { transform: rotate(360deg); }
        }
        /* ── Ghost streams ──
           A copy of "THE FLIGHT DECK" travels across the rail at low
           opacity. mferail-ghost-lr enters from the LEFT edge (the
           ghost's right edge starts at the rail's left edge), passes
           BEHIND the static centered title, and exits off the right.
           mferail-ghost-rl is the mirror — enters from right, exits
           left. Opacity envelopes brighten the ghost in the hair zones
           and dim it near center so the static title is never visually
           overpowered.  Periods are coprime (8.7s vs 10.3s) so the two
           streams NEVER coincide in space, producing a continuous
           "data conveyor" feel without a perceptible loop. */
        @keyframes mferail-ghost-lr-${kfId} {
          0%   { left: -55%; opacity: 0; }
          12%  { opacity: 0.28; }
          42%  { opacity: 0.10; }   /* dims as it approaches center */
          50%  { opacity: 0.06; }   /* faintest under the title    */
          58%  { opacity: 0.10; }
          88%  { opacity: 0.28; }
          100% { left: 155%; opacity: 0; }
        }
        @keyframes mferail-ghost-rl-${kfId} {
          0%   { left: 155%; opacity: 0; }
          12%  { opacity: 0.28; }
          42%  { opacity: 0.10; }
          50%  { opacity: 0.06; }
          58%  { opacity: 0.10; }
          88%  { opacity: 0.28; }
          100% { left: -55%; opacity: 0; }
        }
        @media (prefers-reduced-motion: reduce) {
          .mferail-anim-${kfId} { animation: none !important; }
        }
      `
  return (
    /* Two-row band:
         · row 1 · `ghost-track` (h-[18px], overflow-hidden) — the two
             traveling "THE FLIGHT DECK" copies live here so the scan
             passes OVER the static title visually (above it), instead
             of colliding with it on the same baseline as before.
         · row 2 · main rail row (anchors + hairlines + big static title)
       The keyframes are unchanged — the ghosts still animate `left`
       from −55% → 155% across the full rail width, but they're now
       confined to the slim track on top.                            */
    /* `mb-1` (was `mb-3`) — pulls "Welcome back, Marcus." up so it
       reads as the immediate subordinate of the FLIGHT DECK rail
       above instead of floating in a band of dead vertical space.
       The rail's lower hairlines + side anchor dots already supply
       a soft separator so a 4px gap is plenty. */
    <div className="relative mb-1 select-none">
      {/* ── Inline keyframes scoped to this rail ──
          Defined once per accent. A plain <style> tag is safe here because
          every selector is uniquely namespaced with `kfId`. */}
      <style dangerouslySetInnerHTML={{ __html: railCss }} />

      {/* ────────────────────────────���───────────────────────���────────────
            MAIN RAIL ROW · single-row variant
          ──────────────────────��───��────────────���─────────────────────────
            We previously stacked TWO rows here: a tall "ghost track"
            containing two travelling "THE FLIGHT DECK" copies that
            scanned the rail edge-to-edge, plus this main row. The ghost
            track has been REMOVED per the design directive — those
            travelling copies were duplicating information already
            carried by the static centered title, costing ~22px of
            vertical space the cockpit can't afford. The keyframes for
            the ghosts (mferail-ghost-lr / -rl) are still declared in
            the <style/> block above and are simply unused now — kept
            in place so any future revival is a one-element add, not a
            CSS re-author.                                            */}
      <div className="relative flex items-center gap-3 overflow-hidden">

      {/* ── Outer LEFT anchor — breathing tinted ring with slow spinner �� */}
      <span
        aria-hidden
        className="shrink-0 relative"
        style={{ width: 6, height: 6 }}
      >
        <span
          className={`mferail-anim-${kfId} absolute inset-0 rounded-full`}
          style={{
            border: `1px solid ${vgRgba(rgb, 0.55)}`,
            background: vgRgba(rgb, 0.06),
            animation: `mferail-anchor-${kfId} 4.6s ease-in-out infinite`,
          }}
        />
        {/* A faint tick that rotates so the ring isn't perfectly symmetric */}
        <span
          className={`mferail-anim-${kfId} absolute inset-0`}
          style={{
            background: `conic-gradient(from 0deg, transparent 0deg, ${vgRgba(rgb, 0.6)} 25deg, transparent 50deg, transparent 360deg)`,
            borderRadius: "50%",
            mask: "radial-gradient(circle, transparent 55%, #000 56%, #000 100%)",
            WebkitMask: "radial-gradient(circle, transparent 55%, #000 56%, #000 100%)",
            animation: `mferail-anchor-spin-${kfId} 72s linear infinite`,
          }}
        />
      </span>

      {/* ── LEFT hairline — drifting accent gradient + inward photon ──── */}
      <span
        aria-hidden
        className="relative flex-1 shrink overflow-hidden"
        style={{ height: 1 }}
      >
        {/* Base layer: long gradient sliding across its container so the
            tint subtly drifts left↔right on a 10s loop — it's the
            "breathing of the wire". */}
        <span
          className={`mferail-anim-${kfId} absolute inset-0`}
          style={{
            backgroundImage: `linear-gradient(
              90deg,
              ${vgRgba(rgb, 0.04)} 0%,
              ${vgRgba(rgb, 0.12)} 25%,
              ${vgRgba(rgb, 0.32)} 55%,
              ${vgRgba(rgb, 0.55)} 100%
            )`,
            backgroundSize: "260% 100%",
            animation: `mferail-hair-${kfId} 10s ease-in-out infinite`,
          }}
        />
        {/* Photon — a bright pixel traveling left→right (INWARD toward
            the title). Visually pulls energy into the headline. */}
        <span
          className={`mferail-anim-${kfId} absolute`}
          style={{
            top: -1,
            bottom: -1,
            width: 28,
            background: `linear-gradient(90deg, transparent 0%, ${vgRgba(rgb, 0.95)} 50%, transparent 100%)`,
            filter: `drop-shadow(0 0 4px rgba(${rgb}, 0.8))`,
            animation: `mferail-photon-l-${kfId} 5.7s cubic-bezier(0.32, 0.04, 0.32, 1) infinite`,
          }}
        />
      </span>

      {/* ── CENTER cluster: ping · headline · ping ─────────────���───────���─
            The bigger title (fontSize 17) is naturally centered between
            the two outer anchor dots because the two `flex-1` hairlines
            on either side absorb equal amounts of horizontal slack. The
            inner pip dots are sized in proportion to the new title
            (7×7 instead of the old 5×5) so the whole cluster reads as a
            single unit rather than a giant word hugged by tiny specks. */}
      <span className="relative inline-flex items-center gap-3 shrink-0">
        {/* LEFT pip — solid dot + radar ping halo, phase 0 */}
        <span className="relative inline-block" style={{ width: 7, height: 7 }} aria-hidden>
          <span
            className={`mferail-anim-${kfId} absolute inset-0 rounded-full`}
            style={{
              border: `1px solid ${vgRgba(rgb, 0.7)}`,
              animation: `mferail-ping-${kfId} 2.4s cubic-bezier(0, 0, 0.2, 1) infinite`,
            }}
          />
          <span
            className="absolute inset-0 rounded-full"
            style={{
              background: accent.hex,
              boxShadow: `0 0 10px ${vgRgba(rgb, 0.85)}`,
            }}
          />
        </span>

        {/* THE FLIGHT DECK — three coordinated layers:
              · base solid accent for legibility + a11y
              · diagonal accent gradient sweep clipped to glyphs
              · letter-spacing + glow breath on a 4.8s cycle
            Title size bumped 10.5 → 17 so it reads as a real section
            header, not a chip caption. Letter-spacing kept at 0.32em
            so the glyphs stay airy at the new size.

            ── CLICK-TO-OPEN HUB ────────────────────────────���────────
            The visible "Flight Deck · LOADOUT ▾" pill below the
            cartouche has been retired. This big rail title is now
            the single trigger that opens the same hub popover
            (loadout + add gadget). Implementation: an outer
            `<button>` wraps the existing styled title span, ALL of
            its visual chrome (gradient sweep, breath animation,
            shimmer overlay) is preserved unchanged, and a
            `window.dispatchEvent` toggles the chip's open state via
            the `flight-deck-hub:toggle` CustomEvent it listens to.
            The button has zero padding / zero background / zero
            border / no focus ring distortion — only a `cursor:
            pointer` so it feels live, and an `aria-label` for
            screen-reader users. */}
        <button
          type="button"
          aria-label="Open flight-deck controls (loadout + add gadget)"
          onClick={() => {
            if (typeof window !== "undefined") {
              window.dispatchEvent(new CustomEvent("flight-deck-hub:toggle"))
            }
          }}
          className="relative inline-block whitespace-nowrap focus-visible:outline-none"
          style={{
            lineHeight: 1,
            background: "transparent",
            border: "none",
            padding: 0,
            margin: 0,
            cursor: "pointer",
            color: "inherit",
          }}
        >
          {/* (a) Base layer — visible text, semantic */}
          <span
            className={`mferail-anim-${kfId} font-mono uppercase whitespace-nowrap`}
            style={{
              fontSize: 17,
              letterSpacing: "0.32em",
              color: accent.hex,
              fontWeight: 500,
              display: "inline-block",
              animation: `mferail-letterbreath-${kfId} 4.8s ease-in-out infinite`,
            }}
          >
            THE FLIGHT DECK
          </span>
          {/* (b) Shimmer overlay — same glyphs, but the fill is a
                 diagonal accent gradient that sweeps across on a 6.4s
                 irrational period. `background-clip: text` keeps the
                 sweep inside the letters; `mix-blend-mode: screen`
                 lifts only the highlight without darkening the base. */}
          <span
            aria-hidden
            className={`mferail-anim-${kfId} font-mono uppercase whitespace-nowrap`}
            style={{
              position: "absolute",
              inset: 0,
              fontSize: 17,
              letterSpacing: "0.32em",
              fontWeight: 500,
              backgroundImage: `linear-gradient(
                110deg,
                transparent 0%,
                transparent 38%,
                rgba(255, 255, 255, 0.92) 50%,
                ${vgRgba(rgb, 0.95)} 55%,
                transparent 70%,
                transparent 100%
              )`,
              backgroundSize: "260% 100%",
              backgroundClip: "text",
              WebkitBackgroundClip: "text",
              color: "transparent",
              WebkitTextFillColor: "transparent",
              mixBlendMode: "screen",
              pointerEvents: "none",
              animation: `mferail-shimmer-${kfId} 6.4s cubic-bezier(0.55, 0, 0.45, 1) infinite`,
            }}
          >
            THE FLIGHT DECK
          </span>
        </button>

        {/* RIGHT pip — mirrored, phase 180° (1.2s offset) so the two pips
            never ping at the same time → the field always has one alive */}
        <span className="relative inline-block" style={{ width: 7, height: 7 }} aria-hidden>
          <span
            className={`mferail-anim-${kfId} absolute inset-0 rounded-full`}
            style={{
              border: `1px solid ${vgRgba(rgb, 0.7)}`,
              animation: `mferail-ping-${kfId} 2.4s cubic-bezier(0, 0, 0.2, 1) -1.2s infinite`,
            }}
          />
          <span
            className="absolute inset-0 rounded-full"
            style={{
              background: accent.hex,
              boxShadow: `0 0 10px ${vgRgba(rgb, 0.85)}`,
            }}
          />
        </span>
      </span>

      {/* ��─ RIGHT hairline — mirror of left; photon travels INWARD (R→L)
            on its own 6.3s period so left & right are never in lock-step */}
      <span
        aria-hidden
        className="relative flex-1 shrink overflow-hidden"
        style={{ height: 1 }}
      >
        <span
          className={`mferail-anim-${kfId} absolute inset-0`}
          style={{
            backgroundImage: `linear-gradient(
              90deg,
              ${vgRgba(rgb, 0.55)} 0%,
              ${vgRgba(rgb, 0.32)} 45%,
              ${vgRgba(rgb, 0.12)} 75%,
              ${vgRgba(rgb, 0.04)} 100%
            )`,
            backgroundSize: "260% 100%",
            animation: `mferail-hair-${kfId} 10s ease-in-out infinite reverse`,
          }}
        />
        <span
          className={`mferail-anim-${kfId} absolute`}
          style={{
            top: -1,
            bottom: -1,
            width: 28,
            background: `linear-gradient(90deg, transparent 0%, ${vgRgba(rgb, 0.95)} 50%, transparent 100%)`,
            filter: `drop-shadow(0 0 4px rgba(${rgb}, 0.8))`,
            animation: `mferail-photon-r-${kfId} 6.3s cubic-bezier(0.32, 0.04, 0.32, 1) infinite`,
          }}
        />
      </span>

      {/* ── Outer RIGHT anchor — breath out-of-phase (1.4s) + counter-spin */}
      <span
        aria-hidden
        className="shrink-0 relative"
        style={{ width: 6, height: 6 }}
      >
        <span
          className={`mferail-anim-${kfId} absolute inset-0 rounded-full`}
          style={{
            border: `1px solid ${vgRgba(rgb, 0.55)}`,
            background: vgRgba(rgb, 0.06),
            animation: `mferail-anchor-${kfId} 4.6s ease-in-out -1.4s infinite`,
          }}
        />
        <span
          className={`mferail-anim-${kfId} absolute inset-0`}
          style={{
            background: `conic-gradient(from 180deg, transparent 0deg, ${vgRgba(rgb, 0.6)} 25deg, transparent 50deg, transparent 360deg)`,
            borderRadius: "50%",
            mask: "radial-gradient(circle, transparent 55%, #000 56%, #000 100%)",
            WebkitMask: "radial-gradient(circle, transparent 55%, #000 56%, #000 100%)",
            animation: `mferail-anchor-spin-${kfId} 72s linear infinite reverse`,
          }}
        />
      </span>
      </div>{/* /MAIN RAIL ROW */}
    </div>
  )
}

/* ════════════════════════════════════════════════���═══════��═════��═════════��═══
 *  THE TRADER CARTOUCHE — Welcome Band v3
 *  
 *  A heraldic frame around the trader's name. The headline "Welcome back,
 *  Marcus." is the centerpiece; two flanking wings of 3 customizable
 *  badges each carry the trader's identity, performance, and activity.
 *  
 *  Composition (grid 1fr · auto · 1fr):
 *  
 *     ┌── LEFT WING ──┐                                    ┌── RIGHT WING ──┐
 *     │ ◆ Identity     │ ─┐                            ┌─ │ ◆ Equity Beacon │
 *     │ ◆ Last 5       │  │   Welcome back, Marcus.    │  │ ◆ Best Pair     │
 *     │ ◆ Discipline   │ ─┘   Where would you like…    └─ │ ◆ Session Clock │
 *     └────────────────┘                                    └─────────────────┘
 *  
 *  - 10 visual archetypes (Identity, Beacon, Streak, Sparkline, Pair, Ring,
 *    Clock, Macro, Goal, LastTrade) → a constellation of instruments, not a
 *    uniform list.
 *  - Hover pencil per slot → catalog popover → swap any badge in any slot.
 *  - Persistence via `useWelcomeBadgeConfig` (localStorage, storage adapter
 *    designed for a one-swap upgrade to Supabase per-user table).
 *  - All animations pairwise irrational so the cartouche never visually
 *    loops. Theme-tinted via `useThemeAccent()` — retints in lockstep with
 *    Teal / Cyber / Neural / Quantum / Solar / Light / Obsidian.
 *  - `prefers-reduced-motion` collapses everything to a still composition.
 * ══════════════════════════════════════��════════════════════════════════════ */

/* ── TraderTelemetry · the single source-of-truth shape ───────────────── */
interface TraderTelemetry {
  trader:     { name: string; tier: string }
  firm:       { name: string; phase: string; day: number; daysLeft: number }
  desk:       { city: string; region: string }
  accounts:   { live: number }
  equity:     { total: number; mtdPct: number }
  performance:{ winRate: number; accuracy: number; profitFactor: number; avgR: number; consistency: number }
  bestPair:   { name: string; winRate: number }
  worstPair:  { name: string; winRate: number }
  bestSetup:  { name: string; winRate: number }
  bestSession:{ name: string; winRate: number }
  discipline: { score: number; level: string; consecutiveLosses: number; revengeRisk: string }
  streak:     { count: number; type: "win" | "loss" | "neutral" }
  plan:       { tradesUsed: number; tradesMax: number; lossUsed: number; lossMax: number; focusPairs: readonly string[] }
  macro:      { event: string; time: string; impact: "high" | "medium" | "low"; currency: string }
  session:    { name: string; opensIn: string; isOpen: boolean }
  recentTrades: readonly RecentTrade[]
  goals:      ReadonlyArray<{ id: string; title: string; progress: number; milestoneLabel: string }>
  sparkline:  readonly number[]
}

function useTraderTelemetry(): TraderTelemetry {
  /* Aggregate live-account equity from the ACCOUNTS dataset (excludes demo). */
  const liveAccounts = useMemo(() => ACCOUNTS.filter((a) => a.type !== "demo"), [])
  const totalEquity  = useMemo(() => liveAccounts.reduce((s, a) => s + a.equity, 0), [liveAccounts])

  return useMemo<TraderTelemetry>(() => ({
    trader:      { name: "Marcus", tier: "Founder" },
    firm:        { name: "FTMO 50K", phase: "2 / 2", day: 47, daysLeft: 14 },
    desk:        { city: "New York", region: "US · NY" },
    accounts:    { live: liveAccounts.length },
    equity:      { total: totalEquity, mtdPct: 18.3 },
    performance: {
      winRate:       PERFORMANCE.winRate,
      accuracy:      PERFORMANCE.accuracy,
      profitFactor:  PERFORMANCE.profitFactor,
      avgR:          PERFORMANCE.averageRR,
      consistency:   PERFORMANCE.consistencyScore,
    },
    bestPair:    PERFORMANCE.bestPair,
    worstPair:   { name: PERFORMANCE.worstPair.name, winRate: PERFORMANCE.worstPair.winRate },
    bestSetup:   { name: PERFORMANCE.bestSetup.name, winRate: PERFORMANCE.bestSetup.winRate },
    bestSession: PERFORMANCE.bestSession,
    discipline: {
      score:             PSYCHOLOGY.disciplineScore,
      level:             PSYCHOLOGY.disciplineLevel,
      consecutiveLosses: PSYCHOLOGY.consecutiveLosses,
      revengeRisk:       PSYCHOLOGY.revengeTradingRisk,
    },
    streak: {
      count: AI_CHECKIN.stateSummary.currentStreak.count,
      type:  AI_CHECKIN.stateSummary.currentStreak.type as "win" | "loss" | "neutral",
    },
    plan: {
      tradesUsed: DAILY_PLAN.tradesUsed,
      tradesMax:  DAILY_PLAN.maxTrades,
      lossUsed:   DAILY_PLAN.dailyLossUsed,
      lossMax:    DAILY_PLAN.maxDailyLoss,
      focusPairs: DAILY_PLAN.focusPairs,
    },
    macro: (() => {
      const first = DAILY_PLAN.macroEvents[0]
      return {
        event:    first?.event    ?? "—",
        time:     first?.time     ?? "—",
        impact:   (first?.impact  ?? "low") as "high" | "medium" | "low",
        currency: first?.currency ?? "—",
      }
    })(),
    session: {
      name:    AI_CHECKIN.sessionInfo.name,
      opensIn: AI_CHECKIN.sessionInfo.opensIn,
      isOpen:  AI_CHECKIN.sessionInfo.isOpen,
    },
    recentTrades: RECENT_TRADES,
    goals: PERSONAL_GOALS.map((g) => ({
      id: g.id, title: g.title, progress: g.progress, milestoneLabel: g.milestoneLabel,
    })),
    sparkline: PERFORMANCE.sparkline,
  }), [liveAccounts, totalEquity])
}

/* ── Shared sub-atoms · the typographic primitives every archetype uses ─ */
const CARTOUCHE_RED  = "#ff5c6d"
const CARTOUCHE_GREEN= "#22d3a3"

/** Tiny mono-caps eyebrow ("WIN RATE", "DESK", etc.) — the field label. */
function BadgeEyebrow({ children, alignment }: { children: React.ReactNode; alignment: "left" | "right" }) {
  return (
    <span
      className="font-mono uppercase block tabular-nums"
      style={{
        fontSize: 9.5,
        letterSpacing: "0.24em",
        color: VG_VT.ashSoft,
        textAlign: alignment === "left" ? "right" : "left",
        lineHeight: 1,
      }}
    >
      {children}
    </span>
  )
}

/** Large accent-tinted number (the "$113,866", "72%", "+18.3%" etc.). */
function BadgeBig({
  children, accent, alignment, glow = true,
}: { children: React.ReactNode; accent: ThemeAccent; alignment: "left" | "right"; glow?: boolean }) {
  return (
    <span
      className="font-sans tabular-nums block"
      style={{
        fontSize: 22,
        lineHeight: 1.05,
        fontWeight: 500,
        letterSpacing: "-0.018em",
        color: accent.hex,
        textShadow: glow ? `0 0 14px ${vgRgba(accent.rgb, 0.32)}` : "none",
        textAlign: alignment === "left" ? "right" : "left",
        marginTop: 4,
      }}
    >
      {children}
    </span>
  )
}

/** Faint sub-line ("Capital live", "Stops respected") — the qualifier. */
function BadgeSub({ children, alignment }: { children: React.ReactNode; alignment: "left" | "right" }) {
  return (
    <span
      className="font-sans block"
      style={{
        fontSize: 10.5,
        lineHeight: 1.3,
        color: VG_VT.ashSoft,
        textAlign: alignment === "left" ? "right" : "left",
        marginTop: 3,
        letterSpacing: "0.01em",
      }}
    >
      {children}
    </span>
  )
}

/* ─── ARCHETYPE 1 · IDENTITY ───────────────────────���──────────────────────
   Single-line mono-caps label · accent dot · accent value. Used for
   compact identity badges (DESK · NY, ACCTS · 4, TIER · FOUNDER). */
function IdentityBadge({
  label, value, accent, alignment, icon: Icon,
}: {
  label: string
  value: string
  accent: ThemeAccent
  alignment: "left" | "right"
  /** Lucide icon component. Typed loosely as ElementType to absorb the
      lucide-react `LucideIcon` shape without importing the type. */
  icon?: React.ElementType
}) {
  return (
    <div
      className="inline-flex items-center gap-2 whitespace-nowrap font-mono uppercase tabular-nums"
      style={{
        fontSize: 10.5,
        letterSpacing: "0.22em",
        flexDirection: alignment === "left" ? "row-reverse" : "row",
      }}
    >
      {Icon && (
        <Icon
          size={12}
          className="opacity-80"
          color={accent.hex}
        />
      )}
      <span style={{ color: VG_VT.ashSoft }}>{label}</span>
      <span
        aria-hidden
        className="rounded-full"
        style={{ width: 3, height: 3, background: vgRgba(accent.rgb, 0.55) }}
      />
      <span
        style={{
          color: accent.hex,
          fontWeight: 600,
          textShadow: `0 0 8px ${vgRgba(accent.rgb, 0.3)}`,
        }}
      >
        {value}
      </span>
    </div>
  )
}

/* ─── ARCHETYPE 2 · BEACON ──────────────────────────────────────��────────
   The signature look. Eyebrow label · big accent number · faint sub-line.
   Used for marquee performance values (EQUITY, MTD, WIN RATE, etc.). */
function BeaconBadge({
  eyebrow, big, sub, accent, alignment, big2,
}: {
  eyebrow: string
  big: string
  sub?: string
  accent: ThemeAccent
  alignment: "left" | "right"
  /** Optional secondary smaller value rendered after the big number (e.g. "·  +18.3%"). */
  big2?: string
}) {
  return (
    <div className="flex flex-col min-w-0" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
      <BadgeEyebrow alignment={alignment}>{eyebrow}</BadgeEyebrow>
      <span
        className="font-sans tabular-nums block"
        style={{
          fontSize: 22,
          lineHeight: 1.05,
          fontWeight: 500,
          letterSpacing: "-0.018em",
          color: accent.hex,
          textShadow: `0 0 14px ${vgRgba(accent.rgb, 0.32)}`,
          textAlign: alignment === "left" ? "right" : "left",
          marginTop: 4,
        }}
      >
        {big}
        {big2 && (
          <span
            className="font-sans tabular-nums"
            style={{
              fontSize: 12,
              marginLeft: 8,
              color: VG_VT.paperDim,
              letterSpacing: "0.02em",
              fontWeight: 400,
            }}
          >
            {big2}
          </span>
        )}
      </span>
      {sub && <BadgeSub alignment={alignment}>{sub}</BadgeSub>}
    </div>
  )
}

/* ─── ARCHETYPE 3 · STREAK ───────────────────────────────────────────────
   This is a DIRECT PORT of the forecast-hub popup's "Last 5 trades" cell
   (see components/forecast-hub/forecast-detail-intelligence.tsx, around
   the `Last 5 trades` Eyebrow). Exact same layout, exact same styling:

       grid grid-cols-5 gap-1.5     · 5 equal columns
       cell: minHeight 86, padding 8/6, radius 9, faint tone bg
       4 stacked lines inside:
         line 1 · pair (white, 11px, 600)
         line 2 · ▲/▼ TF (tinted, 9px uppercase)
         line 3 · result in R (tinted, 11px mono, 600)
         line 4 · daysAgo (ashGhost gray, 9px)
       legend below: "Latest call" ← → "5 calls ago"

   Mapped to the cartouche RecentTrade interface (won → outcome,
   recency → daysAgo). NO motion, NO halo sweep, NO hover lift —
   matches the popup verbatim. */
function StreakBadge({
  trades, accent, alignment,
}: { trades: readonly RecentTrade[]; accent: ThemeAccent; alignment: "left" | "right" }) {
  const wins   = trades.filter((t) => t.won).length
  const losses = trades.length - wins
  const summary = `${wins} wins · ${losses} losses`

  return (
    <div
      className="flex flex-col gap-3 w-full"
      style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}
    >
      <div
        className="flex items-baseline justify-between gap-2 w-full"
        style={{ flexDirection: alignment === "left" ? "row-reverse" : "row" }}
      >
        <BadgeEyebrow alignment={alignment}>Last 5 trades</BadgeEyebrow>
        <span
          className="font-mono tabular-nums"
          style={{ fontSize: 10, color: VG_VT.ashSoft, letterSpacing: "0.04em" }}
        >
          {summary}
        </span>
      </div>

      {/* 5-column grid · newest on the inner edge (toward the headline).
          Right-wing reverses order so chip[0] sits closest to "Welcome
          back, Marcus." — same reading direction as the wing text. */}
      <div className="grid grid-cols-5 gap-1.5 w-full">
        {(alignment === "left" ? [...trades].reverse() : trades).map((trade, i) => {
          /* `i === 0` in this rendered order is the newest call when the
             wing is right-aligned; for the left-aligned wing we already
             reversed the array, so the visual-leftmost chip is also the
             one carrying the "latest" treatment. */
          const isLatest = trades.indexOf(trade) === 0
          const isWin    = trade.won
          const tone     = isWin ? CARTOUCHE_GREEN : CARTOUCHE_RED
          const toneRgb  = isWin ? "34,211,163"   : "255,92,109"
          const rValue   = `${trade.rMultiple > 0 ? "+" : ""}${trade.rMultiple.toFixed(1)}R`
          const dirGlyph = trade.direction === "long" ? "▲" : "▼"

          const cellStyle: React.CSSProperties = {
            minHeight: 86,
            padding: "8px 6px",
            borderRadius: 9,
            background: `rgba(${toneRgb},0.05)`,
            border: `1px solid rgba(${toneRgb},${isLatest ? 0.30 : 0.16})`,
            boxShadow: isLatest
              ? `0 0 8px rgba(${toneRgb},0.16), 0 1px 0 rgba(255,255,255,0.04) inset`
              : `0 1px 0 rgba(255,255,255,0.03) inset`,
            cursor: "default",
          }

          return (
            <div
              key={trade.id ?? i}
              style={cellStyle}
              className="select-none"
              aria-label={`${trade.pair} ${trade.direction} ${trade.timeframe} ${rValue} ${trade.recency}`}
            >
              <div className="flex h-full flex-col items-center justify-between gap-0.5">
                {/* Line 1 · pair (white, bold) */}
                <span
                  className="font-sans tabular-nums"
                  style={{
                    fontSize: 11,
                    fontWeight: 600,
                    color: VG_VT.paper,
                    letterSpacing: "-0.01em",
                    lineHeight: 1.1,
                    whiteSpace: "nowrap",
                  }}
                >
                  {trade.pair}
                </span>

                {/* Line 2 · direction · timeframe (tinted, uppercase) */}
                <span
                  className="font-sans"
                  style={{
                    fontSize: 9,
                    fontWeight: 500,
                    color: tone,
                    letterSpacing: "0.04em",
                    textTransform: "uppercase",
                    lineHeight: 1,
                    whiteSpace: "nowrap",
                    opacity: 0.9,
                  }}
                >
                  {dirGlyph} {trade.timeframe}
                </span>

                {/* Line 3 · R result (mono, bold, tinted) */}
                <span
                  className="font-mono tabular-nums"
                  style={{
                    fontSize: 11,
                    fontWeight: 600,
                    color: tone,
                    letterSpacing: "-0.01em",
                    lineHeight: 1,
                    whiteSpace: "nowrap",
                  }}
                >
                  {rValue}
                </span>

                {/* Line 4 · recency */}
                <span
                  className="font-sans"
                  style={{
                    fontSize: 9,
                    fontWeight: 400,
                    color: VG_VT.paperDim,
                    letterSpacing: "-0.005em",
                    lineHeight: 1,
                    whiteSpace: "nowrap",
                  }}
                >
                  {trade.recency}
                </span>
              </div>
            </div>
          )
        })}
      </div>

      {/* Axis legend — left/right ordering is now unambiguous */}
      <div className="flex items-center justify-between -mt-0.5 w-full font-mono uppercase">
        <span style={{ fontSize: 9, color: VG_VT.paperDim, letterSpacing: "0.10em" }}>
          {alignment === "left" ? "5 calls ago" : "Latest call"}
        </span>
        <span style={{ fontSize: 9, color: VG_VT.paperDim, letterSpacing: "0.10em" }}>
          {alignment === "left" ? "Latest call" : "5 calls ago"}
        </span>
      </div>
    </div>
  )
}

/* ─── ARCHETYPE 4 · SPARKLINE ───────────────────────────────────────────
   30-day equity / accuracy curve with a riding accent dot. The curve
   is rendered inline-SVG so we can theme-tint stroke + glow in lockstep
   with the active accent. */
function SparklineBadge({
  eyebrow, sub, data, accent, alignment,
}: { eyebrow: string; sub: string; data: readonly number[]; accent: ThemeAccent; alignment: "left" | "right" }) {
  const id = useId().replace(/[:]/g, "")
  const w = 140, h = 36
  const min = Math.min(...data), max = Math.max(...data), range = max - min || 1
  const pts = data.map((v, i) => {
    const x = (i / (data.length - 1)) * w
    const y = h - ((v - min) / range) * h
    return [x, y] as const
  })
  const path = pts.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`).join(" ")
  const areaPath = `${path} L ${w},${h} L 0,${h} Z`
  return (
    <div className="flex flex-col" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
      <BadgeEyebrow alignment={alignment}>{eyebrow}</BadgeEyebrow>
      <svg
        width={w}
        height={h}
        viewBox={`0 0 ${w} ${h}`}
        style={{ marginTop: 4, display: "block" }}
        aria-hidden
      >
        <defs>
          <linearGradient id={`spark-fill-${id}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stopColor={accent.hex} stopOpacity={0.28} />
            <stop offset="100%" stopColor={accent.hex} stopOpacity={0} />
          </linearGradient>
        </defs>
        <path d={areaPath} fill={`url(#spark-fill-${id})`} />
        <path
          d={path}
          fill="none"
          stroke={accent.hex}
          strokeWidth={1.4}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ filter: `drop-shadow(0 0 4px ${vgRgba(accent.rgb, 0.5)})` }}
        />
        {/* Last-point dot */}
        <circle
          cx={pts[pts.length - 1][0]}
          cy={pts[pts.length - 1][1]}
          r={2.4}
          fill={accent.hex}
          style={{ filter: `drop-shadow(0 0 4px ${vgRgba(accent.rgb, 0.9)})` }}
        />
      </svg>
      <BadgeSub alignment={alignment}>{sub}</BadgeSub>
    </div>
  )
}

/* ─── ARCHETYPE 5 · PAIR ─────────���──────────────────────��───────────────
   Pair symbol large + win-rate beneath with a thin confidence bar.
   Used for BEST PAIR / WORST PAIR / FOCUS PAIRS. */
function PairBadge({
  eyebrow, pair, winRate, accent, alignment, polarity = "positive",
}: {
  eyebrow: string
  pair: string
  winRate: number
  accent: ThemeAccent
  alignment: "left" | "right"
  /** "negative" tints the bar red to flag a worst-pair badge. */
  polarity?: "positive" | "negative"
}) {
  const tint    = polarity === "negative" ? CARTOUCHE_RED : accent.hex
  const tintRgb = polarity === "negative" ? "255, 92, 109" : accent.rgb
  return (
    <div className="flex flex-col" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
      <BadgeEyebrow alignment={alignment}>{eyebrow}</BadgeEyebrow>
      <span
        className="font-sans block tabular-nums"
        style={{
          fontSize: 18,
          lineHeight: 1.1,
          fontWeight: 500,
          letterSpacing: "-0.01em",
          color: VG_VT.paper,
          marginTop: 4,
          textAlign: alignment === "left" ? "right" : "left",
        }}
      >
        {pair}{" "}
        <span style={{ color: tint, fontWeight: 600, textShadow: `0 0 10px rgba(${tintRgb}, 0.4)` }}>
          {winRate}%
        </span>
      </span>
      {/* Confidence bar */}
      <div
        className="relative overflow-hidden mt-2"
        style={{
          width: 96,
          height: 3,
          borderRadius: 2,
          background: vgRgba(accent.rgb, 0.10),
          alignSelf: alignment === "left" ? "flex-end" : "flex-start",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0, bottom: 0,
            left: alignment === "left" ? "auto" : 0,
            right: alignment === "left" ? 0 : "auto",
            width: `${Math.min(100, Math.max(0, winRate))}%`,
            background: `linear-gradient(90deg, transparent 0%, rgba(${tintRgb}, 0.85) 100%)`,
            boxShadow: `0 0 8px rgba(${tintRgb}, 0.6)`,
          }}
        />
      </div>
    </div>
  )
}

/* ─── ARCHETYPE 6 · RING ────────────────────────────────────────────────
   Radial discipline / consistency ring. Stroke draws on mount on a 0.9s
   ease-out, then stays. Center reads the score. Right column has eyebrow
   + qualitative level (GOOD / GREAT / AT-RISK). */
function RingBadge({
  eyebrow, score, level, accent, alignment,
}: { eyebrow: string; score: number; level: string; accent: ThemeAccent; alignment: "left" | "right" }) {
  const id = useId().replace(/[:]/g, "")
  const r = 18, c = 2 * Math.PI * r
  const offset = c * (1 - Math.max(0, Math.min(100, score)) / 100)
  return (
    <div
      className="flex items-center gap-3"
      style={{ flexDirection: alignment === "left" ? "row-reverse" : "row" }}
    >
      <div className="relative" style={{ width: 44, height: 44 }}>
        <style>{`
          @keyframes ring-draw-${id} {
            from { stroke-dashoffset: ${c.toFixed(2)}; }
            to   { stroke-dashoffset: ${offset.toFixed(2)}; }
          }
          @media (prefers-reduced-motion: reduce) {
            .ring-draw-${id} { animation: none !important; stroke-dashoffset: ${offset.toFixed(2)} !important; }
          }
        `}</style>
        <svg width={44} height={44} viewBox="0 0 44 44" aria-hidden>
          {/* Track */}
          <circle cx={22} cy={22} r={r} fill="none" stroke={vgRgba(accent.rgb, 0.14)} strokeWidth={2.4} />
          {/* Progress */}
          <circle
            className={`ring-draw-${id}`}
            cx={22} cy={22} r={r}
            fill="none"
            stroke={accent.hex}
            strokeWidth={2.4}
            strokeLinecap="round"
            strokeDasharray={c}
            strokeDashoffset={offset}
            transform="rotate(-90 22 22)"
            style={{
              filter: `drop-shadow(0 0 4px ${vgRgba(accent.rgb, 0.7)})`,
              animation: `ring-draw-${id} 0.9s cubic-bezier(0.22, 1, 0.36, 1) forwards`,
            }}
          />
        </svg>
        <span
          className="absolute inset-0 flex items-center justify-center font-sans tabular-nums"
          style={{
            fontSize: 13,
            fontWeight: 600,
            color: accent.hex,
            letterSpacing: "-0.01em",
            textShadow: `0 0 6px ${vgRgba(accent.rgb, 0.4)}`,
          }}
        >
          {Math.round(score)}
        </span>
      </div>
      <div className="flex flex-col" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
        <BadgeEyebrow alignment={alignment}>{eyebrow}</BadgeEyebrow>
        <span
          className="font-sans"
          style={{
            fontSize: 13,
            color: VG_VT.paper,
            marginTop: 3,
            fontWeight: 500,
            letterSpacing: "0.005em",
            textTransform: "capitalize",
          }}
        >
          {level}
        </span>
      </div>
    </div>
  )
}

/* ─── ARCHETYPE 7 · CLOCK ────���───────────────────────���──────────────────
   Session name + opens-in label. Accent dot pulses on a 4.2s loop. */
function ClockBadge({
  eyebrow, session, opensIn, isOpen, accent, alignment,
}: { eyebrow: string; session: string; opensIn: string; isOpen: boolean; accent: ThemeAccent; alignment: "left" | "right" }) {
  const id = useId().replace(/[:]/g, "")
  return (
    <div className="flex flex-col" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
      <BadgeEyebrow alignment={alignment}>{eyebrow}</BadgeEyebrow>
      <div
        className="inline-flex items-center gap-2 mt-1"
        style={{ flexDirection: alignment === "left" ? "row-reverse" : "row" }}
      >
        <style>{`
          @keyframes clock-pulse-${id} {
            0%, 100% { transform: scale(1);    opacity: 0.8; }
            50%      { transform: scale(1.35); opacity: 1;   }
          }
          @media (prefers-reduced-motion: reduce) {
            .clock-pulse-${id} { animation: none !important; }
          }
        `}</style>
        <span
          aria-hidden
          className={`clock-pulse-${id} rounded-full`}
          style={{
            width: 7, height: 7,
            background: isOpen ? CARTOUCHE_GREEN : accent.hex,
            boxShadow: `0 0 10px ${isOpen ? "rgba(34, 211, 163, 0.7)" : vgRgba(accent.rgb, 0.7)}`,
            animation: `clock-pulse-${id} 4.2s ease-in-out infinite`,
          }}
        />
        <span
          className="font-sans"
          style={{
            fontSize: 18,
            lineHeight: 1.1,
            fontWeight: 500,
            letterSpacing: "-0.01em",
            color: accent.hex,
            textShadow: `0 0 10px ${vgRgba(accent.rgb, 0.3)}`,
          }}
        >
          {session}
        </span>
      </div>
      <BadgeSub alignment={alignment}>{isOpen ? "Open now" : `Opens in ${opensIn}`}</BadgeSub>
    </div>
  )
}

/* ─── ARCHETYPE 8 · MACRO ─────────────────────────────��─────────────────
   Next high-impact event time + label + currency, impact dot before it. */
function MacroBadge({
  eyebrow, event, time, impact, currency, accent, alignment,
}: { eyebrow: string; event: string; time: string; impact: "high" | "medium" | "low"; currency: string; accent: ThemeAccent; alignment: "left" | "right" }) {
  const impactColor =
    impact === "high"   ? CARTOUCHE_RED :
    impact === "medium" ? "#f5a524"     :
                          VG_VT.ashSoft
  return (
    <div className="flex flex-col" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
      <BadgeEyebrow alignment={alignment}>{eyebrow}</BadgeEyebrow>
      <div
        className="inline-flex items-baseline gap-2 mt-1"
        style={{ flexDirection: alignment === "left" ? "row-reverse" : "row" }}
      >
        <span
          aria-hidden
          className="rounded-full"
          style={{
            width: 6, height: 6,
            background: impactColor,
            boxShadow: `0 0 8px ${impactColor}`,
            alignSelf: "center",
          }}
        />
        <span
          className="font-sans tabular-nums"
          style={{
            fontSize: 18,
            lineHeight: 1.1,
            fontWeight: 500,
            color: accent.hex,
            letterSpacing: "-0.01em",
            textShadow: `0 0 10px ${vgRgba(accent.rgb, 0.3)}`,
          }}
        >
          {time}
        </span>
        <span
          className="font-mono uppercase"
          style={{ fontSize: 9.5, letterSpacing: "0.18em", color: VG_VT.paperDim }}
        >
          {currency}
        </span>
      </div>
      <BadgeSub alignment={alignment}>{event}</BadgeSub>
    </div>
  )
}

/* ─── ARCHETYPE 9 · GOAL ──────────────────────────���─────────────────────
   Goal title + linear progress bar + milestone line. */
function GoalBadge({
  title, progress, milestoneLabel, accent, alignment,
}: { title: string; progress: number; milestoneLabel: string; accent: ThemeAccent; alignment: "left" | "right" }) {
  return (
    <div className="flex flex-col min-w-0" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
      <div
        className="inline-flex items-baseline gap-2"
        style={{ flexDirection: alignment === "left" ? "row-reverse" : "row" }}
      >
        <BadgeEyebrow alignment={alignment}>{title.toUpperCase()}</BadgeEyebrow>
        <span
          className="font-mono tabular-nums"
          style={{ fontSize: 10, color: accent.hex, letterSpacing: "0.08em", fontWeight: 600 }}
        >
          {progress}%
        </span>
      </div>
      <div
        className="relative overflow-hidden mt-2"
        style={{
          width: 130,
          height: 3,
          borderRadius: 2,
          background: vgRgba(accent.rgb, 0.10),
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0, bottom: 0,
            left: alignment === "left" ? "auto" : 0,
            right: alignment === "left" ? 0 : "auto",
            width: `${Math.min(100, Math.max(0, progress))}%`,
            background: `linear-gradient(90deg, transparent 0%, ${vgRgba(accent.rgb, 0.85)} 100%)`,
            boxShadow: `0 0 8px ${vgRgba(accent.rgb, 0.6)}`,
          }}
        />
      </div>
      <BadgeSub alignment={alignment}>{milestoneLabel}</BadgeSub>
    </div>
  )
}

/* ─── ARCHETYPE 10 · LAST TRADE ────────��────────────────────────────────
   Most recent trade as a single card: pair · TF · R · recency · arrow. */
function LastTradeBadge({
  trade, accent, alignment,
}: { trade: RecentTrade; accent: ThemeAccent; alignment: "left" | "right" }) {
  const isWin = trade.won
  const tint    = isWin ? CARTOUCHE_GREEN : CARTOUCHE_RED
  const tintRgb = isWin ? "34, 211, 163" : "255, 92, 109"
  return (
    <div
      className="flex items-center gap-3"
      style={{ flexDirection: alignment === "left" ? "row-reverse" : "row" }}
    >
      {/* R-multiple square */}
      <div
        className="flex items-center justify-center font-sans tabular-nums shrink-0"
        style={{
          width: 44, height: 44, borderRadius: 8,
          background: `linear-gradient(180deg, rgba(${tintRgb}, 0.16) 0%, rgba(${tintRgb}, 0.06) 100%)`,
          border: `1px solid rgba(${tintRgb}, 0.36)`,
          color: tint,
          fontSize: 14,
          fontWeight: 600,
          letterSpacing: "-0.01em",
          textShadow: `0 0 6px rgba(${tintRgb}, 0.5)`,
          boxShadow: `0 0 12px rgba(${tintRgb}, 0.18)`,
        }}
      >
        {trade.rMultiple > 0 ? "+" : ""}{trade.rMultiple.toFixed(1)}R
      </div>
      <div className="flex flex-col min-w-0" style={{ alignItems: alignment === "left" ? "flex-end" : "flex-start" }}>
        <BadgeEyebrow alignment={alignment}>LAST TRADE · {trade.recency.toUpperCase()}</BadgeEyebrow>
        <span
          className="font-sans"
          style={{
            fontSize: 14,
            color: VG_VT.paper,
            marginTop: 2,
            fontWeight: 500,
            letterSpacing: "0.005em",
          }}
        >
          {trade.pair}{" "}
          <span style={{ color: VG_VT.paperDim, fontWeight: 400 }}>
            · {trade.timeframe} · {trade.direction === "long" ? "Long" : "Short"}
          </span>
        </span>
      </div>
    </div>
  )
}

