const WELCOME_CATALOG_BY_ID: Record<string, BadgeDef> = WELCOME_BADGE_CATALOG.reduce(
  (acc, b) => { acc[b.id] = b; return acc },
  {} as Record<string, BadgeDef>,
)

/** Returns the badge def for an id, falling back to the first identity badge. */
function resolveBadge(id: string): BadgeDef {
  return WELCOME_CATALOG_BY_ID[id] ?? WELCOME_BADGE_CATALOG[0]
}

/* ═══════════════════════════════════════════════════════════════════════════
   ARCHIO · LIVING GADGET CATALOG
   ───────────────────────────────────────────────────────────────────────────
   The v2 catalog. Replaces the legacy WELCOME_BADGE_CATALOG. Each entry
   declares the gadget's id, label, blurb, size class, narrative category,
   and a `render(telemetry, accent, alignment)` adapter that translates
   the wide TraderTelemetry into the slim per-gadget data shape.

   Categories appear in the popover header in this fixed order so the
   reading rhythm is consistent: Identity → Activity → Performance →
   Discipline → Time → Macro → Goals.
   ═════════════════════════════════════════════════════════════��═════════════ */
type GadgetCategory =
  | "Identity"
  | "Activity"
  | "Performance"
  | "Discipline"
  | "Time"
  | "Macro"

interface LivingGadgetCatalogEntry {
  id:        string
  label:     string
  blurb:     string
  size:      GadgetSize
  category:  GadgetCategory
  /** Renders the gadget. The wing supplies alignment + accent + telemetry.
   *  `priority` toggles the gadget's amber halo + priority pip. */
  render: (
    telemetry: TraderTelemetry,
    accent:    ThemeAccent,
    alignment: "left" | "right",
    priority?: boolean,
  ) => React.ReactNode
}

/* ────────────────���────────────────────────────────────────────────────────
   ARCHIO · Per-gadget data adapters
   ───��──────────────────────────────────────��──────────────────────────────
   Each adapter projects the wide TraderTelemetry into the narrow shape
   that one gadget expects. Keep adapters PURE and ALLOCATION-LIGHT — they
   run on every parent render. Anything heavy (countdown timers, etc.) is
   moved to the gadget's own internal hooks.
   ─────��───────────────────────────��──────��─────────────��────────────── */

/** Map an account's `propFirm.phase` (lowercase enum) → terse label. */
function shortFirmPhase(phase: string): string {
  const p = phase.toLowerCase()
  if (p === "evaluation") return "EVAL · PHASE 1"
  if (p === "verification") return "VERIF · PHASE 2"
  if (p === "funded") return "FUNDED"
  return phase.toUpperCase()
}

/** Map a live account → ledger row shape required by Management Pulse. */
function mgmtData(t: TraderTelemetry): ManagementPulseData {
  /* Per-account ledger (live only). Sparkline binds on `id` from the
     synthesised ACCOUNT_SPARKLINES dictionary; if missing, we synthesise
     a flat tail so the chart never collapses. */
  const live = ACCOUNTS.filter((a) => a.type !== "demo")
  const ledger = live.map((a) => {
    const spark = ACCOUNT_SPARKLINES[a.id] ?? [a.equity, a.equity, a.equity, a.equity, a.equity, a.equity, a.equity, a.equity]
    return {
      id:        a.id,
      short:     a.label,
      fullName:  a.label,
      equity:    a.equity,
      dailyPnL:  (a as { dailyPnL?: number }).dailyPnL ?? 0,
      sparkline: spark,
    }
  })
  /* Largest account drives the LARGEST face. */
  const largestRow = [...ledger].sort((a, b) => b.equity - a.equity)[0]
  const largestAcc = largestRow
    ? live.find((a) => a.id === largestRow.id)
    : undefined
  /* Segment shares (up to 4) = each account's percent of total equity.
     Empty list collapses to a single "full bar" sentinel in the gadget. */
  const totalEquity = t.equity.total || 1
  const segmentShares = ledger
    .slice(0, 4)
    .map((row) => ({
      id:    row.id,
      pct:   row.equity / totalEquity,
      label: row.short,
    }))
  return {
    totalEquity:    t.equity.total,
    todayPnL:       2184,
    todayPct:       1.92,
    liveAccounts:   live.length,
    todaySparkline: TODAY_PNL_SPARKLINE_24H,
    ledger,
    largest: {
      short:    largestRow?.short ?? "—",
      pctShare: largestRow ? (largestRow.equity / totalEquity) * 100 : 0,
      phase:    shortFirmPhase(largestAcc?.propFirm?.phase ?? t.firm.phase),
      daysLeft: largestAcc?.propFirm?.daysLeftInPhase ?? t.firm.daysLeft,
    },
    segmentShares,
  }
}

function accuracyData(t: TraderTelemetry): AccuracyEngineData {
  /* Trend = current − value 30 days ago. Last value should equal the
     PERFORMANCE.accuracy figure by construction so the RING and TREND
     faces line up. */
  const first = ACCURACY_TREND_30D[0] ?? t.performance.accuracy
  return {
    accuracy:      t.performance.accuracy,
    accuracyTrend: t.performance.accuracy - first,
    trend30d:      ACCURACY_TREND_30D,
    last10Calls:   LAST_10_CALLS,
  }
}

function sessionData(t: TraderTelemetry): SessionClockworkData {
  /* Trading day = 24-hour band [0, 1]. We map UTC hours into the band
     for the trio + now position. SYD ≈ 22:00–07:00, LDN ≈ 07:00–16:00,
     NY ≈ 12:00–21:00. The current session.isOpen comes from telemetry. */
  const now = new Date()
  const utcMins = now.getUTCHours() * 60 + now.getUTCMinutes()
  const pos = utcMins / (24 * 60)
  const trio = [
    { code: "SYD", isOpen: utcMins >= 22 * 60 || utcMins < 7 * 60,
      status: utcMins >= 22 * 60 || utcMins < 7 * 60 ? "Open" : "Closed",
      windowStart: 22 / 24, windowEnd: 31 / 24 },
    { code: "LDN", isOpen: utcMins >= 7 * 60 && utcMins < 16 * 60,
      status: utcMins >= 7 * 60 && utcMins < 16 * 60 ? "Open" : "Closed",
      windowStart: 7 / 24, windowEnd: 16 / 24 },
    { code: "NY",  isOpen: utcMins >= 12 * 60 && utcMins < 21 * 60,
      status: utcMins >= 12 * 60 && utcMins < 21 * 60 ? "Open" : "Closed",
      windowStart: 12 / 24, windowEnd: 21 / 24 },
  ] as const
  /* Killzone (London KZ = 07:00–10:00 UTC). When inside, surface elapsed +
     window-length in seconds for the gadget's progress bar. */
  const kzStartMin = 7 * 60
  const kzEndMin = 10 * 60
  const inKz = utcMins >= kzStartMin && utcMins < kzEndMin
  return {
    sessionName: t.session.name,
    status:      t.session.isOpen
      ? (t.session.opensIn ? `Closes in ${t.session.opensIn}` : "Open")
      : `Opens in ${t.session.opensIn}`,
    isOpen:      t.session.isOpen,
    nextSession: t.session.isOpen ? undefined
      : { name: t.session.name, opensIn: t.session.opensIn },
    trio,
    nowPosition: pos,
    bestSession: [
      { code: "LDN", winRate: t.bestSession.winRate },
      { code: "NY",  winRate: Math.max(0, t.bestSession.winRate - 6.2) },
      { code: "SYD", winRate: Math.max(0, t.bestSession.winRate - 11.8) },
    ],
    killzone: inKz
      ? {
          label: "London KZ",
          elapsedSec: (utcMins - kzStartMin) * 60 + now.getUTCSeconds(),
          windowSec: (kzEndMin - kzStartMin) * 60,
        }
      : undefined,
  }
}

function disciplineData(t: TraderTelemetry): DisciplinePulseData {
  /* `streakDays` = "this many consecutive disciplined days". We map from
     the trade streak count when type is 'win', else default to 3 (the
     baseline narrative). */
  return {
    score:             t.discipline.score,
    level:             t.discipline.level,
    streakDays:        t.streak.type === "win" ? t.streak.count : 3,
    revengeRisk:       (t.discipline.revengeRisk.toLowerCase() === "high"
                          ? "high"
                          : t.discipline.revengeRisk.toLowerCase() === "medium"
                          ? "medium"
                          : "low") as "low" | "medium" | "high",
    consecutiveLosses: t.discipline.consecutiveLosses,
  }
}

function equityData(t: TraderTelemetry): EquityBeaconData {
  /* Project a 30-day equity curve from the 14-day daily P&L tail —
     synthetic but monotonic enough to read as "equity rising through
     the month". */
  const mtdAmount = EQUITY_DAILY_14D.reduce((s, x) => s + x, 0)
  const curve = EQUITY_DAILY_14D.map((_, i, arr) => {
    const base = t.equity.total - arr.reduce((s, x) => s + x, 0)
    return base + arr.slice(0, i + 1).reduce((s, x) => s + x, 0)
  })
  return {
    totalEquity: t.equity.total,
    mtdPct:      t.equity.mtdPct,
    mtdAmount,
    curve,
    daily14d:    EQUITY_DAILY_14D,
    todayPnL:    EQUITY_DAILY_14D[EQUITY_DAILY_14D.length - 1] ?? 0,
  }
}

function firmData(t: TraderTelemetry): FirmIdentityData {
  const phaseEndsAt = Date.now() + t.firm.daysLeft * 24 * 60 * 60 * 1000
  /* The narrative uses a $5,000 profit target on 10% of 50K; if the
     telemetry firm size grows, this still scales sanely. */
  const accountSize = 50000
  const profitTarget = accountSize * 0.10
  const profitAmount = (t.equity.mtdPct / 100) * accountSize
  /* The telemetry stores phase as "2 / 2" — we strip the "/ 2" suffix
     and any whitespace/dashes so the eyebrow reads as a clean
     "PHASE 2" rather than the messy "PHASE 2 / 2 · DAY 47". */
  const phaseNum = String(t.firm.phase).split("/")[0].replace(/[^\d]/g, "").trim()
  return {
    firmShort:    t.firm.name,
    phaseLabel:   `PHASE ${phaseNum || t.firm.phase}`,
    daysLeft:     t.firm.daysLeft,
    phaseEndsAt,
    profitPct:    Math.min(100, (profitAmount / profitTarget) * 100),
    profitAmount,
    profitTarget,
  }
}

function winRateData(t: TraderTelemetry): WinRateHeartData {
  /* Reconstruct wins/losses count from win rate + a fixed total of 58.
     The recentR feeds the PROFIT FACTOR face's dot strip. */
  const totalTrades = 58
  const wins   = Math.round((t.performance.winRate / 100) * totalTrades)
  const losses = totalTrades - wins
  const recentR: number[] = t.recentTrades.length
    ? t.recentTrades.map((tr) => tr.rMultiple)
    : [+0.7, -0.8, +2.9, -1.0, +2.3, +0.5, -0.4, +1.6, -0.7, +1.1]
  return {
    winRate: t.performance.winRate,
    totalTrades,
    wins,
    losses,
    profitFactor: t.performance.profitFactor,
    recentR,
  }
}

function bestPairLiveData(t: TraderTelemetry): BestPairData {
  return {
    bestPair:  { name: t.bestPair.name,  winRate: t.bestPair.winRate  },
    worstPair: { name: t.worstPair.name, winRate: t.worstPair.winRate,
                 aiHint: "Skip — drawdown in this pair" },
    bestSetup: { name: t.bestSetup.name, winRate: t.bestSetup.winRate },
  }
}

function macroData(t: TraderTelemetry): MacroPulseData {
  /* Anchor the next event to "today @ time" — the gadget's countdown
     hook just wants any Date/number. If the time has already passed,
     advance by a day so the countdown reads positive. */
  const at = parseTimeToDate(t.macro.time)
  return {
    next: {
      event:    t.macro.event,
      time:     t.macro.time,
      impact:   t.macro.impact,
      currency: t.macro.currency,
      at,
    },
    todays: EVENTS_TODAY,
  }
}

/** Tiny helper · "HH:MM UTC" → next future Date matching that time. */
function parseTimeToDate(time: string): Date {
  const m = /(\d{1,2}):(\d{2})/.exec(time)
  if (!m) return new Date(Date.now() + 60 * 60 * 1000)
  const hh = Number(m[1])
  const mm = Number(m[2])
  const d = new Date()
  d.setUTCHours(hh, mm, 0, 0)
  if (d.getTime() < Date.now()) d.setUTCDate(d.getUTCDate() + 1)
  return d
}

/* ── v2 expansion adapters ───────────────────────────────────────��──────── */

function riskEnvelopeData(t: TraderTelemetry): RiskEnvelopeData {
  /* plan.lossUsed/lossMax are the day's risk budget (in %). openRisk is the
     R currently exposed — derived from whether any recent trade is "today"
     and still implicitly live; we approximate with consecutiveLosses==0 calm
     read, falling back to 0 when flat. */
  return {
    lossUsed:   t.plan.lossUsed,
    lossMax:    t.plan.lossMax,
    tradesUsed: t.plan.tradesUsed,
    tradesMax:  t.plan.tradesMax,
    openRisk:   t.streak.type === "neutral" ? 0 : t.plan.lossUsed > 0 ? t.performance.avgR : 0,
  }
}

function dailyPlanData(t: TraderTelemetry): DailyPlanData {
  return {
    tradesUsed:  t.plan.tradesUsed,
    tradesMax:   t.plan.tradesMax,
    focusPairs:  t.plan.focusPairs,
    bias:        `Favor ${t.bestPair.name} · ${t.bestSession.name} killzone`,
    sessionName: t.bestSession.name,
  }
}

function goalsBeaconData(t: TraderTelemetry): GoalsBeaconData {
  return { goals: t.goals }
}


function lastTradesData(t: TraderTelemetry): Last5TradesData {
  /* Take 5 most-recent. RecentTrade already has the exact shape the
     gadget chip wants (pair / direction / rMultiple / recency / won). */
  return { trades: t.recentTrades.slice(0, 5) }
}

