    vs: "vs +$11,400 YTD prior", vsTone: "up", vsPct: "+148%",
    wins: 142, losses: 68, expR: "+0.54R / trade",
    avgWin: "+$346", avgLoss: "-$118",
    best:  { day: "MAR", pl: "+$6,210" },
