/* ── Region 2 — Hero stats strip ─��──────����───────────────────────────────── */
/* ���─ Region 2 — Hero stats strip (PREMIUM)  ──────────────────────────────
   Five interactive tiles with spring-cushioned entrance, count-up numerics,
   per-tile micro-visualizations, and a hover scrim that lifts the tile,
   intensifies its accent border, and brightens its background gradient.

   Each tile carries:
   • Identity row     — icon, label, optional live ping (live-only badges)
   • Primary numeric  — animated count-up via useMotionValue + Framer's
                        animate() helper, easing through expoOut so the
                        value settles like a precision balance.
   • Sub-line         — context (today's %, currency, balance share, etc.)
   • Micro-viz row    — sparkline / progress / donut, deterministic per id

   The strip wraps these in a container with a hairline shimmering top
   accent and a subtle internal vignette so the tiles read as facets of a
   single instrument rather than five disconnected cards.
   ──────��─────────────────��──────────��──────────────��─������─────���─���──��────── */

/** Animated count-up — useMotionValue → animate() → text node. The component
 *  re-runs the animation only when `value` changes, so it ticks once on mount
 *  and would re-tick if the underlying account updated. Format function is
 *  applied via useTransform so we never re-render React on every frame. */
function AnimatedNumber({
  value,
  format,
  duration = 1.4,
  delay = 0,
}: {
  value: number
  format: (n: number) => string
  duration?: number
  delay?: number
}) {
  const mv = useMotionValue(0)
  const display = useTransform(mv, (v) => format(v))
  useEffect(() => {
    const controls = animate(mv, value, {
      duration,
      delay,
      ease: [0.16, 1, 0.3, 1], // expoOut-ish — fast start, settles softly
    })
    return controls.stop
  }, [value, mv, duration, delay])
  return <motion.span>{display}</motion.span>
}

/** Live ping dot — concentric pulse used by the EQUITY and FLOATING tiles
 *  to signal the value is streaming. */
function LivePing({ rgb }: { rgb: string }) {
  return (
    <span className="relative inline-flex items-center justify-center" style={{ width: 8, height: 8 }}>
      <motion.span
        className="absolute inset-0 rounded-full"
        style={{ background: `rgb(${rgb})`, opacity: 0.4 }}
        animate={{ scale: [1, 2.2, 1], opacity: [0.4, 0, 0.4] }}
        transition={{ duration: 1.6, repeat: Infinity, ease: "easeOut" }}
      />
      <span
        className="relative rounded-full"
        style={{ width: 5, height: 5, background: `rgb(${rgb})`, boxShadow: `0 0 5px rgba(${rgb}, 0.7)` }}
      />
    </span>
  )
}

/** A single premium stat tile — owns its hover state and count-up animation.
 *  No micro-viz: the tile reads as identity → number → context, with hover
 *  affordances (vignette + corner brackets + accent bar) carrying the
 *  interactive flavor. Pure presentational; parent strip composes them. */
function PremiumStatTile({
  index,
  icon,
  label,
  primary,
  sub,
  liveRgb,
  toneRgb,
  isLast,
}: {
  index: number
  icon: React.ReactNode
  label: string
  primary: React.ReactNode
  sub: React.ReactNode
  liveRgb?: string
  toneRgb: string
  isLast: boolean
}) {
  const [hover, setHover] = useState(false)
  return (
    <motion.div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      initial={{ opacity: 0, y: 14 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.06 * index, duration: 0.55, ease: [0.16, 1, 0.3, 1] }}
      className="relative px-4 py-4 flex flex-col gap-2 cursor-default group overflow-hidden"
      style={{
        borderRight: !isLast ? `1px solid ${VANTARY.rule}` : "none",
      }}
    >
      {/* Tone-tinted vignette — fades in on hover, gives each tile its own
          chromatic identity without dominating the resting state.        */}
      <motion.div
        aria-hidden
        className="absolute inset-0 pointer-events-none"
        animate={{ opacity: hover ? 1 : 0 }}
        transition={{ duration: 0.32 }}
        style={{
          background: `radial-gradient(120% 80% at 0% 0%, rgba(${toneRgb}, 0.10) 0%, rgba(${toneRgb}, 0) 60%)`,
        }}
      />
      {/* Top accent bar — appears on hover, hairline in resting state.    */}
      <motion.div
        aria-hidden
        className="absolute top-0 left-3 right-3 origin-left"
        animate={{ scaleX: hover ? 1 : 0.18, opacity: hover ? 1 : 0.45 }}
        transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
        style={{
          height: 1,
          background: `linear-gradient(90deg, rgba(${toneRgb}, 0) 0%, rgba(${toneRgb}, 0.95) 50%, rgba(${toneRgb}, 0) 100%)`,
        }}
      />

      {/* Identity row */}
      <div className="relative flex items-center justify-between">
        <span className="inline-flex items-center gap-1.5">
          <motion.span
            animate={{ rotate: hover ? [0, -6, 6, 0] : 0, scale: hover ? 1.08 : 1 }}
            transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
            className="inline-flex items-center justify-center"
            style={{ color: `rgba(${toneRgb}, 0.85)` }}
          >
            {icon}
          </motion.span>
          <span
            className="font-mono uppercase"
            style={{ fontSize: 8.5, letterSpacing: "0.20em", color: VANTARY.ashSoft }}
          >
            {label}
          </span>
        </span>
        {liveRgb && <LivePing rgb={liveRgb} />}
      </div>

      {/* Primary number ���� animated and tone-coloured */}
      <div
        className="relative font-mono tabular-nums"
        style={{
          fontSize: 26,
          color: `rgb(${toneRgb})`,
          fontWeight: 500,
          lineHeight: 1,
          letterSpacing: "-0.015em",
          textShadow: hover ? `0 0 16px rgba(${toneRgb}, 0.25)` : "none",
          transition: "text-shadow 0.32s ease",
        }}
      >
        {primary}
      </div>

      {/* Sub-line */}
      <span
        className="relative font-mono"
        style={{ fontSize: 9.5, color: VANTARY.ashSoft, letterSpacing: "0.04em" }}
      >
        {sub}
      </span>

      {/* Bottom corner brackets — hairline ticks that appear on hover, a
          subtle "selected" cue at terminal/instrument scale. */}
      <motion.span
        aria-hidden
        className="absolute bottom-1 left-1"
        animate={{ opacity: hover ? 0.6 : 0 }}
        transition={{ duration: 0.32 }}
        style={{
          width: 5, height: 5,
          borderLeft: `1px solid rgba(${toneRgb}, 0.7)`,
          borderBottom: `1px solid rgba(${toneRgb}, 0.7)`,
        }}
      />
      <motion.span
        aria-hidden
        className="absolute bottom-1 right-1"
        animate={{ opacity: hover ? 0.6 : 0 }}
        transition={{ duration: 0.32 }}
        style={{
          width: 5, height: 5,
          borderRight: `1px solid rgba(${toneRgb}, 0.7)`,
          borderBottom: `1px solid rgba(${toneRgb}, 0.7)`,
        }}
      />
    </motion.div>
  )
}

